Below is the complete Terraform HCL program based on the provided IaC Intent Graph IR:

```hcl
provider "aws" {
  region = "us-east-1"  # Specify your desired AWS region
}

resource "aws_route53_zone" "primary" {
  name = "example.com"
}

resource "aws_cloudwatch_log_group" "aws_route53_example_com" {
  name              = "/aws/route53/example.com"
  retention_in_days = 30  # Set the desired retention period
}

resource "aws_iam_role" "route53_query_logging_role" {
  name = "route53-query-logging-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "route53.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "route53_query_logging_policy" {
  name        = "route53-query-logging-policy"
  description = "Policy for Route 53 to log to CloudWatch"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = aws_cloudwatch_log_group.aws_route53_example_com.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_route53_logging_policy_to_role" {
  role       = aws_iam_role.route53_query_logging_role.name
  policy_arn = aws_iam_policy.route53_query_logging_policy.arn
}

resource "aws_route53_query_log" "route53_query_log" {
  hosted_zone_id = aws_route53_zone.primary.zone_id
  cloudwatch_logs_log_group_arn = aws_cloudwatch_log_group.aws_route53_example_com.arn
}
```

