### Description
This Terraform program sets up a Route 53 hosted zone named "main" and configures a weighted routing policy to distribute traffic between a primary database instance and two replica database instances. The primary and replica database instances are created, and weighted Route 53 records are set up for each instance to ensure traffic is split accordingly.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "db_instance_class" {
  description = "The class of the database instance"
  default     = "db.t3.micro"
}

variable "db_engine" {
  description = "The database engine"
  default     = "mysql"
}

variable "db_name" {
  description = "The name of the database"
  default     = "mydatabase"
}

variable "db_username" {
  description = "The username for the database"
  default     = "admin"
}

variable "db_password" {
  description = "The password for the database"
  default     = "securepassword"
}

variable "zone_name" {
  description = "The name of the Route 53 zone"
  default     = "example.com"
}

resource "aws_route53_zone" "main_zone" {
  name = var.zone_name
}

resource "aws_db_instance" "primary_db_instance" {
  identifier              = "primary-db"
  instance_class          = var.db_instance_class
  engine                  = var.db_engine
  allocated_storage       = 20
  username                = var.db_username
  password                = var.db_password
  db_subnet_group_name    = "default"
  skip_final_snapshot     = true
  vpc_security_group_ids  = ["sg-12345678"]
}

resource "aws_db_instance" "replica_1_db_instance" {
  identifier              = "replica-1-db"
  instance_class          = var.db_instance_class
  engine                  = var.db_engine
  source_db_instance_identifier = aws_db_instance.primary_db_instance.identifier
  skip_final_snapshot     = true
  vpc_security_group_ids  = ["sg-12345678"]
}

resource "aws_db_instance" "replica_2_db_instance" {
  identifier              = "replica-2-db"
  instance_class          = var.db_instance_class
  engine                  = var.db_engine
  source_db_instance_identifier = aws_db_instance.primary_db_instance.identifier
  skip_final_snapshot     = true
  vpc_security_group_ids  = ["sg-12345678"]
}

resource "aws_route53_record" "weighted_record_primary" {
  zone_id = aws_route53_zone.main_zone.zone_id
  name    = "db.example.com"
  type    = "A"
  ttl     = 300

  weighted_routing_policy {
    weight = 100
  }

  records = [aws_db_instance.primary_db_instance.endpoint]
}

resource "aws_route53_record" "weighted_record_replica_1" {
  zone_id = aws_route53_zone.main_zone.zone_id
  name    = "db.example.com"
  type    = "A"
  ttl     = 300

  weighted_routing_policy {
    weight = 45
  }

  records = [aws_db_instance.replica_1_db_instance.endpoint]
}

resource "aws_route53_record" "weighted_record_replica_2" {
  zone_id = aws_route53_zone.main_zone.zone_id
  name    = "db.example.com"
  type    = "A"
  ttl     = 300

  weighted_routing_policy {
    weight = 45
  }

  records = [aws_db_instance.replica_2_db_instance.endpoint]
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **Variables**: Variables are defined for database instance class, engine, name, username, password, and zone name with default values.
- **Route 53 Zone**: A Route 53 hosted zone named "example.com" is created.
- **Database Instances**: Three database instances are created: one primary and two replicas. The replicas are configured to replicate from the primary instance.
- **Weighted Route 53 Records**: Weighted records are created for each database instance. The primary instance has a weight of 100, while each replica has a weight of 45, ensuring that traffic is split between the primary and replicas.

