### Description
The Terraform program below sets up an Elastic Beanstalk worker environment for running batch processing jobs. It includes the necessary AWS resources such as IAM roles, instance profiles, S3 buckets, S3 objects, SQS queues, Elastic Beanstalk applications, application versions, and environments. The resources are configured to ensure proper dependencies and security requirements.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# IAM Role for EC2 instances in Elastic Beanstalk
resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Instance Profile associated with the IAM role
resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  roles = [aws_iam_role.eb_ec2_role.name]
}

# S3 Bucket for storing application artifacts
resource "aws_s3_bucket" "sampleapril26426" {
  bucket = "sampleapril26426"
  acl    = "private"
}

# Object stored in the S3 bucket for application deployment
resource "aws_s3_object" "examplebucket_object" {
  bucket = aws_s3_bucket.sampleapril26426.bucket
  key    = "example-object.zip"
  source = "path/to/your/application/code.zip"
}

# SQS Queue for managing batch processing tasks
resource "aws_sqs_queue" "batch_job_queue" {
  name = "batch_job_queue"
}

# Elastic Beanstalk Application for hosting the batch processing environment
resource "aws_elastic_beanstalk_application" "batch_job_app" {
  name        = "batch_job_app"
  description = "Elastic Beanstalk application for batch processing"
}

# Application Version linked to the S3 object containing the application code
resource "aws_elastic_beanstalk_application_version" "version" {
  name        = "version"
  application = aws_elastic_beanstalk_application.batch_job_app.name
  bucket      = aws_s3_bucket.sampleapril26426.bucket
  key         = aws_s3_object.examplebucket_object.key
}

# Elastic Beanstalk Environment configured with the application, version, instance profile, and SQS queue
resource "aws_elastic_beanstalk_environment" "batch_job_env" {
  name                = "batch_job_env"
  application         = aws_elastic_beanstalk_application.batch_job_app.name
  version_label       = aws_elastic_beanstalk_application_version.version.name
  solution_stack_name = "64bit Amazon Linux 2 v3.6.0 running Multi-container Docker 20.10.17 on 64bit Amazon Linux 2"

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_instance_profile.eb_ec2_profile.name
  }

  setting {
    namespace = "aws:sqsd"
    name      = "QueueURL"
    value     = aws_sqs_queue.batch_job_queue.url
  }
}
```

### Notes
- Ensure that the IAM role `eb_ec2_role` has the necessary permissions for EC2 instances and other AWS services used in the Elastic Beanstalk environment.
- Replace `"path/to/your/application/code.zip"` with the actual path to your application code.
- Adjust the `solution_stack_name` in the `aws_elastic_beanstalk_environment` resource to match the appropriate stack for your application.

