provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# IAM Role for Elastic Beanstalk EC2 instances
resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Instance Profile associated with the IAM role
resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  roles = [aws_iam_role.eb_ec2_role.name]
}

# S3 Bucket to store application code
resource "aws_s3_bucket" "sampleapril26426" {
  bucket = "sampleapril26426"
  acl    = "private"
}

# Application code stored in S3 bucket
resource "aws_s3_object" "examplebucket_object" {
  bucket = aws_s3_bucket.sampleapril26426.bucket
  key    = "application.zip"
  source = "path/to/your/application.zip"  # Update with the path to your application code
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "myapp" {
  name        = "myapp"
  description = "My Elastic Beanstalk Application"
}

# Elastic Beanstalk Application Version
resource "aws_elastic_beanstalk_application_version" "version" {
  application = aws_elastic_beanstalk_application.myapp.name
  bucket      = aws_s3_bucket.sampleapril26426.bucket
  key         = aws_s3_object.examplebucket_object.key
  name        = "version"
}

# Elastic Beanstalk Environment
resource "aws_elastic_beanstalk_environment" "myapp_env" {
  name                = "myapp-env"
  application         = aws_elastic_beanstalk_application.myapp.name
  solution_stack_name = "64bit Amazon Linux 2 v3.6.2 running Python 3.9"  # Update with your desired solution stack
  version_label       = aws_elastic_beanstalk_application_version.version.name
  instance_profile    = aws_iam_instance_profile.eb_ec2_profile.name
}
```

### Notes
1. **IAM Role Permissions**: Ensure that the `aws_iam_role.eb_ec2_role` has the necessary permissions for Elastic Beanstalk and EC2. You may need to attach additional policies depending on your application's requirements.
2. **S3 Bucket and Object Policies**: The S3 bucket and object should have appropriate policies to allow Elastic Beanstalk to access the application code. This example assumes private access; adjust the ACL and policies as needed.
3. **Solution Stack Name**: Update the `solution_stack_name` in the `aws_elastic_beanstalk_environment` resource to match the appropriate stack for your application.
4. **Application Code Path**: Update the `source` attribute in the `aws_s3_object` resource to point to the correct path of your application code.

