### Description
This Terraform program sets up a Blue/Green deployment using AWS Elastic Beanstalk environments and AWS Route53 for traffic management. It includes:

1. **IAM Role and Policy**: An IAM role (`route53_update_role`) with a policy (`route53_update_policy`) that allows updating Route53 records.
2. **Elastic Beanstalk Environments**: Two environments named `blue_environment` and `green_environment`.
3. **Route53 Hosted Zone**: A hosted zone for the domain `example.com`.
4. **Weighted Route53 Records**: Two weighted records (`weighted_blue_record` and `weighted_green_record`) to manage traffic between the two Elastic Beanstalk environments.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# IAM Role for Route53 updates
resource "aws_iam_role" "route53_update_role" {
  name = "route53-update-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Route53 updates
resource "aws_iam_policy" "route53_update_policy" {
  name        = "route53-update-policy"
  description = "Policy to allow Route53 updates"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "route53:ChangeResourceRecordSets",
          "route53:GetHostedZone",
          "route53:ListResourceRecordSets"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_route53_policy_to_role" {
  role       = aws_iam_role.route53_update_role.name
  policy_arn = aws_iam_policy.route53_update_policy.arn
}

# Elastic Beanstalk Environment - Blue
resource "aws_elastic_beanstalk_environment" "blue_environment" {
  name                = "blue-environment"
  application         = var.elastic_beanstalk_application_name
  solution_stack_name = var.elastic_beanstalk_solution_stack_name
  instance_type       = var.instance_type
}

# Elastic Beanstalk Environment - Green
resource "aws_elastic_beanstalk_environment" "green_environment" {
  name                = "green-environment"
  application         = var.elastic_beanstalk_application_name
  solution_stack_name = var.elastic_beanstalk_solution_stack_name
  instance_type       = var.instance_type
}

# Route53 Hosted Zone
resource "aws_route53_zone" "example_com_zone" {
  name = "example.com"
}

# Weighted Route53 Record - Blue
resource "aws_route53_record" "weighted_blue_record" {
  zone_id = aws_route53_zone.example_com_zone.zone_id
  name    = "www.example.com"
  type    = "A"
  ttl     = 300

  weighted_routing_policy {
    weight = 50
  }

  alias {
    name                   = aws_elastic_beanstalk_environment.blue_environment.cname
    zone_id                = aws_elastic_beanstalk_environment.blue_environment.elb
    evaluate_target_health = true
  }
}

# Weighted Route53 Record - Green
resource "aws_route53_record" "weighted_green_record" {
  zone_id = aws_route53_zone.example_com_zone.zone_id
  name    = "www.example.com"
  type    = "A"
  ttl     = 300

  weighted_routing_policy {
    weight = 50
  }

  alias {
    name                   = aws_elastic_beanstalk_environment.green_environment.cname
    zone_id                = aws_elastic_beanstalk_environment.green_environment.elb
    evaluate_target_health = true
  }
}

# Variables
variable "elastic_beanstalk_application_name" {
  description = "Name of the Elastic Beanstalk application"
  default     = "my-application"
}

variable "elastic_beanstalk_solution_stack_name" {
  description = "Solution stack name for the Elastic Beanstalk environment"
  default     = "64bit Amazon Linux 2 v3.6.1 running Python 3.9"
}

variable "instance_type" {
  description = "EC2 instance type for the Elastic Beanstalk environment"
  default     = "t2.micro"
}
```

### Notes
- Ensure that the IAM policy grants necessary permissions for Route53 updates.
- The weighted routing policy is configured in the DNS records, with equal weights for both environments (`weight = 50`). Adjust these weights as needed to control traffic distribution.
- Replace the default values for `elastic_beanstalk_application_name`, `elastic_beanstalk_solution_stack_name`, and `instance_type` with your specific requirements.

