}

variable "environment_name_us_west" {
  description = "The name of the Elastic Beanstalk environment in us-west-2"
  type        = string
  default     = "us_west_env"
}

variable "environment_name_eu_central" {
  description = "The name of the Elastic Beanstalk environment in eu-central-1"
  type        = string
  default     = "eu_central_env"
}

resource "aws_iam_role" "beanstalk_role_us_west" {
  name = "beanstalk_role_us_west"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "beanstalk_policy_us_west" {
  name = "beanstalk_policy_us_west"
  role = aws_iam_role.beanstalk_role_us_west.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:*",
          "elasticloadbalancing:*",
          "autoscaling:*",
          "cloudwatch:*",
          "s3:*",
          "sns:*",
          "cloudformation:*",
          "rds:*",
          "dynamodb:*",
          "logs:*"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role" "beanstalk_role_eu_central" {
  name = "beanstalk_role_eu_central"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "beanstalk_policy_eu_central" {
  name = "beanstalk_policy_eu_central"
  role = aws_iam_role.beanstalk_role_eu_central.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:*",
          "elasticloadbalancing:*",
          "autoscaling:*",
          "cloudwatch:*",
          "s3:*",
          "sns:*",
          "cloudformation:*",
          "rds:*",
          "dynamodb:*",
          "logs:*"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_elastic_beanstalk_application" "my_app" {
  name = var.application_name
}

resource "aws_elastic_beanstalk_environment" "us_west_env" {
  name                = var.environment_name_us_west
  application         = aws_elastic_beanstalk_application.my_app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.5.0 running Python 3.8"
  instance_type       = "t2.micro"
  role_arn            = aws_iam_role.beanstalk_role_us_west.arn
}

resource "aws_elastic_beanstalk_environment" "eu_central_env" {
  name                = var.environment_name_eu_central
  application         = aws_elastic_beanstalk_application.my_app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.5.0 running Python 3.8"
  instance_type       = "t2.micro"
  role_arn            = aws_iam_role.beanstalk_role_eu_central.arn
}

resource "aws_route53_zone" "my_domain" {
  name = var.domain_name
}

resource "aws_route53_record" "geo_redirect_us_west" {
  zone_id = aws_route53_zone.my_domain.zone_id
  name    = "www.${var.domain_name}"
  type    = "A"
  ttl     = 300

  geo_location {
    continent_code = "NA"
  }

  alias {
    name                   = aws_elastic_beanstalk_environment.us_west_env.cname
    zone_id                = aws_elastic_beanstalk_environment.us_west_env.elb
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "geo_redirect_eu_central" {
  zone_id = aws_route53_zone.my_domain.zone_id
  name    = "www.${var.domain_name}"
  type    = "A"
  ttl     = 300

  geo_location {
    continent_code = "EU"
  }

  alias {
    name                   = aws_elastic_beanstalk_environment.eu_central_env.cname
    zone_id                = aws_elastic_beanstalk_environment.eu_central_env.elb
    evaluate_target_health = true
  }
}
```

