Below is the complete Terraform HCL program that provisions the necessary AWS infrastructure for deploying a web application, including IAM roles, a VPC with an Internet Gateway, subnets, route configurations, an RDS instance, and an Elastic Beanstalk environment.

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the main VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "CIDR blocks for the public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "db_instance_class" {
  description = "Instance class for the RDS instance"
  default     = "db.t3.micro"
}

variable "db_engine" {
  description = "Database engine for the RDS instance"
  default     = "mysql"
}

variable "db_username" {
  description = "Username for the RDS instance"
  default     = "admin"
}

variable "db_password" {
  description = "Password for the RDS instance"
  default     = "password123"
}

variable "eb_application_name" {
  description = "Name of the Elastic Beanstalk application"
  default     = "web-app"
}

variable "eb_environment_name" {
  description = "Name of the Elastic Beanstalk environment"
  default     = "web-app-env"
}

resource "aws_iam_role" "web_app_role" {
  name = "web-app-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "web_app_policy" {
  name        = "web-app-policy"
  path        = "/"
  description = "Policy for the web application role"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:*",
          "rds:*",
          "elasticbeanstalk:*"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_web_app_policy" {
  role       = aws_iam_role.web_app_role.name
  policy_arn = aws_iam_policy.web_app_policy.arn
}

resource "aws_vpc" "main_vpc" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_internet_gateway" "main_igw" {
  vpc_id = aws_vpc.main_vpc.id
}

resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.main_vpc.id
}

resource "aws_route" "internet_gateway_route" {
  route_table_id         = aws_route_table.public_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main_igw.id
}

resource "aws_subnet" "public_subnet_1" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = var.subnet_cidr_blocks[0]
  map_public_ip_on_launch = true
}

resource "aws_subnet" "public_subnet_2" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = var.subnet_cidr_blocks[1]
  map_public_ip_on_launch = true
}

resource "aws_route_table_association" "public_subnet_1_association" {
  subnet_id      = aws_subnet.public_subnet_1.id
  route_table_id = aws_route_table.public_route_table.id
}

resource "aws_route_table_association" "public_subnet_2_association" {
  subnet_id      = aws_subnet.public_subnet_2.id
  route_table_id = aws_route_table.public_route_table.id
}

resource "aws_db_instance" "web_app_rds" {
  identifier              = "web-app-rds"
  instance_class          = var.db_instance_class
  engine                  = var.db_engine
  username                = var.db_username
  password                = var.db_password
  allocated_storage       = 20
  vpc_security_group_ids  = [aws_security_group.default_sg.id]
  db_subnet_group_name    = aws_db_subnet_group.default_sg.name
  skip_final_snapshot     = true
}

resource "aws_security_group" "default_sg" {
  name        = "default-sg"
  description = "Default security group"
  vpc_id      = aws_vpc.main_vpc.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_subnet_group" "default_sg" {
  name       = "default-sg"
  subnet_ids = [aws_subnet.public_subnet_1.id, aws_subnet.public_subnet_2.id]
}

resource "aws_elastic_beanstalk_application" "web_app_eb_app" {
  name = var.eb_application_name
}

resource "aws_elastic_beanstalk_environment" "web_app_eb_env" {
  name                = var.eb_environment_name
  application         = aws_elastic_beanstalk_application.web_app_eb_app.name
  solution_stack_name = "64bit Amazon Linux 2 v3.4.1 running Python 3.8"
  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "IamInstanceProfile"
    value     = aws_iam_role.web_app_role.name
  }
  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBInstanceClass"
    value     = var.db_instance_class
  }
  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBEngine"
    value     = var.db_engine
  }
  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBUser"
    value     = var.db_username
  }
  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBPassword"
    value     = var.db_password
  }
}
