Below is the complete Terraform HCL program that configures the specified Route 53 resources to manage a domain and directs traffic to an Elastic Beanstalk environment with a connected RDS database.

```hcl
provider "aws" {
  region = "us-west-2"  # Ensure this is set to your desired region
}

# IAM Role for EC2 instances in Elastic Beanstalk
resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Instance Profile for EC2 instances in Elastic Beanstalk
resource "aws_iam_instance_profile" "eb_ec2_profile1" {
  name = "eb_ec2_profile1"
  roles = [aws_iam_role.eb_ec2_role.name]
}

# RDS Database for the application
resource "aws_rds_instance" "myapp_db" {
  identifier           = "myapp-db"
  instance_class       = "db.t2.micro"
  engine               = "mysql"
  engine_version       = "8.0"
  username             = "admin"
  password             = "password"
  allocated_storage    = 20
  skip_final_snapshot  = true
  vpc_security_group_ids = [aws_security_group.rds_sg.id]
}

# Security Group for RDS
resource "aws_security_group" "rds_sg" {
  name        = "rds-sg"
  description = "Security group for RDS"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# VPC for RDS
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "myapp" {
  name        = "myapp"
  description = "My Elastic Beanstalk Application"
}

# Elastic Beanstalk Environment
resource "aws_elastic_beanstalk_environment" "myenv" {
  name                = "myenv"
  application         = aws_elastic_beanstalk_application.myapp.name
  solution_stack_name = "64bit Amazon Linux 2 v3.5.0 running Python 3.8"
  instance_profile    = aws_iam_instance_profile.eb_ec2_profile1.name

  setting {
    namespace = "aws:elasticbeanstalk:environment"
    name      = "EnvironmentType"
    value     = "LoadBalanced"
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBUser"
    value     = aws_rds_instance.myapp_db.username
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBPassword"
    value     = aws_rds_instance.myapp_db.password
  }

  setting {
    namespace = "aws:rds:dbinstance"
    name      = "DBSnapshotIdentifier"
    value     = aws_rds_instance.myapp_db.identifier
  }
}

# Route 53 Hosted Zone for the domain
resource "aws_route53_zone" "mydomain_zone" {
  name = "example.com"
}

# Route 53 Record to direct traffic to the Elastic Beanstalk environment
resource "aws_route53_record" "mydomain_record" {
  zone_id = aws_route53_zone.mydomain_zone.zone_id
  name    = "www.example.com"
  type    = "A"
  ttl     = 300

  alias {
    name                   = aws_elastic_beanstalk_environment.myenv.cname
    zone_id                = aws_elastic_beanstalk_environment.myenv.elb_domain_name
    evaluate_target_health = true
  }
}
