```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# IAM Role for Elastic Beanstalk
resource "aws_iam_role" "elastic_beanstalk_service_role" {
  name = "elastic-beanstalk-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      }
    ]
  })
}

# Attach AWS managed policy for Elastic Beanstalk service role
resource "aws_iam_role_policy_attachment" "attach_elastic_beanstalk_service_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkWebTier"
  role       = aws_iam_role.elastic_beanstalk_service_role.name
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "my_application" {
  name        = "my-application"
  description = "My Elastic Beanstalk Application"
}

# S3 Bucket to store application versions
resource "aws_s3_bucket" "application_version_bucket" {
  bucket = "my-application-version-bucket-${random_string.suffix.result}"
  acl    = "private"

  tags = {
    Name        = "My Application Version Bucket"
    Environment = "production"
  }
}

# Random string suffix for S3 bucket name
resource "random_string" "suffix" {
  length  = 8
  special = false
}

# S3 Object for application version
resource "aws_s3_object" "application_version_object" {
  bucket = aws_s3_bucket.application_version_bucket.bucket
  key    = "my-application-version.zip"
  source = "path/to/my-application-version.zip"  # Update with your application version file path

  acl = "private"
}

# Elastic Beanstalk Application Version
resource "aws_elastic_beanstalk_application_version" "my_application_version" {
  application = aws_elastic_beanstalk_application.my_application.name
  version     = "v1"
  bucket      = aws_s3_bucket.application_version_bucket.bucket
  key         = aws_s3_object.application_version_object.key
}

# Elastic Beanstalk Environment
resource "aws_elastic_beanstalk_environment" "my_environment" {
  name                = "my-environment"
  application         = aws_elastic_beanstalk_application.my_application.name
  solution_stack_name = "64bit Amazon Linux 2 v3.3.1 running Python 3.8"
  version_label       = aws_elastic_beanstalk_application_version.my_application_version.version

  setting {
    namespace = "aws:autoscaling:launchconfiguration"
    name      = "InstanceType"
    value     = "t2.micro"
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "VPCId"
    value     = "vpc-12345678"  # Update with your VPC ID
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "Subnets"
    value     = "subnet-12345678,subnet-87654321"  # Update with your subnet IDs
  }

  setting {
    namespace = "aws:ec2:vpc"
    name      = "SecurityGroups"
    value     = "sg-12345678"  # Update with your security group ID
  }
}
```

### Notes:
1. **IAM Role and Policy Attachment**: The IAM role `elastic_beanstalk_service_role` is created with a trust policy allowing Elastic Beanstalk to assume it. The AWS managed policy `AWSElasticBeanstalkWebTier` is attached to this role.
2. **S3 Bucket and Object**: An S3 bucket named `my-application-version-bucket-{random_suffix}` is created to store the application version files. A random string suffix is appended to ensure the bucket name is unique.
3. **Elastic Beanstalk Application and Version**: The Elastic Beanstalk application `my-application` is created, and an application version `v1` is uploaded from the specified S3 object.
4. **Elastic Beanstalk Environment**: An environment `my-environment` is created to run the application version. You need to update the `solution_stack_name`, `VPCId`, `Subnets`, and `SecurityGroups` settings with your specific configurations.

Make sure to replace placeholders like `path/to/my-application-version.zip`, `vpc-12345678`, `subnet-12345678`, `subnet-87654321`, and `sg-12345678` with your actual values.

