Below is the complete Terraform HCL program that creates an Elastic Beanstalk application with an app version lifecycle, retaining the version for 5 days. The program includes the necessary IAM roles, S3 bucket, Lambda function, and CloudWatch event rule to manage the lifecycle of the application versions.

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# IAM Role for Elastic Beanstalk
resource "aws_iam_role" "elastic_beanstalk_service_role" {
  name = "elastic_beanstalk_service_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      }
    ]
  })
}

# Attach policy to the IAM role
resource "aws_iam_role_policy_attachment" "elastic_beanstalk_service_role_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkWebTier"
  role       = aws_iam_role.elastic_beanstalk_service_role.name
}

# Elastic Beanstalk Application
resource "aws_elastic_beanstalk_application" "my_application" {
  name        = "my-application"
  description = "My Elastic Beanstalk Application"
}

# S3 Bucket to store application code
resource "aws_s3_bucket" "application_code_bucket" {
  bucket = "my-application-code-bucket-${random_string.suffix.result}"
  acl    = "private"
}

# Random string suffix for S3 bucket name
resource "random_string" "suffix" {
  length  = 8
  special = false
}

# Upload application code to S3
resource "aws_s3_object" "application_code_object" {
  bucket = aws_s3_bucket.application_code_bucket.bucket
  key    = "my-application-code.zip"
  source = "path/to/my-application-code.zip"  # Update with your application code path
}

# Elastic Beanstalk Application Version
resource "aws_elastic_beanstalk_application_version" "my_application_version" {
  application = aws_elastic_beanstalk_application.my_application.name
  bucket      = aws_s3_bucket.application_code_bucket.bucket
  key         = aws_s3_object.application_code_object.key
  version_label = "v1.0.0"  # Update with your version label
}

# Elastic Beanstalk Environment
resource "aws_elastic_beanstalk_environment" "my_environment" {
  name                = "my-environment"
  application         = aws_elastic_beanstalk_application.my_application.name
  solution_stack_name = "64bit Amazon Linux 2 v3.6.0 running Python 3.9"
  version_label       = aws_elastic_beanstalk_application_version.my_application_version.version_label
}

# Lambda function to handle lifecycle events
resource "aws_lambda_function" "lifecycle_hook_lambda" {
  filename         = "path/to/lifecycle_hook_lambda.zip"  # Update with your Lambda function code path
  function_name    = "lifecycle_hook_lambda"
  role             = aws_iam_role.lambda_execution_role.arn
  handler          = "lambda_function.lambda_handler"
  runtime          = "python3.9"
  source_code_hash = filebase64sha256("path/to/lifecycle_hook_lambda.zip")  # Update with your Lambda function code path
}

# IAM Role for Lambda execution
resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# Attach policy to the Lambda execution role
resource "aws_iam_role_policy_attachment" "lambda_execution_role_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_execution_role.name
}

# Permission for Lambda to be invoked by Elastic Beanstalk
resource "aws_lambda_permission" "lifecycle_hook_lambda_permission" {
  statement_id  = "AllowElasticBeanstalkInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.lifecycle_hook_lambda.function_name
  principal     = "elasticbeanstalk.amazonaws.com"
}

# CloudWatch event rule to trigger lifecycle events
resource "aws_cloudwatch_event_rule" "lifecycle_event_rule" {
  name        = "lifecycle_event_rule"
  schedule_expression = "cron(0 0 * * ? *)"  # Daily at midnight
}

# Target the Lambda function for the CloudWatch event
resource "aws_cloudwatch_event_target" "lifecycle_event_target" {
  rule      = aws_cloudwatch_event_rule.lifecycle_event_rule.name
  target_id = "lifecycle_event_target"
  arn       = aws_lambda_function.lifecycle_hook_lambda.arn
}

# Permission for CloudWatch Events to invoke the Lambda function
resource "aws_cloudwatch_event_permission" "lifecycle_event_permission" {
  statement_id  = "AllowCloudWatchEventsInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.lifecycle_hook_lambda.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.lifecycle_event_rule.arn
}
```

### Notes:
1. **IAM Policies**: Ensure the IAM policies attached to the roles have the necessary permissions for Elastic Beanstalk operations.
2. **Lambda Function**: The Lambda function should be configured to handle the lifecycle events and delete old versions after 5 days. You need to implement the logic inside the Lambda function to achieve this.
3. **Update Paths**: Replace `"path/to/my-application-code.zip"` and `"path/to/lifecycle_hook_lambda.zip"` with the actual paths to your application code and Lambda function code, respectively.

