### Description
This Terraform program creates a basic AWS CodeBuild project with an example IAM role and a GitHub source. The program includes the necessary IAM role, policy, and policy attachment to ensure the CodeBuild project has the required permissions. The provider configuration specifies the AWS region.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"  # Specify your desired AWS region
}

# IAM Role for CodeBuild
resource "aws_iam_role" "codebuild_example_role" {
  name = "codebuild-example-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for CodeBuild
resource "aws_iam_policy" "codebuild_example_policy" {
  name        = "codebuild-example-policy"
  description = "Policy for CodeBuild to access necessary AWS services"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::your-bucket-name/*"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_codebuild_policy_to_role" {
  policy_arn = aws_iam_policy.codebuild_example_policy.arn
  role       = aws_iam_role.codebuild_example_role.name
}

# CodeBuild Project
resource "aws_codebuild_project" "example_codebuild_project" {
  name         = "example-codebuild-project"
  service_role = aws_iam_role.codebuild_example_role.arn

  source {
