### Description
The Terraform program below creates an AWS CodeBuild project along with an IAM role and policy necessary for the CodeBuild project to execute its build steps. The IAM role is attached to the policy, ensuring that the CodeBuild project has the required permissions. Additionally, the program includes a secondary artifact configuration for the CodeBuild project.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# IAM Role for CodeBuild
resource "aws_iam_role" "codebuild_example_role" {
  name = "codebuild-example-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for CodeBuild
resource "aws_iam_policy" "codebuild_example_policy" {
  name        = "codebuild-example-policy"
  description = "Policy for CodeBuild to access necessary resources"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::your-bucket-name/*"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_codebuild_policy_to_role" {
  role       = aws_iam_role.codebuild_example_role.name
  policy_arn = aws_iam_policy.codebuild_example_policy.arn
}

# CodeBuild Project
resource "aws_codebuild_project" "example_codebuild_project" {
  name         = "example-codebuild-project"
  service_role = aws_iam_role.codebuild_example_role.arn

  source {
    type            = "S3"
    location        = "your-bucket-name/your-source-code.zip"
    buildspec       = "buildspec.yml"
    auth {
      type     = "OAUTH"
      resource = "your-resource"
    }
  }

  artifacts {
    type = "S3"
    location = "your-bucket-name/build-artifacts"
  }

  secondary_artifacts {
    type = "S3"
    location = "your-bucket-name/secondary-build-artifacts"
  }

  environment {
    compute_type    = "BUILD_GENERAL1_SMALL"
    image           = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    type            = "LINUX_CONTAINER"
    image_pull_credentials_type = "CODEBUILD"
  }

  logs_config {
    cloudwatch_logs {
      group_name  = "/aws/codebuild/example-codebuild-project"
      stream_name = "build-log"
    }
  }
}
```

### Notes
- Replace `"your-bucket-name"` with the actual S3 bucket name where your source code and artifacts will be stored.
- Replace `"your-resource"` with the appropriate resource identifier if using OAuth for authentication.
- Ensure that the IAM policy actions and resources align with your specific requirements and security policies.

