```hcl
provider "aws" {
  region = "us-east-1"
}

variable "bot_name" {
  description = "The name of the Lex bot"
  default     = "MyLexBot"
}

variable "slot_type_1_name" {
  description = "The name of the first slot type"
  default     = "SlotType1"
}

variable "slot_type_2_name" {
  description = "The name of the second slot type"
  default     = "SlotType2"
}

variable "intent_name" {
  description = "The name of the intent"
  default     = "IntentWithSlots"
}

resource "aws_lex_slot_type" "slot_type_1" {
  name        = var.slot_type_1_name
  enumeration_value {
    value = "Value1"
  }
  enumeration_value {
    value = "Value2"
  }
}

resource "aws_lex_slot_type" "slot_type_2" {
  name        = var.slot_type_2_name
  enumeration_value {
    value = "OptionA"
  }
  enumeration_value {
    value = "OptionB"
  }
}

resource "aws_lex_intent" "intent_with_slots" {
  name        = var.intent_name
  sample_utterances = [
    "I want to book a flight",
    "Can I book a flight?"
  ]
  fulfillment_activity {
    type = "ReturnIntent"
  }
  slot {
    name               = "Slot1"
    slot_type          = aws_lex_slot_type.slot_type_1.name
    elicitation_prompt {
      max_attempts = 2
      message {
        content_type = "PlainText"
        content      = "Please provide Slot1"
      }
    }
  }
  slot {
    name               = "Slot2"
    slot_type          = aws_lex_slot_type.slot_type_2.name
    elicitation_prompt {
      max_attempts = 2
      message {
        content_type = "PlainText"
        content      = "Please provide Slot2"
      }
    }
  }
}

resource "aws_lex_bot" "lex_bot" {
  name                  = var.bot_name
  locale                = "en-US"
  child_directed        = false
  intents {
    intent_name = aws_lex_intent.intent_with_slots.name
    intent_version = "$LATEST"
  }
  clarification_prompt {
    max_attempts = 2
    message {
      content_type = "PlainText"
      content      = "I didn't understand that. Can you please repeat?"
    }
  }
  abort_statement {
    message {
      content_type = "PlainText"
      content      = "Sorry, I can't assist with that."
    }
  }
}
```

This Terraform configuration sets up an AWS Lex bot with two slots, each associated with a different slot type. The bot is configured with sample utterances and fulfillment activities. The dependencies between resources are managed using Terraform references to ensure the correct order of creation.

Reference output:
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.75"
    }
  }

  required_version = "~> 1.9.8"
}

provider "aws" {
  region = "us-east-1"
  profile = "admin-1"

  assume_role {
    role_arn = "arn:aws:iam::590184057477:role/yicun-iac"
  }
}


resource "aws_lex_bot" "pizza_order_bot" {
  name = "PizzaOrderBot"
  description = "Pizza order bot"
  idle_session_ttl_in_seconds = 600
  create_version = false
  child_directed = false

  abort_statement {
    message {
      content = "Sorry, I am not able to assist."
      content_type = "PlainText"
    }
  }

  clarification_prompt {
    max_attempts = 2
    message {
      content = "I'm sorry, I didn't understand that. Can you try again?"
      content_type = "PlainText"
    }
  }

  intent {
    intent_name = aws_lex_intent.OrderPizzaIntent.name
    intent_version = aws_lex_intent.OrderPizzaIntent.version
  }
}

resource "aws_lex_intent" "OrderPizzaIntent" {
  name = "OrderPizzaIntent"
  create_version = true

  sample_utterances = [
    "I would like to pick up a pizza",
    "I would like to order some pizzas",
  ]

  slot {
    name = "PizzaType"
    description = "Type of pizza to order"
    priority = 1  # must be in [1, 100]
    slot_type = aws_lex_slot_type.PizzaType.name
    slot_type_version = aws_lex_slot_type.PizzaType.version
    slot_constraint = "Required"

    sample_utterances = ["I want a {PizzaType} pizza.", "A {PizzaType} pizza please."]

    value_elicitation_prompt {
      max_attempts = 2
      message {
        content = "What type of pizza would you like to order?"
        content_type = "PlainText"
      }
    }
  }

  confirmation_prompt {
    max_attempts = 2
    message {
      content = "So, you would like to order a pizza. Is that correct?"
      content_type = "PlainText"
    }
  }

  rejection_statement {
    message {
        content = "Sorry, I don't know how to help then"
        content_type = "PlainText"
      }
    }

  follow_up_prompt {
    prompt {
      max_attempts = 2
      message {
        content = "Would you like anything else with your order?"
        content_type = "PlainText"
      }
    }
    rejection_statement {
      message {
        content = "OK, Your pizza is on its way."
        content_type = "PlainText"
      }
    }
  }

  fulfillment_activity {
    type = "ReturnIntent"
  }
}

resource "aws_lex_slot_type" "PizzaType" {
  create_version = true
  description = "Types of pizza available to order"
  name = "PizzaTypes"
  enumeration_value {
    value = "Margherita"
  }
  enumeration_value {
    value = "Pepperoni"
  }
}

