```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for Lex Bot
resource "aws_iam_role" "lex_bot_role" {
  name = "lex-bot-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lex.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Lex Bot
resource "aws_iam_policy" "lex_bot_policy" {
  name        = "lex-bot-policy"
  description = "Policy granting necessary permissions to the Lex bot"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_lex_bot_policy" {
  role       = aws_iam_role.lex_bot_role.name
  policy_arn = aws_iam_policy.lex_bot_policy.arn
}

# Slot Type for Pizza Size
resource "aws_lex_slot_type" "pizza_size_slot_type" {
  name               = "PizzaSize"
  enumeration_value {
    value = "Small"
  }
  enumeration_value {
    value = "Medium"
  }
  enumeration_value {
    value = "Large"
  }
  create_version = true
}

# Slot Type for Pizza Topping
resource "aws_lex_slot_type" "pizza_topping_slot_type" {
  name               = "PizzaTopping"
  enumeration_value {
    value = "Pepperoni"
  }
  enumeration_value {
    value = "Mushrooms"
  }
  enumeration_value {
    value = "Onions"
  }
  create_version = true
}

# Intent for Ordering Pizza
resource "aws_lex_intent" "order_pizza_intent" {
  name               = "OrderPizza"
  sample_utterances  = ["I want to order a pizza", "Can I order a pizza?"]
  fulfillment_activity {
    type = "ReturnIntent"
  }

  slot {
    name               = "PizzaSize"
    slot_constraint    = "Required"
    slot_type          = aws_lex_slot_type.pizza_size_slot_type.name
    elicitation_prompt {
