      messages {
        content_type = "PlainText"
        content      = "What size pizza would you like?"
      }
    }
  }

  slot {
    name               = "PizzaTopping"
    slot_constraint    = "Required"
    slot_type          = aws_lex_slot_type.pizza_topping_slot_type.name
    elicitation_prompt {
      max_attempts = 2
      messages {
        content_type = "PlainText"
        content      = "What toppings would you like?"
      }
    }
  }

  confirmation_prompt {
    max_attempts = 2
    messages {
      content_type = "PlainText"
      content      = "Is this correct? Size: {PizzaSize}, Toppings: {PizzaTopping}"
    }
  }

  create_version = true
}

# Lex Bot for Ordering Pizza
resource "aws_lex_bot" "pizza_order_bot" {
  name            = "PizzaOrderBot"
  locale          = "en-US"
  child_directed  = false
  intents {
    intent_name = aws_lex_intent.order_pizza_intent.name
    intent_version = aws_lex_intent.order_pizza_intent.version
