### Description
The Terraform program below creates an AWS Lex bot for ordering pizzas along with a Lambda function that handles the pizza ordering logic. The program includes the necessary IAM roles and policies to ensure proper execution. The Lambda function is attached to the Lex bot for fulfillment.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"  # Specify your desired AWS region
}

# IAM Role for Lambda Execution
resource "aws_iam_role" "lex_bot_lambda_execution_role" {
  name = "lex_bot_lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Lambda Function
resource "aws_iam_policy" "lex_bot_lambda_policy" {
  name        = "lex_bot_lambda_policy"
  description = "Policy granting necessary permissions to Lambda function"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach Policy to IAM Role
resource "aws_iam_role_policy_attachment" "attach_lex_bot_lambda_policy_to_role" {
  role       = aws_iam_role.lex_bot_lambda_execution_role.name
  policy_arn = aws_iam_policy.lex_bot_lambda_policy.arn
}

# Lambda Function for Pizza Ordering
resource "aws_lambda_function" "pizza_ordering_lambda" {
  function_name = "pizza_ordering_lambda"
  handler       = "index.handler"
  runtime       = "python3.8"
  role          = aws_iam_role.lex_bot_lambda_execution_role.arn

  # Replace with your actual Lambda function code
  filename         = "path/to/your/pizza_ordering_lambda.zip"
  source_code_hash = filebase64sha256("path/to/your/pizza_ordering_lambda.zip")
}

# Lex Bot for Ordering Pizzas
resource "aws_lex_bot" "pizza_ordering_bot" {
  name                  = "pizza_ordering_bot"
  locale                = "en-US"
  child_directed        = false
  voice_id              = "Joanna"
  process_behavior      = "BUILD"
  clarification_prompt {
    max_attempts = 2
    messages {
      content_type = "PlainText"
      content      = "I'm sorry, I didn't understand that. Can you please repeat?"
    }
  }
  abort_statement {
    messages {
      content_type = "PlainText"
      content      = "Sorry, I can't help with that."
    }
  }
  intents {
    intent_name = "OrderPizzaIntent"
    sample_utterances = [
      "I want to order a pizza",
      "Can I order a pizza?",
      "Order me a pizza"
    ]
    fulfillment_activity {
      type = "CodeHook"
      code_hook {
        uri = aws_lambda_function.pizza_ordering_lambda.invoke_arn
        message_version = "1.0"
      }
    }
  }
}
```

### Notes
1. **Lambda Function Code**: Ensure that the `filename` and `source_code_hash` are correctly set to point to your Lambda function's deployment package.
2. **IAM Policy**: Adjust the IAM policy (`aws_iam_policy.lex_bot_lambda_policy`) to grant the necessary permissions for your Lambda function, especially if it interacts with other AWS services.
3. **Region**: Update the `region` in the provider configuration to your preferred AWS region.
4. **Voice ID**: The `voice_id` in the Lex bot configuration can be changed to any available Amazon Polly voice ID.

