### Description
The Terraform program below creates an AWS Connect instance, a Lex V2 bot, and associates the Lex V2 bot with the AWS Connect instance. The program ensures that the bot association depends on the existence of both the Connect instance and the Lex V2 bot. The necessary IAM roles and permissions are created to support these operations.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "connect_instance_role" {
  name = "connect-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "connect.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "connect_instance_policy" {
  role       = aws_iam_role.connect_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonConnectFullAccess"
}

resource "aws_connect_instance" "connect_instance_kids" {
  identity_management_type = "CONNECT_MANAGED"
  inbound_calls_enabled    = true
  outbound_calls_enabled   = true
  auto_resolve_best_vpc    = true

  depends_on = [aws_iam_role_policy_attachment.connect_instance_policy]
}

resource "aws_iam_role" "lexv2_bot_role" {
  name = "lexv2-bot-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lexv2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lexv2_bot_policy" {
  role       = aws_iam_role.lexv2_bot_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonLexV2FullAccess"
}

resource "aws_lexv2_bot" "lexv2_bot_kids" {
  name                        = "kids_bot"
  idle_session_ttl_in_seconds = 300
  data_privacy_mode           = "TextAndVoice"
  child_directed              = false
  role_arn                    = aws_iam_role.lexv2_bot_role.arn

  depends_on = [aws_iam_role_policy_attachment.lexv2_bot_policy]
}

resource "aws_connect_bot_association" "connect_bot_association_kids" {
  instance_id = aws_connect_instance.connect_instance_kids.id
  lexBot {
    name     = aws_lexv2_bot.lexv2_bot_kids.name
    lex_region = var.aws_region
  }

  depends_on = [aws_connect_instance.connect_instance_kids, aws_lexv2_bot.lexv2_bot_kids]
}

variable "aws_region" {
  description = "The AWS region where the resources will be deployed"
  type        = string
  default     = "us-east-1"
}
```

