Below is the complete Terraform HCL program that creates an AWS Connect instance, an IAM role for SAML integration, attaches a policy to the IAM role, and associates a bot with the Connect instance using the SAML IAM role.

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

resource "aws_connect_instance" "connect_instance" {
  identity_management_type = "CONNECT_MANAGED"
  inbound_calls_enabled    = true
  outbound_calls_enabled   = true
  auto_resolve_best_vpc    = true
}

resource "aws_iam_role" "connect_saml_role" {
  name = "connect_saml_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRoleWithSAML"
        Effect = "Allow"
        Principal = {
          SAMLProvider = aws_iam_saml_provider.connect_saml_provider.name
        }
        Condition = {
          StringEquals = {
            "SAML:aud" = "https://signin.aws.amazon.com/saml"
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "connect_saml_policy" {
  name        = "connect_saml_policy"
  path        = "/"
  description = "Policy for SAML integration with AWS Connect"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "connect:*"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_saml_policy_to_role" {
  role       = aws_iam_role.connect_saml_role.name
  policy_arn = aws_iam_policy.connect_saml_policy.arn
}

resource "aws_connect_bot_association" "connect_bot_association" {
  instance_id = aws_connect_instance.connect_instance.id
  lexicographic_order = 1
  bot_name = "example_bot"  # Replace with your bot name
  bot_alias_name = "example_bot_alias"  # Replace with your bot alias name
  lex_v2_bot_id = "example_lex_v2_bot_id"  # Replace with your Lex V2 bot ID
  lex_v2_bot_alias_id = "example_lex_v2_bot_alias_id"  # Replace with your Lex V2 bot alias ID
  lex_v2_bot_locale = "en_US"  # Replace with your Lex V2 bot locale
  lex_v2_bot_version = "DRAFT"  # Replace with your Lex V2 bot version
  security_profile_ids = ["example_security_profile_id"]  # Replace with your security profile IDs
  instance_version = "LATEST"  # Replace with your instance version
}
```

### Notes:
1. **IAM Policy Permissions**: Ensure that the IAM policy (`aws_iam_policy.connect_saml_policy`) has the necessary permissions for SAML integration with AWS Connect.
2. **Bot Details**: Replace placeholders like `example_bot`, `example_bot_alias`, `example_lex_v2_bot_id`, `example_lex_v2_bot_alias_id`, `example_security_profile_id` with actual values relevant to your setup.
3. **Region**: The provider region is set to `us-west-2`. You can change it to your preferred region.
4. **Dependencies**: The dependencies between resources are managed through Terraform references, ensuring that resources are created in the correct order.

