### Description
The Terraform program below defines a Kinesis Firehose Delivery Stream with an extended S3 Destination, including dynamic partitioning. It also sets up the necessary IAM roles and policies to allow the Firehose delivery stream to access the S3 bucket.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "s3_bucket_name" {
  description = "The name of the S3 bucket where data will be delivered"
  type        = string
}

variable "s3_prefix" {
  description = "The prefix for the S3 bucket where data will be delivered"
  type        = string
  default     = ""
}

variable "delivery_stream_name" {
  description = "The name of the Kinesis Firehose delivery stream"
  type        = string
  default     = "my_kinesis_firehose_delivery_stream"
}

# IAM Role for Kinesis Firehose to access S3
resource "aws_iam_role" "firehose_delivery_stream_role" {
  name = "firehose_delivery_stream_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy granting S3 access permissions to the Firehose delivery stream
resource "aws_iam_policy" "firehose_s3_access_policy" {
  name        = "firehose_s3_access_policy"
  description = "Policy granting S3 access permissions to the Firehose delivery stream"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = [
          "arn:aws:s3:::${var.s3_bucket_name}",
          "arn:aws:s3:::${var.s3_bucket_name}/*"
        ]
      }
    ]
  })
}

# Attach the S3 access policy to the Firehose delivery stream role
resource "aws_iam_role_policy_attachment" "attach_firehose_s3_policy" {
  role       = aws_iam_role.firehose_delivery_stream_role.name
  policy_arn = aws_iam_policy.firehose_s3_access_policy.arn
}

# Kinesis Firehose delivery stream with S3 destination
resource "aws_kinesis_firehose_delivery_stream" "kinesis_firehose_delivery_stream" {
  name        = var.delivery_stream_name
  destination = "s3"

  s3_configuration {
    role_arn         = aws_iam_role.firehose_delivery_stream_role.arn
    bucket_arn       = "arn:aws:s3:::${var.s3_bucket_name}"
    prefix           = var.s3_prefix
    buffering_hints {
      size_in_mbs = 5
      interval_in_seconds = 300
    }
    compression_format = "UNCOMPRESSED"
    dynamic_partitioning_configuration {
      enabled = true
      retry_options {
        duration_in_seconds = 300
      }
    }
  }
}
```

### Notes
- Ensure the S3 bucket (`var.s3_bucket_name`) and prefix (`var.s3_prefix`) are created before deploying the Firehose delivery stream.
- The `dynamic_partitioning_configuration` block enables dynamic partitioning in the Firehose delivery stream. Adjust the `duration_in_seconds` as needed for retry options.

