This Terraform program sets up a Kinesis Firehose Delivery Stream that delivers data to a Redshift cluster. It includes the creation of a Redshift cluster, an IAM role with necessary permissions, and the Kinesis Firehose Delivery Stream itself. The IAM role and policy ensure that Kinesis Firehose has the required permissions to deliver data to Redshift.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "redshift_cluster_identifier" {
  description = "Identifier for the Redshift cluster"
  default     = "my-redshift-cluster"
}

variable "redshift_node_type" {
  description = "Node type for the Redshift cluster"
  default     = "dc2.large"
}

variable "redshift_master_username" {
  description = "Master username for the Redshift cluster"
  default     = "admin"
}

variable "redshift_master_password" {
  description = "Master password for the Redshift cluster"
  default     = "SecurePassword123!"
}

variable "redshift_cluster_subnet_group_name" {
  description = "Name of the Redshift cluster subnet group"
  default     = "default"
}

variable "redshift_security_group_name" {
  description = "Name of the Redshift security group"
  default     = "default"
}

variable "firehose_delivery_role_name" {
  description = "Name of the IAM role for Kinesis Firehose delivery"
  default     = "kinesis-firehose-delivery-role"
}

variable "firehose_delivery_policy_name" {
  description = "Name of the IAM policy for Kinesis Firehose delivery"
  default     = "kinesis-firehose-delivery-policy"
}

resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier      = var.redshift_cluster_identifier
  node_type               = var.redshift_node_type
  master_username         = var.redshift_master_username
  master_password         = var.redshift_master_password
  cluster_subnet_group_name = var.redshift_cluster_subnet_group_name
  vpc_security_group_ids  = [aws_security_group.redshift_sg.id]
}

resource "aws_security_group" "redshift_sg" {
  name        = var.redshift_security_group_name
  description = "Security group for Redshift cluster"
  vpc_id      = aws_vpc.default.id

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Adjust as needed for security
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_vpc" "default" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_iam_role" "firehose_delivery_role" {
  name = var.firehose_delivery_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "firehose_delivery_policy" {
  name        = var.firehose_delivery_policy_name
  description = "Policy for Kinesis Firehose to deliver data to Redshift"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "redshift:LoadIntoRedshift",
          "redshift:DescribeClusters",
          "redshift:GetClusterCredentials"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_firehose_policy_to_role" {
  role       = aws_iam_role.firehose_delivery_role.name
  policy_arn = aws_iam_policy.firehose_delivery_policy.arn
}

resource "aws_kinesis_firehose_delivery_stream" "kinesis_firehose_delivery_stream" {
  name        = "my-kinesis-firehose-stream"
  destination = "redshift"

  redshift_configuration {
    role_arn           = aws_iam_role.firehose_delivery_role.arn
    cluster_jdbcurl    = "jdbc:redshift://<redshift-cluster-endpoint>:5439/dev"
    copy_command {
      copy_options = ""
      data_table_columns = ""
      data_table_name = "my_table"
    }
    username = var.redshift_master_username
    password = var.redshift_master_password
  }
}
```

### Notes
- Replace `<redshift-cluster-endpoint>` with the actual endpoint of your Redshift cluster.
- Ensure that the security groups and subnets are correctly configured to allow communication between Kinesis Firehose and Redshift.
- Adjust the security group rules as needed to comply with your security policies.

