}

variable "region" {
  description = "The AWS region to deploy the resources"
  default     = "us-west-2"
}

variable "firehose_delivery_stream_name" {
  description = "The name of the Kinesis Firehose Delivery Stream"
  default     = "my_firehose_delivery_stream"
}

variable "opensearch_domain_arn" {
  description = "The ARN of the OpenSearch domain"
  type        = string
}

variable "opensearch_index_name" {
  description = "The name of the OpenSearch index"
  type        = string
}

resource "aws_iam_role" "firehose_delivery_stream_role" {
  name = "firehose_delivery_stream_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "firehose_delivery_stream_policy" {
  name        = "firehose_delivery_stream_policy"
  description = "Policy granting Firehose permissions to deliver data to OpenSearch"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "es:DescribeElasticsearchDomain",
          "es:DescribeElasticsearchDomainConfig",
          "es:ESHttpPost",
          "es:ESHttpPut",
          "es:ESHttpGet"
        ]
        Effect   = "Allow"
        Resource = var.opensearch_domain_arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_firehose_policy_to_role" {
  role       = aws_iam_role.firehose_delivery_stream_role.name
  policy_arn = aws_iam_policy.firehose_delivery_stream_policy.arn
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery_stream" {
  name        = var.firehose_delivery_stream_name
  destination = "elasticsearch"

  elasticsearch_configuration {
    domain_arn         = var.opensearch_domain_arn
    index_name         = var.opensearch_index_name
    role_arn           = aws_iam_role.firehose_delivery_stream_role.arn
    type               = "PUT"
    buffer_interval    = 300
    buffer_size        = 5
    retry_duration     = 300
    s3_backup_mode     = "Failed"
    s3_configuration {
      bucket_arn = var.s3_bucket_arn
      role_arn   = aws_iam_role.firehose_delivery_stream_role.arn
    }
  }

  depends_on = [aws_iam_role_policy_attachment.attach_firehose_policy_to_role]
}

variable "s3_bucket_arn" {
  description = "The ARN of the S3 bucket for backup"
  type        = string
}
```

### Notes
- Ensure that the `opensearch_domain_arn` and `opensearch_index_name` variables are set to the correct values for your OpenSearch domain.
- The `s3_bucket_arn` variable should be set to the ARN of an S3 bucket where Firehose can store backup data.
- The IAM policy grants Firehose the necessary permissions to deliver data to OpenSearch. Adjust the actions and resources as needed based on your specific requirements.

