### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-east-1"  # Default region, can be changed as needed
}

variable "splunk_hec_url" {
  description = "The URL of the Splunk HTTP Event Collector"
  type        = string
}

variable "splunk_hec_token" {
  description = "The token for the Splunk HTTP Event Collector"
  type        = string
  sensitive   = true
}

resource "aws_iam_role" "firehose_splunk_role" {
  name = "firehose-splunk-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "firehose_splunk_policy" {
  name        = "firehose-splunk-policy"
  description = "Policy granting necessary permissions for Kinesis Firehose to deliver data to Splunk"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_firehose_splunk_policy" {
  role       = aws_iam_role.firehose_splunk_role.name
  policy_arn = aws_iam_policy.firehose_splunk_policy.arn
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_to_splunk" {
  name        = "firehose-to-splunk"
  destination = "http_endpoint"

  http_endpoint_configuration {
    url             = var.splunk_hec_url
    name            = "splunk-http-endpoint"
    role_arn        = aws_iam_role.firehose_splunk_role.arn
    buffering_hints {
      size_in_mBs       = 6
      interval_in_seconds = 300
    }
    request_configuration {
      content_encoding = "NONE"
    }
    s3_configuration {
      role_arn = aws_iam_role.firehose_splunk_role.arn
      bucket_arn = "arn:aws:s3:::your-s3-bucket-name"  # Replace with your S3 bucket ARN
      prefix     = "firehose/"
    }
  }

  depends_on = [aws_iam_role_policy_attachment.attach_firehose_splunk_policy]
}
```

### Notes
- Ensure that the `splunk_hec_url` and `splunk_hec_token` variables are set with the correct values for your Splunk setup.
- Replace `"arn:aws:s3:::your-s3-bucket-name"` with the actual ARN of your S3 bucket.
- The IAM policy provided grants basic logging permissions. Adjust the policy as needed based on your specific requirements and security policies.

