### Description

This Terraform program creates a Kinesis Firehose Delivery Stream configured to deliver data to an OpenSearch Serverless destination. It includes the necessary IAM roles and policies to ensure proper permissions for the Firehose delivery stream to access OpenSearch Serverless. The program also sets up an OpenSearch Serverless collection and security configuration to handle incoming data.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Firehose
resource "aws_iam_role" "firehose_delivery_stream_role" {
  name = "firehose-delivery-stream-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Firehose
resource "aws_iam_policy" "firehose_delivery_stream_policy" {
  name        = "firehose-delivery-stream-policy"
  description = "Policy for Firehose to deliver data to OpenSearch Serverless"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "es:DescribeElasticsearchDomain",
          "es:DescribeElasticsearchDomainConfig",
          "es:ESHttpPut",
          "es:ESHttpPost",
          "es:ESHttpDelete",
          "es:ESHttpHead",
          "es:ESHttpGet"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the Firehose role
resource "aws_iam_role_policy_attachment" "attach_firehose_policy_to_role" {
  role       = aws_iam_role.firehose_delivery_stream_role.name
  policy_arn = aws_iam_policy.firehose_delivery_stream_policy.arn
}

# OpenSearch Serverless Collection
resource "aws_opensearchserverless_collection" "opensearchserverless_collection" {
  name = "firehose-opensearch-collection"
  type = "SEARCH"

  tags = {
    Name = "firehose-opensearch-collection"
  }
}

# OpenSearch Serverless Security Configuration
resource "aws_opensearchserverless_security_config" "opensearchserverless_security_config" {
  name = "firehose-opensearch-security-config"
  type = "saml"

  config = jsonencode({
    SAML = {
      IdpMetadataContent = "<IdP_Metadata_Content>"
      SessionDuration    = 3600
    }
  })

  tags = {
    Name = "firehose-opensearch-security-config"
  }
}

# OpenSearch Serverless Security Policy
resource "aws_opensearchserverless_security_policy" "opensearchserverless_security_policy" {
  name = "firehose-opensearch-security-policy"
  type = "data"

  policy = jsonencode({
    Rules = [
      {
        Resource = [
          "collection/firehose-opensearch-collection"
        ]
        Permission = "aoss:*"
      }
    ]
    Principal = [
      "firehose-delivery-stream-role"
    ]
  })

  depends_on = [
    aws_opensearchserverless_collection.opensearchserverless_collection,
    aws_opensearchserverless_security_config.opensearchserverless_security_config
  ]
}

# Kinesis Firehose Delivery Stream
resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery_stream" {
  name        = "firehose-delivery-stream"
  destination = "opensearch-serverless"

  opensearchserverless_destination_configuration {
    role_arn = aws_iam_role.firehose_delivery_stream_role.arn

    index_name = "firehose-index"
    buffering_hints {
      size_in_mbs = 5
      interval_in_seconds = 300
    }

    s3_configuration {
      role_arn         = aws_iam_role.firehose_delivery_stream_role.arn
      bucket_arn       = "arn:aws:s3:::your-s3-bucket-name"
      prefix           = "firehose/"
      error_output_prefix = "firehose/error/"
    }
  }

  depends_on = [
    aws_iam_role.firehose_delivery_stream_role,
    aws_opensearchserverless_collection.opensearchserverless_collection,
    aws_opensearchserverless_security_policy.opensearchserverless_security_policy
  ]
}
```

### Notes

1. **IAM Policy Permissions**: Ensure that the IAM policy attached to the Firehose role has the necessary permissions to deliver data to OpenSearch Serverless.
2. **OpenSearch Serverless Setup**: The OpenSearch Serverless collection and security configuration must be properly set up to receive data from Firehose.
3. **S3 Configuration**: Replace `"arn:aws:s3:::your-s3-bucket-name"` with the actual ARN of your S3 bucket where Firehose will temporarily store data before delivering it to OpenSearch Serverless.
4. **IdP Metadata Content**: Replace `"<IdP_Metadata_Content>"` with the actual content of your Identity Provider metadata for the OpenSearch Serverless security configuration.

