This Terraform program sets up a Kinesis Firehose Delivery Stream with an Elasticsearch destination within a VPC. It includes the necessary IAM roles and policies to grant the Firehose Delivery Stream the required permissions to interact with the Elasticsearch domain. The program also creates a VPC, subnet, and security group for the Elasticsearch domain.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# IAM Role for Kinesis Firehose
resource "aws_iam_role" "firehose_delivery_stream_role" {
  name = "firehose_delivery_stream_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Kinesis Firehose to access Elasticsearch
resource "aws_iam_policy" "firehose_delivery_stream_policy" {
  name        = "firehose_delivery_stream_policy"
  description = "Policy granting permissions to Kinesis Firehose for Elasticsearch operations"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "es:DescribeElasticsearchDomain",
          "es:DescribeElasticsearchDomainConfig",
          "es:ESHttpPost",
          "es:ESHttpPut",
          "es:ESHttpGet"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the IAM role
