  role       = aws_iam_role.firehose_delivery_stream_role.name
  policy_arn = aws_iam_policy.firehose_delivery_stream_policy.arn
}

# VPC for Elasticsearch
resource "aws_vpc" "elasticsearch_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

# Subnet within the VPC for Elasticsearch
