    instance_type = "t2.medium.elasticsearch"
  }

  ebs_options {
    ebs_enabled = true
    volume_size = 10
  }

  vpc_options {
    subnet_ids = [aws_subnet.elasticsearch_subnet.id]
    security_group_ids = [aws_security_group.elasticsearch_sg.id]
  }

  tags = {
    Name = "MyElasticsearchDomain"
  }
}

# Kinesis Firehose Delivery Stream with Elasticsearch destination
resource "aws_kinesis_firehose_delivery_stream" "kinesis_firehose_delivery_stream" {
  name        = "my-kinesis-firehose-stream"
  destination = "elasticsearch"

  elasticsearch_configuration {
    domain_arn         = aws_elasticsearch_domain.elasticsearch_domain.arn
    index_name         = "my-index"
    type_name          = "my-type"
    role_arn           = aws_iam_role.firehose_delivery_stream_role.arn
    buffering_hints {
      interval_in_seconds = 300
      size_in_mBs         = 5
    }
    retry_options {
      duration_in_seconds = 300
    }
    s3_configuration {
      role_arn = aws_iam_role.firehose_delivery_stream_role.arn
      bucket_arn = "arn:aws:s3:::my-backup-bucket"  # Replace with your S3 bucket ARN
      prefix = "firehose-backups/"
    }
  }
}
```

### Notes
- Ensure that the IAM policy grants the necessary permissions for Kinesis Firehose to interact with Elasticsearch.
- The Elasticsearch domain must be configured to allow inbound traffic from the Kinesis Firehose Delivery Stream.
- Adjust the security group rules to restrict access as needed.
- Replace `"arn:aws:s3:::my-backup-bucket"` with the actual ARN of your S3 bucket for backup purposes.

