### Description
This Terraform program sets up a Kinesis Firehose Delivery Stream with an HTTP endpoint destination, such as New Relic. It includes the necessary IAM role and policy to grant Kinesis Firehose the permissions required to deliver data to the specified HTTP endpoint. The configuration ensures that all dependencies are correctly established and that the resources are deployable with Terraform version 1.9.8 and AWS provider version 5.75.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-east-1"  # Specify your desired AWS region
}

variable "http_endpoint_url" {
  description = "The URL of the HTTP endpoint (e.g., New Relic)"
  type        = string
  default     = "https://example.com/endpoint"  # Replace with your actual endpoint URL
}

variable "role_name" {
  description = "The name of the IAM role for Kinesis Firehose"
  type        = string
  default     = "firehose_delivery_stream_role"
}

variable "policy_name" {
  description = "The name of the IAM policy for Kinesis Firehose"
  type        = string
  default     = "firehose_delivery_stream_policy"
}

resource "aws_iam_role" "firehose_delivery_stream_role" {
  name = var.role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "firehose_delivery_stream_policy" {
  name = var.policy_name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:PutLogEvents",
          "logs:CreateLogGroup",
          "logs:CreateLogStream"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_firehose_policy_to_role" {
  role       = aws_iam_role.firehose_delivery_stream_role.name
  policy_arn = aws_iam_policy.firehose_delivery_stream_policy.arn
}

resource "aws_kinesis_firehose_delivery_stream" "kinesis_firehose_delivery_stream" {
  name        = "kinesis_firehose_delivery_stream"
  destination = "http_endpoint"

  http_endpoint_configuration {
    url             = var.http_endpoint_url
    name            = "new_relic_http_endpoint"
    buffering_hints {
      size_in_mBs = 6
      interval_in_seconds = 300
    }
    request_configuration {
      content_encoding = "NONE"
    }
    s3_backup_mode = "FailedDataOnly"
    s3_configuration {
      role_arn = aws_iam_role.firehose_delivery_stream_role.arn
      bucket_arn = "arn:aws:s3:::your-backup-bucket-name"  # Replace with your S3 backup bucket ARN
      prefix = "firehose-backups/"
    }
  }

  depends_on = [aws_iam_role_policy_attachment.attach_firehose_policy_to_role]
}
```

### Notes
- Ensure that the `http_endpoint_url` variable is set to the correct URL of your HTTP endpoint (e.g., New Relic).
- Replace `"arn:aws:s3:::your-backup-bucket-name"` with the ARN of your S3 bucket where you want to store failed data backups.
- The IAM policy provided grants basic logging permissions. You may need to adjust the policy to include additional permissions depending on your specific requirements.

