### Description
The Terraform program below creates a Kinesis Firehose Delivery Stream configured to deliver data to an OpenSearch destination within a specified VPC. It includes the necessary IAM roles, policies, VPC, subnet, and security group configurations to ensure proper access and network isolation.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# IAM Role for Kinesis Firehose
resource "aws_iam_role" "firehose_delivery_stream_role" {
  name = "firehose_delivery_stream_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Kinesis Firehose
resource "aws_iam_policy" "firehose_delivery_stream_policy" {
  name        = "firehose_delivery_stream_policy"
  description = "Policy granting necessary permissions for Kinesis Firehose"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "es:DescribeElasticsearchDomain",
          "es:DescribeElasticsearchDomainConfig",
          "es:ESHttpPost",
          "es:ESHttpPut",
          "es:ESHttpGet",
          "es:ESHttpDelete",
          "es:ESHttpHead"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_firehose_policy_to_role" {
  role       = aws_iam_role.firehose_delivery_stream_role.name
  policy_arn = aws_iam_policy.firehose_delivery_stream_policy.arn
}

# VPC for Kinesis Firehose
resource "aws_vpc" "kinesis_firehose_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

# Subnet for Kinesis Firehose
resource "aws_subnet" "kinesis_firehose_subnet" {
  vpc_id            = aws_vpc.kinesis_firehose_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

# Security Group for Kinesis Firehose
resource "aws_security_group" "kinesis_firehose_sg" {
  name        = "kinesis_firehose_sg"
  description = "Security group for Kinesis Firehose"
  vpc_id      = aws_vpc.kinesis_firehose_vpc.id

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Adjust this to your specific needs
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Kinesis Firehose Delivery Stream with OpenSearch Destination
resource "aws_kinesis_firehose_delivery_stream" "kinesis_firehose_delivery_stream" {
  name        = "kinesis_firehose_delivery_stream"
  destination = "elasticsearch"

  elasticsearch_configuration {
    domain_arn         = "arn:aws:es:us-west-2:123456789012:domain/my-opensearch-domain"
    index_name         = "my-index"
    type_name          = "my-type"
    role_arn           = aws_iam_role.firehose_delivery_stream_role.arn
    buffering_hints {
      interval_in_seconds = 300
      size_in_mBs         = 5
    }
    retry_options {
      duration_in_seconds = 300
    }
    s3_configuration {
      role_arn = aws_iam_role.firehose_delivery_stream_role.arn
      bucket_arn = "arn:aws:s3:::my-backup-bucket"
      prefix = "firehose-backup/"
    }
  }

  vpc_configuration {
    role_arn            = aws_iam_role.firehose_delivery_stream_role.arn
    subnet_ids          = [aws_subnet.kinesis_firehose_subnet.id]
    security_group_ids  = [aws_security_group.kinesis_firehose_sg.id]
  }
}
```

### Notes
- Ensure the `domain_arn` in the `elasticsearch_configuration` matches your OpenSearch domain ARN.
- Adjust the `cidr_blocks` in the security group rules according to your specific network requirements.
- The `bucket_arn` in the `s3_configuration` should point to an existing S3 bucket for backup purposes.

