      interval_in_seconds = 300
    }
    compression_format = "UNCOMPRESSED"
    prefix             = "data/"
  }

  tags = {
    Name        = "KinesisFirehoseStream"
    Environment = "production"
  }
}
```

### Explanation
1. **Provider Configuration**: The AWS provider is configured with the region `us-east-1`. You can change this to your preferred region.
2. **S3 Bucket**: An S3 bucket is created with a unique name using a random string suffix.
3. **IAM Role**: An IAM role is created for the Firehose Delivery Stream to assume.
4. **IAM Policy**: An IAM policy is created to grant the necessary permissions for the Firehose role to write to the S3 bucket.
5. **Role Policy Attachment**: The IAM policy is attached to the IAM role.
6. **Kinesis Firehose Delivery Stream**: A Kinesis Firehose Delivery Stream is created with an S3 destination, configured to use the IAM role and S3 bucket created earlier. The stream is set to buffer data in 5 MB chunks or for 300 seconds before delivering it to the S3 bucket.

