### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "kinesis_stream_name" {
  description = "Name of the Kinesis stream"
  default     = "input_kinesis_stream"
}

variable "kinesis_analytics_app_name" {
  description = "Name of the Kinesis Analytics application"
  default     = "basic_kinesis_analytics_app"
}

resource "aws_iam_role" "kinesis_analytics_role" {
  name = "kinesis_analytics_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "kinesis_analytics_policy" {
  name        = "kinesis_analytics_policy"
  description = "Policy for Kinesis Analytics to access Kinesis stream"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kinesis:GetRecords",
          "kinesis:GetShardIterator",
          "kinesis:DescribeStream",
          "kinesis:ListStreams"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_kinesis_analytics_policy_to_role" {
  role       = aws_iam_role.kinesis_analytics_role.name
  policy_arn = aws_iam_policy.kinesis_analytics_policy.arn
}

resource "aws_kinesis_stream" "input_kinesis_stream" {
  name             = var.kinesis_stream_name
  shard_count      = 1
  retention_period = 24  # Retention period in hours
}

resource "aws_kinesis_analytics_application" "basic_kinesis_analytics_app" {
  name = var.kinesis_analytics_app_name

  inputs {
    name_prefix = "input_stream"

    kinesis_stream_input {
      resource_arn = aws_kinesis_stream.input_kinesis_stream.arn
      role_arn     = aws_iam_role.kinesis_analytics_role.arn
    }

    input_parallelism {
      count = 1
    }

    input_schema {
      record_format {
        record_format_type = "JSON"

        mapping_parameters {
          json_mapping_parameters {
            record_row_path = "$"
          }
        }
      }

      record_encoding = "UTF-8"

      record_columns {
        name     = "data"
        sql_type = "VARCHAR(8000)"
        mapping  = "$.data"
      }
    }
  }
}
```

