### Description
The Terraform program below creates an AWS Kendra data source with a proxy configuration. It includes the necessary IAM role and policy to ensure the data source has the required permissions. The configuration is designed to be deployable with Terraform version ~> 1.9.8 and the AWS provider version ~> 5.75.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "kendra_index_id" {
  description = "The ID of the Kendra index"
  type        = string
}

variable "data_source_name" {
  description = "The name of the Kendra data source"
  type        = string
  default     = "kendra_data_source_with_proxy"
}

variable "proxy_configuration_endpoint" {
  description = "The endpoint of the proxy server"
  type        = string
}

variable "proxy_configuration_port" {
  description = "The port of the proxy server"
  type        = number
}

variable "proxy_configuration_username" {
  description = "The username for the proxy server (optional)"
  type        = string
  default     = ""
}

variable "proxy_configuration_password" {
  description = "The password for the proxy server (optional)"
  type        = string
  default     = ""
}

resource "aws_iam_role" "kendra_data_source_role" {
  name = "kendra_data_source_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "kendra_data_source_policy" {
  name   = "kendra_data_source_policy"
  role   = aws_iam_role.kendra_data_source_role.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = [
          "arn:aws:s3:::your-bucket-name",  # Replace with your S3 bucket ARN
          "arn:aws:s3:::your-bucket-name/*" # Replace with your S3 bucket ARN
        ]
      }
    ]
  })
}

resource "aws_kendra_data_source" "kendra_data_source_with_proxy" {
  depends_on = [aws_iam_role_policy.kendra_data_source_policy]

  name           = var.data_source_name
  index_id       = var.kendra_index_id
  type           = "S3"
  role_arn       = aws_iam_role.kendra_data_source_role.arn
  s3_configuration {
    bucket_name = "your-bucket-name"  # Replace with your S3 bucket name
  }

  proxy_configuration {
    host             = var.proxy_configuration_endpoint
    port             = var.proxy_configuration_port
    username         = var.proxy_configuration_username
    password         = var.proxy_configuration_password
  }
}
```

### Notes
- Ensure that the `kendra_index_id` variable is set to the ID of your existing Kendra index.
- Replace `"your-bucket-name"` with the actual name of your S3 bucket.
- Adjust the IAM policy permissions as needed based on your specific requirements.
- The proxy configuration is optional and can be omitted if not needed.

