### Description

This Terraform program creates an Amazon Kendra index with user group resolution enabled. It includes the necessary AWS resources such as an IAM role and policy required for user group resolution. The resources are configured to ensure proper dependencies and security obligations.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "kendra_index_name" {
  description = "The name of the Kendra index"
  type        = string
  default     = "my_kendra_index"
}

variable "kendra_user_group_resolution_role_name" {
  description = "The name of the IAM role for user group resolution"
  type        = string
  default     = "kendra_user_group_resolution_role"
}

variable "kendra_user_group_resolution_policy_name" {
  description = "The name of the IAM policy for user group resolution"
  type        = string
  default     = "kendra_user_group_resolution_policy"
}

resource "aws_iam_policy" "kendra_user_group_resolution_policy" {
  name        = var.kendra_user_group_resolution_policy_name
  description = "Policy for Kendra user group resolution"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "ds:DescribeGroup",
          "ds:GetDirectoryDetails",
          "ds:ListUsers",
          "ds:ListGroups",
          "ds:ListGroupMemberships",
          "ds:ListUserAttributes",
          "ds:ListGroupAttributes"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role" "kendra_user_group_resolution_role" {
  name = var.kendra_user_group_resolution_role_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_kendra_user_group_resolution_policy" {
  role       = aws_iam_role.kendra_user_group_resolution_role.name
  policy_arn = aws_iam_policy.kendra_user_group_resolution_policy.arn
}

resource "aws_kendra_index" "kendra_index" {
  name                  = var.kendra_index_name
  edition               = "ENTERPRISE_EDITION"
  role_arn              = aws_iam_role.kendra_user_group_resolution_role.arn
  user_token_configurations {
    json_token_type_configuration {
      group_attribute_field = "groups"
      user_name_attribute_field = "username"
    }
  }

  depends_on = [aws_iam_role_policy_attachment.attach_kendra_user_group_resolution_policy]
}
```

This Terraform configuration sets up an Amazon Kendra index with user group resolution enabled. It includes an IAM role and policy that grant the necessary permissions for user group resolution. The `aws_kendra_index` resource depends on the IAM role and policy attachment to ensure proper configuration.

