### Description
The Terraform program below configures a Route 53 zone named "primary" and sets up geo-based routing policies to direct users to the nearest endpoint based on their location. The program creates two endpoints, one for the US and one for the EU, and uses Route 53's geo-location feature to route traffic accordingly.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-east-1"  # You can change this to any region where you want to create the Route 53 zone
}

variable "us_endpoint_ip" {
  description = "IP address or CNAME for the US endpoint"
  type        = string
  default     = "192.0.2.1"  # Example IP, replace with actual endpoint
}

variable "eu_endpoint_ip" {
  description = "IP address or CNAME for the EU endpoint"
  type        = string
  default     = "192.0.2.2"  # Example IP, replace with actual endpoint
}

resource "aws_route53_zone" "primary_zone" {
  name = "primary.example.com"
}

resource "aws_route53_record" "us_endpoint" {
  zone_id = aws_route53_zone.primary_zone.zone_id
  name    = "us"
  type    = "A"
  ttl     = 300
  records = [var.us_endpoint_ip]
}

resource "aws_route53_record" "eu_endpoint" {
  zone_id = aws_route53_zone.primary_zone.zone_id
  name    = "eu"
  type    = "A"
  ttl     = 300
  records = [var.eu_endpoint_ip]
}

resource "aws_route53_geo_location" "us_geo_location" {
  continent = "NA"  # North America covers US
}

resource "aws_route53_geo_location" "eu_geo_location" {
  continent = "EU"  # Europe covers EU
}

resource "aws_route53_record" "geo_us_record" {
  zone_id = aws_route53_zone.primary_zone.zone_id
  name    = "www"
  type    = "A"
  ttl     = 300
  geo {
    location_name = aws_route53_geo_location.us_geo_location.location_name
    record        = aws_route53_record.us_endpoint.name
  }
}

resource "aws_route53_record" "geo_eu_record" {
  zone_id = aws_route53_zone.primary_zone.zone_id
  name    = "www"
  type    = "A"
  ttl     = 300
  geo {
    location_name = aws_route53_geo_location.eu_geo_location.location_name
    record        = aws_route53_record.eu_endpoint.name
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured with a default region (`us-east-1`). You can change this to any other region as needed.
