### Description
The Terraform program below creates an IAM role named `eks-cluster-1` with an assume role policy allowing the `eks.amazonaws.com` service to assume the role. It attaches the `AmazonEKSClusterPolicy` IAM policy to this role. The program also defines an AWS EKS cluster named based on the provided `cluster_name` and `cluster_version` variables, associating it with the IAM role. The cluster's VPC is configured with specified subnet IDs for networking, including both private and public subnets in the specified AWS region.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the EKS cluster"
  type        = string
  default     = "us-west-2"
}

variable "cluster_name" {
  description = "The name of the EKS cluster"
  type        = string
  default     = "my-eks-cluster"
}

variable "cluster_version" {
  description = "The Kubernetes version for the EKS cluster"
  type        = string
  default     = "1.24"
}

variable "subnet_ids" {
  description = "List of subnet IDs for the EKS cluster VPC"
  type        = list(string)
  default     = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]
}

resource "aws_iam_role" "eks_cluster_1" {
  name = "eks-cluster-1"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_amazon_eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster_1.name
}

resource "aws_eks_cluster" "eks_cluster" {
  name     = var.cluster_name
  role_arn = aws_iam_role.eks_cluster_1.arn
  version  = var.cluster_version

  vpc_config {
    subnet_ids = var.subnet_ids
  }

  depends_on = [aws_iam_role_policy_attachment.attach_amazon_eks_cluster_policy]
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured with a default region (`us-west-2`), which can be overridden by setting the `region` variable.
- **Variables**: 
  - `region`: Specifies the AWS region.
  - `cluster_name`: Specifies the name of the EKS cluster.
  - `cluster_version`: Specifies the Kubernetes version for the EKS cluster.
  - `subnet_ids`: Specifies the list of subnet IDs for the EKS cluster VPC.
- **IAM Role**: An IAM role named `eks-cluster-1` is created with an assume role policy that allows `eks.amazonaws.com` to assume the role.
- **IAM Role Policy Attachment**: The `AmazonEKSClusterPolicy` is attached to the IAM role.
- **EKS Cluster**: An EKS cluster is created with the specified name, version, and VPC configuration using the subnet IDs provided. The cluster depends on the IAM role policy being attached.

