```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the infrastructure"
  default     = "us-west-2"
}

variable "ecr_repository_name" {
  description = "The name of the ECR repository"
  default     = "my-ecr-repo"
}

variable "eks_cluster_name" {
  description = "The name of the EKS cluster"
  default     = "my-eks-cluster"
}

variable "instance_type" {
  description = "The instance type for the EKS worker nodes"
  default     = "t3.medium"
}

variable "node_count" {
  description = "The number of worker nodes in the EKS cluster"
  default     = 3
}

data "aws_caller_identity" "current_identity" {}

data "aws_ecr_repository_image" "latest_stable_image" {
  repository_name = var.ecr_repository_name
  filter {
    tag_status = "TAGGED"
    tag        = "stable"
  }
}

locals {
  image_tag = data.aws_ecr_repository_image.latest_stable_image.image_tag
  aws_tags = {
    Environment = "production"
    Owner       = "terraform"
  }
  workspace_name = "default"
}

module "eks_cluster" {
  source = "terraform-aws-modules/eks/aws"

  cluster_name    = var.eks_cluster_name
  cluster_version = "1.24"
  subnets         = var.subnets
  vpc_id          = var.vpc_id
  manage_iam_policies = true
  worker_groups = [
    {
      name                 = "workers"
      instance_type        = var.instance_type
      asg_desired_capacity = var.node_count
      asg_min_size         = var.node_count
      asg_max_size         = var.node_count
    }
  ]

  tags = local.aws_tags
}

data "aws_eks_cluster" "created_eks_cluster" {
  name = module.eks_cluster.cluster_id
}

data "aws_eks_cluster_auth" "eks_cluster_auth" {
  name = module.eks_cluster.cluster_id
}

provider "helm" {
  kubernetes {
    host                   = data.aws_eks_cluster.created_eks_cluster.endpoint
    token                  = data.aws_eks_cluster_auth.eks_cluster_auth.token
    cluster_ca_certificate = base64decode(data.aws_eks_cluster.created_eks_cluster.certificate_authority[0].data)
  }
}

provider "kubernetes" {
  host                   = data.aws_eks_cluster.created_eks_cluster.endpoint
  token                  = data.aws_eks_cluster_auth.eks_cluster_auth.token
  cluster_ca_certificate = base64decode(data.aws_eks_cluster.created_eks_cluster.certificate_authority[0].data)
}
```

This Terraform configuration sets up an AWS provider, retrieves the current caller identity, fetches the latest stable ECR image, defines local variables, creates an EKS cluster using a module, retrieves information about the created EKS cluster, and configures Helm and Kubernetes providers for cluster communication. Make sure to provide the necessary variables such as `subnets` and `vpc_id` when applying this configuration.

