### Description

This Terraform program configures an OIDC identity provider for an AWS EKS cluster named "example". It includes the creation of an EKS cluster, an IAM OIDC provider, and an EKS identity provider configuration. The dependencies between these resources are preserved to ensure proper deployment order.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_eks_cluster" "example_eks_cluster" {
  name     = "example"
  role_arn = aws_iam_role.eks_cluster_role.arn

  vpc_config {
    subnet_ids = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]
  }

  depends_on = [aws_iam_role_policy_attachment.eks_cluster_policy]
}

resource "aws_iam_role" "eks_cluster_role" {
  name = "eks-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster_role.name
}

resource "aws_iam_openid_connect_provider" "oidc_provider" {
  url = "https://oidc.eks.us-west-2.amazonaws.com/id/EXAMPLE1234567890123456789012345678901234567890123456789012345678"

  client_id_list = ["sts.amazonaws.com"]

  thumbprint_list = ["SHA1:Fingerprint"]

  depends_on = [aws_eks_cluster.example_eks_cluster]
}

resource "aws_eks_identity_provider_config" "eks_identity_provider_config" {
  cluster_name = aws_eks_cluster.example_eks_cluster.name
  identity_provider_config_name = "oidc_provider_config"
  oidc {
    client_id = "sts.amazonaws.com"
    groups_claim = "groups"
    identity_provider_config_name = "oidc_provider_config"
    issuer_url = "https://oidc.eks.us-west-2.amazonaws.com/id/EXAMPLE1234567890123456789012345678901234567890123456789012345678"
    required_claims = {}
    username_claim = "sub"
    username_prefix = "idp:"
  }

  depends_on = [aws_iam_openid_connect_provider.oidc_provider]
}
```

### Notes

- Replace the `subnet_ids` in the `vpc_config` block with your actual subnet IDs.
- Replace the `url` and `thumbprint_list` in the `aws_iam_openid_connect_provider` resource with the correct OIDC issuer URL and thumbprint for your EKS cluster.
- Ensure that the `client_id`, `issuer_url`, and other parameters in the `aws_eks_identity_provider_config` resource match your specific requirements.

