Below is the Terraform HCL program that creates an AWS EKS node group linked to a specific EKS cluster, following the provided IaC Intent Graph IR. The program includes the necessary IAM roles, policy attachments, and EKS resources with the specified configurations.

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# IAM Role for EKS Node Group
resource "aws_iam_role" "eks_node_group_role" {
  name = "eks_node_group_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# Attach EKS Worker Node Policy
resource "aws_iam_role_policy_attachment" "eks_worker_node_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.eks_node_group_role.name
}

# Attach EKS CNI Policy
resource "aws_iam_role_policy_attachment" "eks_cni_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSCNIPolicy"
  role       = aws_iam_role.eks_node_group_role.name
}

# Attach EC2 Container Registry Read Only Policy
resource "aws_iam_role_policy_attachment" "ec2_container_registry_read_only_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  role       = aws_iam_role.eks_node_group_role.name
}

# EKS Cluster
resource "aws_eks_cluster" "example_eks_cluster" {
  name     = "example"
  role_arn = aws_iam_role.eks_node_group_role.arn

  vpc_config {
    subnet_ids = var.subnet_ids  # Provide your subnet IDs
  }

  enabled_cluster_log_types = ["api", "audit", "authenticator", "controllerManager", "scheduler"]

  tags = {
    Name = "example_eks_cluster"
  }
}

# EKS Node Group
resource "aws_eks_node_group" "example_eks_node_group" {
  cluster_name    = aws_eks_cluster.example_eks_cluster.name
  node_group_name = "example"
  node_role_arn   = aws_iam_role.eks_node_group_role.arn
  subnet_ids      = var.subnet_ids  # Provide your subnet IDs

  scaling_config {
    desired_size = 1
    max_size     = 2
    min_size     = 1
  }

  update_config {
    max_unavailable = 1
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_worker_node_policy_attachment,
    aws_iam_role_policy_attachment.eks_cni_policy_attachment,
    aws_iam_role_policy_attachment.ec2_container_registry_read_only_policy_attachment,
    aws_eks_cluster.example_eks_cluster
  ]

  tags = {
    Name = "example_eks_node_group"
  }
}

# Variables
variable "subnet_ids" {
  type        = list(string)
  description = "List of subnet IDs for the EKS cluster and node group"
  default     = []  # Provide your subnet IDs here
}
```

### Notes:
1. **Region**: Ensure the `region` in the provider configuration matches your desired AWS region.
2. **Subnet IDs**: You need to provide the subnet IDs for the EKS cluster and node group by setting the `subnet_ids` variable.
3. **AMI ID and Instance Type**: The example does not include AMI ID and instance type configurations. You may need to add these based on your requirements.
4. **Trust Relationship**: The IAM role has a trust relationship with the EC2 service, which is necessary for EKS node groups.

