### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"  # Ensure this is set to your desired AWS region
}

resource "aws_iam_role" "s3_admin_role" {
  name = "s3_admin_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "s3_admin_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
  role       = aws_iam_role.s3_admin_role.name
}

resource "aws_s3_bucket" "example_bucket" {
  bucket = "example-bucket"
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  tags = {
    Name        = "example-bucket"
    Environment = "production"
  }
}

resource "aws_s3_bucket_object_lock_configuration" "example_bucket_object_lock_configuration" {
  bucket = aws_s3_bucket.example_bucket.id

  rule {
    default_retention {
      mode = "COMPLIANCE"
      days = 30
    }
  }
}
```

