### Description

This Terraform program creates a Virtual Private Cloud (VPC) with both public and private subnets. It then defines an EC2 Fleet consisting of 5 On-Demand and 4 Spot Instances using a Launch Template for consistent configuration. The program ensures that all resources are properly referenced and dependent on each other as specified in the IaC Intent Graph IR.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the main VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr_block" {
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidr_block" {
  description = "CIDR block for the private subnet"
  default     = "10.0.2.0/24"
}

resource "aws_vpc" "main_vpc" {
  cidr_block = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "MainVPC"
  }
}

resource "aws_subnet" "public_subnet" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = var.public_subnet_cidr_block
  map_public_ip_on_launch = true

  tags = {
    Name = "PublicSubnet"
  }
}

resource "aws_subnet" "private_subnet" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = var.private_subnet_cidr_block

  tags = {
    Name = "PrivateSubnet"
  }
}

resource "aws_iam_role" "ec2_instance_role" {
  name = "EC2InstanceRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "ec2_instance_policy" {
  role       = aws_iam_role.ec2_instance_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_launch_template" "ec2_fleet_launch_template" {
  name_prefix = "ec2-fleet-launch-template-"
  image_id    = data.aws_ami.amazon_linux_2.id
  instance_type = "t2.micro"

  iam_instance_profile {
    name = aws_iam_role.ec2_instance_role.name
  }

  tag_specifications {
    resource_type = "instance"

    tags = {
      Name = "EC2FleetInstance"
    }
  }
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

resource "aws_ec2_fleet" "main_ec2_fleet" {
  launch_template_config {
    launch_template_specification {
      launch_template_id = aws_launch_template.ec2_fleet_launch_template.id
    }
  }

  target_capacity_specification {
    total_target_capacity = 9
    default_target_capacity_type = "spot"
  }

  on_demand_options {
    allocation_strategy = "lowest-price"
  }

  spot_options {
    allocation_strategy = "lowest-price"
  }

  depends_on = [
    aws_launch_template.ec2_fleet_launch_template,
    aws_subnet.public_subnet,
    aws_subnet.private_subnet
  ]

  tags = {
    Name = "MainEC2Fleet"
  }
}
```

This Terraform program sets up a VPC with public and private subnets, defines a Launch Template for EC2 instances, and creates an EC2 Fleet with a mix of On-Demand and Spot Instances. The IAM role and policies ensure that the EC2 instances have the necessary permissions.

