The Terraform program below sets up a basic Memcached cluster with three nodes in AWS. Each node is associated with a security group that allows necessary traffic. The security group is configured to allow inbound traffic on port 11211, which is the default port for Memcached.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_security_group" "memcached_sg" {
  name        = "memcached_sg"
  description = "Security group to allow traffic to the Memcached cluster"

  ingress {
    from_port   = 11211
    to_port     = 11211
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_instance" "memcached_node_1" {
  ami           = "ami-0c55b159cbfafe1f0"  # Example AMI ID for Amazon Linux 2
  instance_type = "t2.micro"
  vpc_security_group_ids = [aws_security_group.memcached_sg.id]
}

resource "aws_instance" "memcached_node_2" {
