  cluster_subnet_group_name = var.cluster_subnet_group_name
  vpc_security_group_ids  = var.cluster_security_group_names
}

resource "aws_redshift_endpoint_authorization" "redshift_endpoint_authorization" {
  account_with  = var.aws_account_id
  cluster_identifier = aws_redshift_cluster.redshift_cluster_1.cluster_identifier
  force_delete      = true

  depends_on = [
    aws_redshift_cluster.redshift_cluster_1,
    aws_redshift_cluster.redshift_cluster_2
  ]
}
