### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "cluster_identifier" {
  description = "The identifier for the Redshift cluster"
  default     = "my-redshift-cluster"
}

variable "node_type" {
  description = "The node type for the Redshift cluster"
  default     = "dc2.large"
}

variable "master_username" {
  description = "The master username for the Redshift cluster"
  default     = "admin"
}

variable "master_user_password" {
  description = "The master user password for the Redshift cluster"
  default     = "SecurePassword123!"
}

variable "cluster_subnet_group_name" {
  description = "The name of the Redshift cluster subnet group"
  default     = "default"
}

