### Description
This Terraform configuration sets up a highly available Amazon Redshift cluster across two availability zones (`us-east-1a` and `us-east-1b`). It includes the necessary infrastructure components such as a VPC, subnets, security groups, IAM roles, and policies. The Redshift cluster is configured to use these resources to ensure high availability.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_vpc" "redshift_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "RedshiftVPC"
  }
}

resource "aws_subnet" "redshift_subnet_a" {
  vpc_id            = aws_vpc.redshift_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-east-1a"

  tags = {
    Name = "RedshiftSubnetA"
  }
}

resource "aws_subnet" "redshift_subnet_b" {
  vpc_id            = aws_vpc.redshift_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-east-1b"

  tags = {
    Name = "RedshiftSubnetB"
  }
}

resource "aws_security_group" "redshift_sg" {
  vpc_id = aws_vpc.redshift_vpc.id

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "RedshiftSecurityGroup"
  }
}

resource "aws_iam_role" "redshift_role" {
  name = "RedshiftClusterRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "RedshiftClusterRole"
  }
}

resource "aws_iam_policy" "redshift_policy" {
  name        = "RedshiftClusterPolicy"
  description = "Policy for Redshift cluster to access other AWS services"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:*",
          "ec2:Describe*",
          "cloudwatch:*"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "RedshiftClusterPolicy"
  }
}

resource "aws_iam_role_policy_attachment" "attach_redshift_policy_to_role" {
  role       = aws_iam_role.redshift_role.name
  policy_arn = aws_iam_policy.redshift_policy.arn
}

resource "aws_redshift_cluster" "high_availability_redshift" {
  cluster_identifier      = "high-availability-redshift"
  node_type               = "dc2.large"
  master_username         = var.master_username
  master_password         = var.master_password
  iam_roles               = [aws_iam_role.redshift_role.arn]
  publicly_accessible     = false
  encrypted               = true
  enhanced_vpc_routing    = true
  number_of_nodes         = 2
  port                    = 5439
  availability_zone_relocation_enabled = true

  vpc_security_group_ids = [aws_security_group.redshift_sg.id]
  cluster_subnet_group_name = "redshift-subnet-group"

  tags = {
    Name = "HighAvailabilityRedshiftCluster"
  }
}

resource "aws_redshift_subnet_group" "redshift_subnet_group" {
  name       = "redshift-subnet-group"
  subnet_ids = [aws_subnet.redshift_subnet_a.id, aws_subnet.redshift_subnet_b.id]

  tags = {
    Name = "RedshiftSubnetGroup"
  }
}

variable "master_username" {
  description = "The username for the Redshift cluster database"
  type        = string
  default     = "admin"
}

variable "master_password" {
  description = "The password for the Redshift cluster database"
  type        = string
  sensitive   = true
  default     = "password123"
}
```

### Notes
- Ensure the IAM policy attached to the Redshift role has the necessary permissions for the cluster to operate.
- The `master_username` and `master_password` variables are provided with default values, but it's recommended to set them securely using environment variables or Terraform's secure input methods.

