### Description
This Terraform program creates a 2-node Amazon Redshift cluster and attaches a resource policy to it. It includes the necessary IAM role and policy to ensure the Redshift cluster has the required permissions. The program is designed to be deployable with Terraform version `~> 1.9.8` and AWS provider version `~> 5.75`.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# IAM Role for Redshift Cluster
resource "aws_iam_role" "redshift_cluster_role" {
  name = "redshift-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Redshift Cluster
resource "aws_iam_policy" "redshift_cluster_policy" {
  name        = "redshift-cluster-policy"
  description = "Policy for Redshift Cluster"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:Get*",
          "s3:List*"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the IAM role
resource "aws_iam_role_policy_attachment" "attach_redshift_policy_to_role" {
  role       = aws_iam_role.redshift_cluster_role.name
  policy_arn = aws_iam_policy.redshift_cluster_policy.arn
}

# First node of the Redshift cluster
resource "aws_redshift_cluster" "redshift_cluster_node1" {
  cluster_identifier = "redshift-cluster-node1"
  node_type          = "dc2.large"
  master_username    = "admin"
  master_password    = "SecurePassword123!"
  iam_roles          = [aws_iam_role.redshift_cluster_role.arn]
  cluster_subnet_group_name = "default"  # Ensure this subnet group exists
  publicly_accessible = false
}

# Second node of the Redshift cluster
resource "aws_redshift_cluster" "redshift_cluster_node2" {
  cluster_identifier = "redshift-cluster-node2"
  node_type          = "dc2.large"
  master_username    = "admin"
  master_password    = "SecurePassword123!"
  iam_roles          = [aws_iam_role.redshift_cluster_role.arn]
  cluster_subnet_group_name = "default"  # Ensure this subnet group exists
  publicly_accessible = false
}

# Resource policy for the Redshift cluster
resource "aws_redshift_resource_policy" "redshift_cluster_resource_policy" {
  resource_arn = aws_redshift_cluster.redshift_cluster_node1.cluster_identifier
  policy = jsonencode({
