### Description
This Terraform program creates an Amazon Redshift cluster with 2 nodes and sets up an endpoint access for it. The program includes the necessary provider configuration and ensures that the endpoint access resource depends on the existence of the Redshift cluster.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "cluster_identifier" {
  description = "The identifier for the Redshift cluster"
  type        = string
  default     = "my-redshift-cluster"
}

variable "node_type" {
  description = "The node type for the Redshift cluster"
  type        = string
  default     = "dc2.large"
}

variable "master_username" {
  description = "The username for the Redshift cluster"
  type        = string
  default     = "admin"
}

variable "master_password" {
  description = "The password for the Redshift cluster"
  type        = string
  sensitive   = true
  default     = "SecurePassword123!"
}

variable "endpoint_name" {
  description = "The name for the Redshift endpoint access"
  type        = string
  default     = "my-redshift-endpoint"
}

variable "subnet_group_name" {
  description = "The name of the Redshift subnet group"
  type        = string
  default     = "default"
}

resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier      = var.cluster_identifier
  node_type               = var.node_type
  master_username         = var.master_username
  master_password         = var.master_password
  cluster_subnet_group_name = var.subnet_group_name
  iam_roles               = []  # Add IAM roles if needed
}

resource "aws_redshift_endpoint_access" "redshift_endpoint_access" {
  endpoint_name         = var.endpoint_name
  cluster_identifier    = aws_redshift_cluster.redshift_cluster.id
  subnet_group_name     = var.subnet_group_name
  vpc_security_group_ids = []  # Add VPC security groups if needed
}
```

### Notes
- Ensure that the `master_password` is securely managed and not hard-coded in production environments.
- The `iam_roles` and `vpc_security_group_ids` lists are empty by default. You can populate them with the appropriate IAM roles and VPC security group IDs as needed.
- The `subnet_group_name` should be set to an existing Redshift subnet group in your AWS account.

