### Description
The Terraform program below sets up a Lambda function that is triggered by events from a DynamoDB table. It includes the necessary IAM roles and policies to ensure that the Lambda function has the appropriate permissions to access the DynamoDB table. The program also creates the DynamoDB table and the event source mapping that connects the Lambda function to the DynamoDB table.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# IAM Role for Lambda to access DynamoDB
resource "aws_iam_role" "lambda_dynamodb_event_source_mapping_role" {
  name = "lambda-dynamodb-event-source-mapping-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Lambda to access DynamoDB
resource "aws_iam_role_policy" "lambda_dynamodb_event_source_mapping_policy" {
  name = "lambda-dynamodb-event-source-mapping-policy"
  role = aws_iam_role.lambda_dynamodb_event_source_mapping_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "dynamodb:GetItem",
          "dynamodb:PutItem",
          "dynamodb:UpdateItem",
          "dynamodb:DeleteItem",
          "dynamodb:Scan",
          "dynamodb:Query"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Lambda Function
resource "aws_lambda_function" "lambda_function" {
  function_name = "lambda-dynamodb-event-source-mapping-function"
  handler       = "index.handler"
  runtime       = "python3.8"
  role          = aws_iam_role.lambda_dynamodb_event_source_mapping_role.arn

  filename         = "function.zip"  # Ensure this file is in your working directory
  source_code_hash = filebase64sha256("function.zip")
}

# DynamoDB Table
resource "aws_dynamodb_table" "dynamodb_table" {
  name           = "dynamodb-event-source-mapping-table"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }
}

# Lambda Event Source Mapping
resource "aws_lambda_event_source_mapping" "lambda_event_source_mapping" {
  event_source_arn = aws_dynamodb_table.dynamodb_table.stream_arn
  function_name    = aws_lambda_function.lambda_function.function_name
  starting_position = "LATEST"
}
```

### Notes
- Ensure that the `filename` attribute in the `aws_lambda_function` resource points to a valid ZIP file containing your Lambda function code.
- The IAM policy attached to the Lambda role grants necessary permissions for DynamoDB operations. Adjust the `Resource` field in the policy if you need more granular control over which DynamoDB tables the Lambda function can access.
- The `starting_position` for the event source mapping is set to `"LATEST"`, which means the Lambda function will start processing new items from the latest point in the DynamoDB stream. You can change this to `"TRIM_HORIZON"` if you want to process all existing items in the stream.

