### Description
This Terraform program creates a Lambda function and sets up a CloudWatch event rule to invoke the Lambda function every 15 minutes. The program includes the necessary IAM roles and policies to ensure the Lambda function has the required permissions.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"  # Specify your desired AWS region
}

# IAM Role for Lambda Execution
resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# Attach Basic Execution Policy to the Lambda Execution Role
resource "aws_iam_role_policy_attachment" "lambda_basic_execution_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_execution_role.name
}

# Lambda Function
resource "aws_lambda_function" "scheduled_lambda_function" {
  function_name = "scheduled_lambda_function"
  handler       = "index.handler"
  runtime       = "python3.8"
  role          = aws_iam_role.lambda_execution_role.arn

  filename         = "function.zip"  # Ensure this file is in the same directory as your Terraform configuration
  source_code_hash = filebase64sha256("function.zip")
}

# CloudWatch Event Rule to Trigger Lambda Function Every 15 Minutes
resource "aws_cloudwatch_event_rule" "lambda_invocation_rule" {
  name                = "lambda_invocation_rule"
  schedule_expression = "rate(15 minutes)"
}

# Set the Lambda Function as the Target for the CloudWatch Event Rule
resource "aws_cloudwatch_event_target" "lambda_invocation_target" {
  rule      = aws_cloudwatch_event_rule.lambda_invocation_rule.name
  target_id = "TriggerScheduledLambdaFunction"
  arn       = aws_lambda_function.scheduled_lambda_function.arn
}

# Grant CloudWatch Permission to Invoke the Lambda Function
resource "aws_lambda_permission" "allow_cloudwatch_to_invoke_lambda" {
  statement_id  = "AllowExecutionFromCloudWatch"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.scheduled_lambda_function.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.lambda_invocation_rule.arn
}
```

### Notes
- Ensure that the `function.zip` file containing your Lambda function code is present in the same directory as your Terraform configuration.
- Adjust the `region` variable in the `provider` block to your desired AWS region.
- The `handler` and `runtime` in the `aws_lambda_function` resource should match your Lambda function's entry point and runtime environment.

