### Description
This Terraform program sets up an infrastructure to trigger an AWS Lambda function named `test_lambda` whenever an EC2 image is created. The program includes the necessary IAM roles, policies, SNS topics, subscriptions, CloudWatch event rules, and Lambda permissions to achieve this functionality.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# IAM Role for Lambda Execution
resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Lambda Execution
resource "aws_iam_policy" "lambda_policy" {
  name        = "lambda_policy"
  description = "Policy for Lambda execution"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach IAM Policy to Lambda Execution Role
resource "aws_iam_role_policy_attachment" "attach_lambda_policy_to_role" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = aws_iam_policy.lambda_policy.arn
}

# Lambda Function
resource "aws_lambda_function" "test_lambda" {
  function_name = "test_lambda"
  handler       = "index.handler"
  runtime       = "python3.8"
  role          = aws_iam_role.lambda_execution_role.arn

  filename         = "lambda_function_payload.zip"
  source_code_hash = filebase64sha256("lambda_function_payload.zip")
}

# SNS Topic for EC2 Image Creation Events
resource "aws_sns_topic" "ec2_image_created_topic" {
  name = "ec2_image_created_topic"
}

# Subscribe Lambda to SNS Topic
resource "aws_sns_topic_subscription" "subscribe_lambda_to_sns" {
  topic_arn = aws_sns_topic.ec2_image_created_topic.arn
  protocol  = "lambda"
  endpoint  = aws_lambda_function.test_lambda.arn
}

# CloudWatch Event Rule for EC2 Image Creation
resource "aws_cloudwatch_event_rule" "ec2_image_creation_rule" {
  name        = "ec2_image_creation_rule"
  description = "Rule to trigger Lambda on EC2 image creation"
  event_pattern = jsonencode({
    "source": ["aws.ec2"],
    "detail-type": ["EC2 Image State Change"],
    "detail": {
      "state": ["available"]
    }
  })
}

# Target Lambda from CloudWatch Event Rule
resource "aws_cloudwatch_event_target" "target_lambda_from_ec2_event" {
  rule      = aws_cloudwatch_event_rule.ec2_image_creation_rule.name
  target_id = "trigger_test_lambda"
  arn       = aws_lambda_function.test_lambda.arn
}

# Allow CloudWatch to Invoke Lambda
resource "aws_lambda_permission" "allow_cloudwatch_to_invoke_lambda" {
  statement_id  = "AllowExecutionFromCloudWatch"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.test_lambda.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.ec2_image_creation_rule.arn
}
```

### Notes
- Ensure that the `lambda_function_payload.zip` file exists in the same directory as your Terraform configuration file, or update the `filename` attribute to point to the correct location.
- The IAM policy (`aws_iam_policy.lambda_policy`) grants basic logging permissions to the Lambda function. You may need to adjust the policy to include additional permissions based on your specific requirements.
- The CloudWatch event pattern is set to trigger the Lambda function when an EC2 image state changes to "available". Adjust the event pattern if you need to match different events.

