  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "my_lambda_function" {
  function_name = var.lambda_function_name
  handler       = var.lambda_handler
  runtime       = var.runtime
  role          = aws_iam_role.lambda_execution_role.arn

  s3_bucket = var.s3_bucket
  s3_key    = var.s3_key
}
```

### Notes
- Ensure that the S3 bucket (`your-s3-bucket-name`) and the key (`lambda.js`) are correctly set to point to the location of your Lambda code.
- The `lambda_handler` variable should match the entry point of your JavaScript file. Adjust it if your handler is different.
- The `runtime` variable specifies the Node.js version. Adjust it if you are using a different runtime.

