  default     = "index.handler"  # Adjust based on your lambda.js structure
}

variable "runtime" {
  description = "The runtime environment for the Lambda function"
  default     = "nodejs14.x"  # Adjust based on your Node.js version
}

variable "s3_bucket" {
  description = "The S3 bucket where the Lambda function code is stored"
  type        = string
}

variable "s3_key" {
  description = "The key (path) to the Lambda function code in the S3 bucket"
  type        = string
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution_policy" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "my_lambda_function" {
  function_name = var.lambda_function_name
  handler       = var.lambda_handler
  runtime       = var.runtime
  role          = aws_iam_role.lambda_execution_role.arn

  s3_bucket = var.s3_bucket
  s3_key    = var.s3_key
}
```

### Notes
1. **S3 Bucket Configuration**: Ensure that the `lambda.js` file is uploaded to the specified S3 bucket (`var.s3_bucket`) with the correct key (`var.s3_key`). The bucket should have the appropriate permissions to allow the Lambda function to access it.
2. **Handler Adjustment**: The `handler` variable should be adjusted based on the structure of your `lambda.js` file. For example, if your entry point is different, update the `handler` accordingly.
3. **Runtime Version**: The `runtime` variable should match the Node.js version you are using. Adjust it if necessary.

This Terraform configuration ensures that the Lambda function has the necessary permissions to execute and access the required resources.

