### Description
The Terraform program below defines an AWS CloudWatch metric alarm named 'foobar' that monitors the 'CPUUtilization' metric of AWS EC2 instances. The alarm triggers when the average CPU utilization is greater than or equal to 80% for two consecutive 2-minute periods. No actions are taken when there's insufficient data. The AWS provider is configured with a default region, and the necessary IAM role is created to allow CloudWatch to access the EC2 metrics.

### Terraform HCL Program
```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  default     = "us-west-2"
}

resource "aws_iam_role" "cloudwatch_role" {
  name = "cloudwatch_ec2_metrics_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudwatch.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "cloudwatch_policy" {
  name        = "cloudwatch_ec2_metrics_policy"
  description = "Policy to allow CloudWatch to read EC2 metrics"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:DescribeInstances",
          "cloudwatch:GetMetricData",
          "cloudwatch:GetMetricStatistics",
          "cloudwatch:ListMetrics"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "cloudwatch_policy_attachment" {
  role       = aws_iam_role.cloudwatch_role.name
  policy_arn = aws_iam_policy.cloudwatch_policy.arn
}

resource "aws_cloudwatch_metric_alarm" "alarma_foobar" {
  alarm_name          = "foobar"
  comparison_operator = "GreaterThanOrEqualToThreshold"
  evaluation_periods  = 2
  metric_name         = "CPUUtilization"
  namespace           = "AWS/EC2"
  period              = 120
  statistic           = "Average"
  threshold           = 80
  treat_missing_data  = "notBreaching"

  dimensions = {
    InstanceId = "*"
  }

  depends_on = [aws_iam_role_policy_attachment.cloudwatch_policy_attachment]
}
```

This Terraform configuration sets up the necessary AWS resources, including an IAM role and policy, to allow CloudWatch to monitor EC2 instance metrics. The CloudWatch metric alarm is then defined to trigger based on the specified conditions.

