### Description
This Terraform program creates a Kinesis Streaming Destination for a specific DynamoDB table. It includes the creation of a DynamoDB table, a Kinesis stream, a DynamoDB stream to capture changes from the DynamoDB table, and a Kinesis stream consumer to consume records from the DynamoDB stream. The program ensures that all dependencies are correctly handled and that the necessary permissions are set up.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "dynamodb_table_name" {
  description = "The name of the DynamoDB table"
  type        = string
  default     = "my_dynamodb_table"
}

variable "kinesis_stream_name" {
  description = "The name of the Kinesis stream"
  type        = string
  default     = "my_kinesis_stream"
}

resource "aws_dynamodb_table" "dynamodb_table" {
  name           = var.dynamodb_table_name
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  stream_view_type = "NEW_AND_OLD_IMAGES"
}

resource "aws_kinesis_stream" "kinesis_stream" {
  name             = var.kinesis_stream_name
  shard_count      = 1
  retention_period = 24
}

resource "aws_dynamodb_stream" "dynamodb_stream" {
  table_name = aws_dynamodb_table.dynamodb_table.name
  stream_view_type = aws_dynamodb_table.dynamodb_table.stream_view_type
}

resource "aws_kinesis_stream_consumer" "kinesis_stream_consumer" {
  stream_arn = aws_kinesis_stream.kinesis_stream.arn
  consumer_name = "my_kinesis_consumer"
  depends_on = [aws_dynamodb_stream.dynamodb_stream]
}

resource "aws_iam_role" "kinesis_consumer_role" {
  name = "kinesis_consumer_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesis.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "kinesis_consumer_policy" {
  name = "kinesis_consumer_policy"
  role = aws_iam_role.kinesis_consumer_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "dynamodb:GetRecords",
          "dynamodb:GetShardIterator",
          "dynamodb:DescribeStream",
          "dynamodb:ListStreams"
        ]
        Effect = "Allow"
        Resource = aws_dynamodb_stream.dynamodb_stream.arn
      }
    ]
  })
}

resource "aws_kinesis_stream_consumer" "kinesis_stream_consumer_with_role" {
  stream_arn = aws_kinesis_stream.kinesis_stream.arn
  consumer_name = "my_kinesis_consumer_with_role"
  role_arn = aws_iam_role.kinesis_consumer_role.arn
  depends_on = [aws_dynamodb_stream.dynamodb_stream, aws_iam_role_policy.kinesis_consumer_policy]
}
```

