### Description
The Terraform program below creates an Amazon DynamoDB Accelerator (DAX) cluster with the specified node type (`dax.r4.large`) and replication factor (`1`). The program includes a provider configuration for AWS, ensuring that the DAX cluster is deployed in a region where DAX is supported. The IAM role required for DAX operations is also created and attached to the cluster.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"  # Ensure this region supports DAX
}

variable "dax_cluster_name" {
  description = "The name of the DAX cluster"
  default     = "my-dax-cluster"
}

variable "dax_subnet_group_name" {
  description = "The name of the DAX subnet group"
  default     = "my-dax-subnet-group"
}

variable "dax_security_group_name" {
  description = "The name of the DAX security group"
  default     = "my-dax-security-group"
}

resource "aws_iam_role" "dax_role" {
  name = "dax-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "dax.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "dax_policy" {
  role       = aws_iam_role.dax_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonDAXFullAccess"
}

resource "aws_dax_subnet_group" "dax_subnet_group" {
