}

resource "aws_security_group" "dax_security_group" {
  name        = var.dax_security_group_name
  description = "Security group for DAX cluster"
  vpc_id      = "vpc-12345678"  # Replace with actual VPC ID

  ingress {
    from_port   = 8111
    to_port     = 8111
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_dax_cluster" "dax_cluster" {
  cluster_name       = var.dax_cluster_name
  iam_role_arn       = aws_iam_role.dax_role.arn
  node_type          = "dax.r4.large"
  replication_factor = 1
  subnet_group_name  = aws_dax_subnet_group.dax_subnet_group.name
  security_group_ids = [aws_security_group.dax_security_group.id]
}
```

### Notes
- Ensure that the `subnet_ids` and `vpc_id` are replaced with actual values from your AWS environment.
- The region specified in the provider configuration (`us-west-2`) should be one where DAX is supported. Adjust it as necessary.
- The security group allows inbound traffic on port 8111, which is the default port for DAX. Adjust the security group rules as needed for your security requirements.

