### Description

The Terraform program below creates a SageMaker user profile resource along with the necessary IAM role and policy. The IAM role is created first, followed by the IAM policy, which is then attached to the IAM role. Finally, the SageMaker user profile is created, depending on the existence of the IAM role.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "sagemaker_user_profile_name" {
  description = "The name of the SageMaker user profile"
  type        = string
  default     = "example-user-profile"
}

variable "sagemaker_user_profile_domain_id" {
  description = "The ID of the SageMaker domain where the user profile will be created"
  type        = string
  default     = "example-domain-id"
}

resource "aws_iam_role" "sagemaker_user_profile_role" {
  name = "sagemaker-user-profile-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "sagemaker_user_profile_policy" {
  name        = "sagemaker-user-profile-policy"
  description = "Policy for SageMaker user profile"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "sagemaker:*",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "ecr:BatchCheckLayerAvailability",
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_sagemaker_user_profile_policy" {
  role       = aws_iam_role.sagemaker_user_profile_role.name
  policy_arn = aws_iam_policy.sagemaker_user_profile_policy.arn
}

resource "aws_sagemaker_user_profile" "sagemaker_user_profile" {
  domain_id = var.sagemaker_user_profile_domain_id
  user_profile_name = var.sagemaker_user_profile_name
  user_settings {
    execution_role_arn = aws_iam_role.sagemaker_user_profile_role.arn
  }
}
```

This Terraform configuration ensures that the SageMaker user profile is created with the appropriate IAM role and policy, allowing it to perform necessary SageMaker operations. Adjust the `region`, `sagemaker_user_profile_name`, and `sagemaker_user_profile_domain_id` variables as needed for your specific use case.

