### Description
This Terraform program creates a VPC in the `us-east-1` region, along with two subnets in availability zones `us-east-1a` and `us-east-1b`. It then launches an EC2 instance in each subnet using the latest Amazon Linux 2 AMI with a `t2.micro` instance type. Each instance is associated with an EBS volume of 50 GB. The program ensures proper dependencies between resources and includes necessary configurations for security groups and key pairs.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the main VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_us_east_1a_cidr_block" {
  description = "CIDR block for the subnet in us-east-1a"
  default     = "10.0.1.0/24"
}

variable "subnet_us_east_1b_cidr_block" {
  description = "CIDR block for the subnet in us-east-1b"
  default     = "10.0.2.0/24"
}

variable "instance_type" {
  description = "EC2 instance type"
  default     = "t2.micro"
}

variable "ebs_volume_size" {
  description = "Size of the EBS volume in GB"
  default     = 50
}

resource "aws_vpc" "main_vpc" {
  cidr_block = var.vpc_cidr_block

  tags = {
    Name = "MainVPC"
  }
}

resource "aws_subnet" "subnet_us_east_1a" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = var.subnet_us_east_1a_cidr_block
  availability_zone = "us-east-1a"

  tags = {
    Name = "SubnetUS-East-1A"
  }
}

resource "aws_subnet" "subnet_us_east_1b" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = var.subnet_us_east_1b_cidr_block
  availability_zone = "us-east-1b"

  tags = {
    Name = "SubnetUS-East-1B"
  }
}

resource "aws_security_group" "allow_ssh" {
  name        = "AllowSSH"
  description = "Allow SSH inbound traffic"
  vpc_id      = aws_vpc.main_vpc.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "AllowSSH"
  }
}

resource "aws_key_pair" "my_key_pair" {
  key_name   = "my-key-pair"
  public_key = file("~/.ssh/id_rsa.pub")

  tags = {
    Name = "MyKeyPair"
  }
}

resource "aws_instance" "instance_us_east_1a" {
  ami           = data.aws_ami.amazon_linux_2.id
  instance_type = var.instance_type
  subnet_id     = aws_subnet.subnet_us_east_1a.id
  key_name      = aws_key_pair.my_key_pair.key_name
  vpc_security_group_ids = [aws_security_group.allow_ssh.id]

  tags = {
    Name = "InstanceUS-East-1A"
  }
}

resource "aws_instance" "instance_us_east_1b" {
  ami           = data.aws_ami.amazon_linux_2.id
  instance_type = var.instance_type
  subnet_id     = aws_subnet.subnet_us_east_1b.id
  key_name      = aws_key_pair.my_key_pair.key_name
  vpc_security_group_ids = [aws_security_group.allow_ssh.id]

  tags = {
    Name = "InstanceUS-East-1B"
  }
}

resource "aws_ebs_volume" "volume_us_east_1a" {
  availability_zone = aws_instance.instance_us_east_1a.availability_zone
  size              = var.ebs_volume_size

  tags = {
    Name = "VolumeUS-East-1A"
  }
}

