Below is the complete Terraform HCL program that creates a public and private subnet, an IAM role, an instance profile, a launch template, and an EC2 Fleet with 5 On-Demand and 4 Spot Instances using the AWS Linux 2 AMI.

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr_block" {
  description = "CIDR block for the public subnet"
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidr_block" {
  description = "CIDR block for the private subnet"
  default     = "10.0.2.0/24"
}

resource "aws_vpc" "main_vpc" {
  cidr_block = var.vpc_cidr_block

  tags = {
    Name = "MainVPC"
  }
}

resource "aws_internet_gateway" "main_igw" {
  vpc_id = aws_vpc.main_vpc.id

  tags = {
    Name = "MainIGW"
  }
}

resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.main_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main_igw.id
  }

  tags = {
    Name = "PublicRouteTable"
  }
}

resource "aws_subnet" "public_subnet" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = var.public_subnet_cidr_block
  map_public_ip_on_launch = true
  availability_zone = "us-west-2a"

  tags = {
    Name = "PublicSubnet"
  }
}

resource "aws_route_table_association" "public_subnet_assoc" {
  subnet_id      = aws_subnet.public_subnet.id
  route_table_id = aws_route_table.public_route_table.id
}

resource "aws_subnet" "private_subnet" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = var.private_subnet_cidr_block
  availability_zone = "us-west-2b"

  tags = {
    Name = "PrivateSubnet"
  }
}

resource "aws_iam_role" "ec2_fleet_role" {
  name = "ec2-fleet-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "EC2FleetRole"
  }
}

resource "aws_iam_instance_profile" "ec2_fleet_instance_profile" {
  name = "ec2-fleet-instance-profile"
  roles = [aws_iam_role.ec2_fleet_role.name]

  tags = {
    Name = "EC2FleetInstanceProfile"
  }
}

resource "aws_ami" "latest_aws_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}

resource "aws_launch_template" "ec2_fleet_launch_template" {
  name_prefix   = "ec2-fleet-launch-template-"
  image_id      = aws_ami.latest_aws_linux_2.id
  instance_type = "t2.micro"
  iam_instance_profile {
    name = aws_iam_instance_profile.ec2_fleet_instance_profile.name
  }

  tags = {
    Name = "EC2FleetLaunchTemplate"
  }
}

resource "aws_ec2_fleet" "main_ec2_fleet" {
  launch_template_config {
    launch_template_specification {
      launch_template_name = aws_launch_template.ec2_fleet_launch_template.name
    }
    override {
      instance_type     = "t2.micro"
      weighted_capacity = 1
      subnet_id         = aws_subnet.public_subnet.id
    }
    override {
      instance_type     = "t2.micro"
      weighted_capacity = 1
      subnet_id         = aws_subnet.private_subnet.id
    }
  }

  target_capacity_specification {
    total_target_capacity = 9
    default_target_capacity_type = "spot"
  }

  on_demand_options {
    allocation_strategy = "lowest-price"
  }

  spot_options {
    allocation_strategy = "lowest-price"
  }

  tags = {
    Name = "MainEC2Fleet"
  }
}
```

