### Description

This Terraform configuration sets up a VPC with two private subnets, an EFS file system, and two EC2 instances running the latest Amazon Linux AMI. The EC2 instances are configured to access the EFS file system through mount targets in their respective subnets. An IAM role and policy are created to grant the necessary permissions for the EC2 instances to access the EFS file system.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the main VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "CIDR blocks for the private subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

resource "aws_vpc" "main_vpc" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_subnet" "private_subnet_1" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = var.subnet_cidr_blocks[0]
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "private_subnet_2" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = var.subnet_cidr_blocks[1]
  availability_zone = "us-west-2b"
}

resource "aws_iam_role" "ec2_instance_role" {
  name = "ec2-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "ec2_efs_access_policy" {
  name        = "ec2-efs-access-policy"
  description = "Policy to allow EC2 instances to access EFS"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite",
          "elasticfilesystem:ClientRootAccess"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_ec2_efs_policy" {
  role       = aws_iam_role.ec2_instance_role.name
  policy_arn = aws_iam_policy.ec2_efs_access_policy.arn
}

resource "aws_efs_file_system" "shared_efs" {
  tags = {
    Name = "shared-efs"
  }
}

resource "aws_efs_mount_target" "efs_mount_target_1" {
  file_system_id = aws_efs_file_system.shared_efs.id
  subnet_id      = aws_subnet.private_subnet_1.id
}

resource "aws_efs_mount_target" "efs_mount_target_2" {
  file_system_id = aws_efs_file_system.shared_efs.id
  subnet_id      = aws_subnet.private_subnet_2.id
}

resource "aws_instance" "ec2_instance_1" {
  ami           = data.aws_ami.amazon_linux_latest.id
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.private_subnet_1.id
  iam_instance_profile = aws_iam_role.ec2_instance_role.name

  tags = {
    Name = "ec2-instance-1"
  }

  user_data = <<-EOF
              #!/bin/bash
              yum install -y amazon-efs-utils
              mkdir /mnt/efs
              mount -t efs ${aws_efs_file_system.shared_efs.id}:/ /mnt/efs
              EOF
}

resource "aws_instance" "ec2_instance_2" {
  ami           = data.aws_ami.amazon_linux_latest.id
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.private_subnet_2.id
  iam_instance_profile = aws_iam_role.ec2_instance_role.name

  tags = {
    Name = "ec2-instance-2"
  }

  user_data = <<-EOF
              #!/bin/bash
              yum install -y amazon-efs-utils
              mkdir /mnt/efs
              mount -t efs ${aws_efs_file_system.shared_efs.id}:/ /mnt/efs
              EOF
}

data "aws_ami" "amazon_linux_latest" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }
}
```

This Terraform configuration creates the necessary resources to set up a VPC with two private subnets, an EFS file system, and two EC2 instances that can access the EFS file system. The EC2 instances are launched with the latest Amazon Linux AMI and have the necessary IAM role attached to access the EFS file system.

