### Description:
The Terraform program below creates a managed Amazon MSK (Managed Streaming for Apache Kafka) cluster with 3 broker nodes in the `us-east-1` region. The program includes necessary configurations such as the cluster name, instance type, and VPC settings. It also sets up an IAM role required for the MSK cluster to operate.

### Terraform HCL Program:
```hcl
provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  description = "The name of the MSK cluster"
  default     = "my-msk-cluster"
}

variable "instance_type" {
  description = "The instance type for the MSK brokers"
  default     = "kafka.m5.large"
}

variable "vpc_id" {
  description = "The ID of the VPC where the MSK cluster will be deployed"
  default     = "vpc-12345678"
}

variable "subnet_ids" {
  description = "A list of subnet IDs for the MSK cluster"
  type        = list(string)
  default     = ["subnet-12345678", "subnet-87654321", "subnet-abcdef01"]
}

variable "security_group_id" {
  description = "The ID of the security group for the MSK cluster"
  default     = "sg-12345678"
}

resource "aws_iam_role" "msk_role" {
  name = "${var.cluster_name}_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonMSKFullAccess"
  role       = aws_iam_role.msk_role.name
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = var.cluster_name
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3
  broker_node_group_info {
    client_subnets = var.subnet_ids
    instance_type  = var.instance_type
    security_groups = [var.security_group_id]
    ebs_volume_size = 100
  }

  encryption_info {
    encryption_in_transit {
      client_broker = "TLS_PLAINTEXT"
    }
  }

  enhanced_monitoring = "PER_BROKER"

  tags = {
    Name = var.cluster_name
  }

  depends_on = [aws_iam_role_policy_attachment.msk_policy]
}
```

### Explanation:
- **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
- **Variables**: Several variables are defined to allow customization of the cluster name, instance type, VPC, subnets, and security group.
- **IAM Role**: An IAM role is created for the MSK cluster with the necessary permissions attached.
- **MSK Cluster**: The `aws_msk_cluster` resource is defined with 3 broker nodes, specifying the instance type, subnets, security group, and other configurations like encryption and monitoring.

This Terraform configuration can be deployed using Terraform version `~> 1.9.8` and the AWS provider version `~> 5.75`.

