The Terraform program below creates a managed Amazon MSK cluster with 3 broker nodes in the `us-east-2` region. It also sets up an IAM role and attaches the necessary policy for the MSK cluster.

```hcl
provider "aws" {
  region = "us-east-2"
}

resource "aws_iam_role" "msk_cluster_role" {
  name = "msk-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_cluster_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonMSKFullAccess"
  role       = aws_iam_role.msk_cluster_role.name
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "msk-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

