LLM Output #0:
### Description
This Terraform program creates a managed Amazon Managed Streaming for Apache Kafka (MSK) cluster in the `us-east-1` region. The MSK cluster is configured to log its activities to a CloudWatch log group. The program also sets up an IAM role and attaches the necessary policies to allow the MSK cluster to operate.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-east-1"
}

variable "cluster_name" {
  description = "The name of the MSK cluster"
  default     = "my-msk-cluster"
}

variable "instance_type" {
  description = "The instance type for the MSK brokers"
  default     = "kafka.m5.large"
}

variable "num_broker_nodes" {
  description = "The number of broker nodes in the MSK cluster"
  default     = 3
}

variable "kafka_version" {
  description = "The version of Kafka to use"
  default     = "2.8.0"
}

variable "client_subnets" {
  description = "A list of subnets where the MSK cluster will be deployed"
  type        = list(string)
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "security_groups" {
  description = "A list of security groups for the MSK cluster"
  type        = list(string)
  default     = ["sg-12345678"]
}

resource "aws_iam_role" "msk_service_role" {
  name = "${var.cluster_name}_msk_service_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_service_role_policy" {
  role       = aws_iam_role.msk_service_role.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonMSKFullAccess"
}

resource "aws_cloudwatch_log_group" "msk_logs" {
  name              = "${var.cluster_name}_msk_logs"
  retention_in_days = 30
}

resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = var.cluster_name
  kafka_version          = var.kafka_version
  number_of_broker_nodes = var.num_broker_nodes
  broker_node_group_info {
    client_subnets = var.client_subnets
    instance_type  = var.instance_type
    security_groups = var.security_groups
    ebs_volume_size = 100
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = "arn:aws:kms:us-east-1:123456789012:key/abcd1234-abcd-1234-abcd-1234abcd1234"
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_logs.name
      }
    }
  }

  tags = {
    Name = var.cluster_name
  }
}
```

### Notes
- Ensure that the `client_subnets` and `security_groups` variables are correctly set to your VPC configuration.
- The `encryption_at_rest_kms_key_arn` should be replaced with a valid KMS key ARN in your AWS account.
- The `aws_iam_role_policy_attachment` uses the `AmazonMSKFullAccess` policy, which provides full access to MSK. Adjust the policy as needed based on your security requirements.

