Below is the complete Terraform HCL program that creates a managed MSK cluster in `us-east-1` and configures it to log to an S3 bucket. The program includes the necessary IAM roles and policies as specified in the IaC Intent Graph IR.

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "msk_logs_bucket" {
  bucket = "msk-logs-bucket-${random_string.bucket_suffix.result}"
  acl    = "private"

  versioning {
    enabled = true
  }

  logging {
    target_bucket = aws_s3_bucket.logging_bucket.bucket
    target_prefix = "msk-logs/"
  }
}

resource "aws_s3_bucket" "logging_bucket" {
  bucket = "msk-logging-bucket-${random_string.bucket_suffix.result}"
  acl    = "log-delivery-write"
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

resource "aws_iam_role" "msk_service_role" {
  name = "msk-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "msk_logging_policy" {
  name        = "msk-logging-policy"
  description = "Policy for MSK to log to S3"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:PutObject",
          "s3:PutObjectAcl"
        ]
        Effect = "Allow"
        Resource = "${aws_s3_bucket.msk_logs_bucket.arn}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_msk_logging_policy" {
  role       = aws_iam_role.msk_service_role.name
  policy_arn = aws_iam_policy.msk_logging_policy.arn
}

resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "managed-msk-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3
  broker_node_group_info {
    instance_type = "kafka.m5.large"
    client_subnets  = ["subnet-12345678", "subnet-87654321"]
    security_groups = ["sg-12345678"]
    ebs_volume_size = 100
  }

  encryption_info {
    encryption_in_transit {
      client_broker = "TLS_PLAINTEXT"
    }
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = false
      }
      firehose {
        enabled   = false
      }
      s3 {
        enabled         = true
        bucket_arn      = aws_s3_bucket.msk_logs_bucket.arn
        prefix          = "msk-logs/"
      }
    }
  }

  tags = {
    Name = "ManagedMSKCluster"
  }
}
```

### Explanation:
1. **Provider Configuration**: The AWS provider is configured to use the `us-east-1` region.
2. **S3 Buckets**: Two S3 buckets are created:
   - `msk_logs_bucket`: This bucket stores the MSK logs.
   - `logging_bucket`: This bucket is used for logging purposes.
3. **Random String**: A random string is generated to ensure unique bucket names.
4. **IAM Role**: An IAM role named `msk-service-role` is created with a trust policy allowing the MSK service to assume it.
5. **IAM Policy**: An IAM policy named `msk-logging-policy` is created to allow the MSK service to write logs to the `msk_logs_bucket`.
6. **IAM Role Policy Attachment**: The logging policy is attached to the MSK service role.
7. **MSK Cluster**: A managed MSK cluster is created with the specified configurations, including logging to the S3 bucket.

This Terraform configuration ensures that the MSK cluster is properly set up with logging to an S3 bucket, adhering to the provided IaC Intent Graph IR.

