### Description
The Terraform program below creates a managed Amazon Managed Streaming for Apache Kafka (MSK) cluster in the `us-east-1` region. The MSK cluster is configured to log its data to an Amazon Kinesis Firehose delivery stream. The necessary IAM roles and policies are created to allow the MSK cluster to deliver logs to the Kinesis Firehose.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_kinesis_firehose_delivery_stream" "msk_logs_firehose" {
  name        = "msk-logs-firehose"
  destination = "s3"

  s3_configuration {
    bucket_arn = var.s3_bucket_arn
    role_arn   = aws_iam_role.msk_firehose_role.arn
  }
}

resource "aws_iam_role" "msk_firehose_role" {
  name = "msk-firehose-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "msk_firehose_policy" {
  name        = "msk-firehose-policy"
  description = "Policy allowing MSK to deliver logs to Kinesis Firehose"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "firehose:PutRecord",
          "firehose:PutRecordBatch"
        ]
        Effect = "Allow"
        Resource = aws_kinesis_firehose_delivery_stream.msk_logs_firehose.arn
      },
      {
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Effect = "Allow"
        Resource = [var.s3_bucket_arn, "${var.s3_bucket_arn}/*"]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_msk_firehose_policy" {
  role       = aws_iam_role.msk_firehose_role.name
  policy_arn = aws_iam_policy.msk_firehose_policy.arn
}

resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "managed-msk-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = var.subnet_ids
    instance_type  = "kafka.m5.large"
    security_groups = [var.security_group_id]
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = false
      }
      firehose {
        delivery_stream = aws_kinesis_firehose_delivery_stream.msk_logs_firehose.name
        enabled         = true
      }
      s3 {
        enabled = false
      }
    }
  }

  tags = {
    Name = "ManagedMSKCluster"
  }
}

variable "s3_bucket_arn" {
  description = "ARN of the S3 bucket where logs will be delivered"
  type        = string
}

variable "subnet_ids" {
  description = "List of subnet IDs for the MSK cluster"
  type        = list(string)
}

variable "security_group_id" {
  description = "Security group ID for the MSK cluster"
  type        = string
}
```

### Notes
- Ensure that the `s3_bucket_arn`, `subnet_ids`, and `security_group_id` variables are provided when applying this Terraform configuration.
- The MSK cluster is configured to log to Kinesis Firehose, which then delivers the logs to an S3 bucket. Adjust the `destination` and configuration within the `aws_kinesis_firehose_delivery_stream` resource if you want to change the destination (e.g., to Elasticsearch).

