LLM Output #0:
### Description
This Terraform program creates a managed Amazon Managed Streaming for Apache Kafka (MSK) cluster with encryption at rest. It includes the creation of an AWS Key Management Service (KMS) key for encryption, an IAM role for the MSK cluster service operations, an IAM policy with necessary permissions, and attaches this policy to the IAM role. The MSK cluster is then created, referencing the KMS key and the IAM role.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

resource "aws_kms_key" "msk_cluster_encryption_key" {
  description             = "KMS key for MSK cluster encryption at rest"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_iam_role" "msk_cluster_service_role" {
  name = "msk-cluster-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "msk_cluster_policy" {
  name        = "msk-cluster-policy"
  description = "Policy for MSK cluster operations"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kms:DescribeKey",
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*"
        ]
        Effect   = "Allow"
        Resource = aws_kms_key.msk_cluster_encryption_key.arn
      },
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_msk_policy_to_role" {
  role       = aws_iam_role.msk_cluster_service_role.name
  policy_arn = aws_iam_policy.msk_cluster_policy.arn
}

resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "managed-msk-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3
  broker_node_group_info {
    instance_type = "kafka.m5.large"
    ebs_volume_size = 100
    client_subnets = ["subnet-12345678", "subnet-87654321"]  # Replace with your subnet IDs
    security_groups = ["sg-12345678"]  # Replace with your security group ID
    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = aws_kms_key.msk_cluster_encryption_key.arn
  }

  enhanced_monitoring = "PER_BROKER"

  tags = {
    Name = "ManagedMSKCluster"
  }
}
```

### Notes
- Ensure that the `client_subnets` and `security_groups` in the `aws_msk_cluster` resource are replaced with your actual subnet and security group IDs.
- The KMS key policy grants necessary permissions for MSK to encrypt and decrypt data using the key.
- The IAM policy attached to the MSK service role allows MSK to perform logging operations in CloudWatch Logs. Adjust the policy as needed based on your specific requirements.

