LLM Output #0:
The Terraform program below creates a managed Amazon MSK (Managed Streaming for Kafka) cluster with JMX Exporter and Node Exporter enabled. It also sets up the necessary IAM roles and policies required for the MSK cluster to function properly.

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "cluster_name" {
  description = "The name of the MSK cluster"
  default     = "my-msk-cluster"
}

variable "instance_type" {
  description = "The instance type for the MSK brokers"
  default     = "kafka.m5.large"
}

variable "num_brokers" {
  description = "The number of broker nodes in the MSK cluster"
  default     = 3
}

variable "jmx_exporter_enabled" {
  description = "Whether to enable JMX Exporter"
  default     = true
}

variable "node_exporter_enabled" {
  description = "Whether to enable Node Exporter"
  default     = true
}

resource "aws_iam_role" "msk_cluster_role" {
  name = "msk-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "msk_cluster_policy" {
  name        = "msk-cluster-policy"
  description = "Policy for MSK cluster operations"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeVpcs",
          "ec2:DescribeInternetGateways",
          "ec2:DescribeRouteTables",
          "ec2:DescribeAvailabilityZones",
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "cloudwatch:PutMetricData"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_msk_policy_to_role" {
  role       = aws_iam_role.msk_cluster_role.name
  policy_arn = aws_iam_policy.msk_cluster_policy.arn
}

resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = var.cluster_name
  kafka_version          = "2.8.1"
  number_of_broker_nodes = var.num_brokers

  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-87654321"]  # Replace with your subnet IDs
    instance_type  = var.instance_type
    security_groups = ["sg-12345678"]  # Replace with your security group ID
  }

  encryption_info {
    encryption_in_transit {
      client_broker = "TLS_PLAINTEXT"
    }
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = var.jmx_exporter_enabled
      }
      node_exporter {
        enabled_in_broker = var.node_exporter_enabled
      }
    }
  }

  depends_on = [aws_iam_role_policy_attachment.attach_msk_policy_to_role]
}
```

### Explanation:
1. **Provider Configuration**: The AWS provider is configured with a specific region (`us-west-2`).
2. **Variables**: Several variables are defined to allow customization of the cluster name, instance type, number of brokers, and whether JMX and Node Exporters are enabled.
3. **IAM Role**: An IAM role (`msk_cluster_role`) is created with a trust policy allowing EC2 to assume it.
4. **IAM Policy**: An IAM policy (`msk_cluster_policy`) is created with permissions necessary for MSK operations.
5. **IAM Role Policy Attachment**: The policy is attached to the IAM role.
