### Description
The Terraform program below creates a serverless Amazon Managed Streaming for Apache Kafka (MSK) cluster with 3 broker nodes. It also sets up the necessary IAM role and policy to allow the MSK cluster to operate. The program ensures that all dependencies are correctly handled through Terraform references.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "cluster_name" {
  description = "The name of the MSK serverless cluster"
  default     = "msk-serverless-cluster"
}

variable "vpc_id" {
  description = "The ID of the VPC where the MSK cluster will be deployed"
  default     = "vpc-12345678"  # Replace with your VPC ID
}

variable "subnet_ids" {
  description = "A list of subnet IDs for the MSK cluster"
  type        = list(string)
  default     = ["subnet-12345678", "subnet-87654321"]  # Replace with your subnet IDs
}

resource "aws_iam_policy" "msk_serverless_policy" {
  name        = "msk-serverless-policy"
  description = "Policy required for MSK serverless cluster."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "kafka:DescribeCluster",
          "kafka:GetBootstrapBrokers",
          "kafka:ListClusters",
          "kafka:ListConfigurationRevisions",
          "kafka:ListKafkaVersions",
          "kafka:ListNodes",
          "kafka:ListScramSecrets",
          "kafka:ListTagsForResource",
          "kafka:TagResource",
          "kafka:UntagResource"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role" "msk_serverless_role" {
  name = "msk-serverless-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_msk_serverless_policy" {
  role       = aws_iam_role.msk_serverless_role.name
  policy_arn = aws_iam_policy.msk_serverless_policy.arn
}

resource "aws_msk_serverless_cluster" "msk_serverless_cluster" {
  cluster_name = var.cluster_name
  vpc_config {
    subnet_ids = var.subnet_ids
  }

  client_authentication {
    sasl {
      iam = true
    }
  }

  tags = {
    Name = var.cluster_name
  }

  depends_on = [aws_iam_role_policy_attachment.attach_msk_serverless_policy]
}
```

### Notes
- Ensure that the `vpc_id` and `subnet_ids` variables are set to your actual VPC and subnet IDs.
- The IAM policy provided is a basic example and may need to be adjusted based on your specific requirements and security policies.
- The `aws_msk_serverless_cluster` resource is used instead of `aws_msk_cluster` as it specifically targets serverless MSK clusters.

