### Description
The Terraform program below creates a serverless Amazon Managed Streaming for Apache Kafka (MSK) cluster with 3 broker nodes in the `us-east-1` region. It also sets up an IAM role and attaches the necessary policy to allow the MSK service to operate. The configuration ensures that all dependencies are correctly handled through Terraform references.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-east-1"
}

variable "msk_cluster_name" {
  type        = string
  description = "The name of the MSK cluster"
  default     = "my-msk-cluster"
}

variable "msk_instance_type" {
  type        = string
  description = "The instance type for the MSK brokers"
  default     = "kafka.m5.large"
}

variable "msk_kafka_version" {
  type        = string
  description = "The Kafka version for the MSK cluster"
  default     = "2.8.0"
}

resource "aws_iam_role" "msk_service_role" {
  name = "msk-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "msk_service_role_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonMSKFullAccess"
  role       = aws_iam_role.msk_service_role.name
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = var.msk_cluster_name
  kafka_version          = var.msk_kafka_version
  number_of_broker_nodes = 3
  broker_node_group_info {
    client_subnets         = ["subnet-12345678", "subnet-87654321"] # Replace with actual subnet IDs
    instance_type          = var.msk_instance_type
    ebs_volume_size        = 100
    security_groups        = ["sg-12345678"] # Replace with actual security group ID
  }

  encryption_info {
    encryption_in_transit {
      client_broker = "TLS_PLAINTEXT"
    }
  }

  enhanced_monitoring = "PER_BROKER"

  tags = {
    Name = var.msk_cluster_name
  }

  depends_on = [aws_iam_role_policy_attachment.msk_service_role_policy]
}
```

### Notes
- Ensure that the subnet IDs and security group IDs in the `broker_node_group_info` block are replaced with actual values from your AWS account.
- The `aws_iam_role` assumes EC2 for demonstration purposes; adjust the trust policy if needed for your specific use case.
- The `aws_msk_cluster` resource includes basic encryption and monitoring settings. Adjust these settings based on your security requirements.

