### Description

The Terraform program below creates a serverless Amazon Managed Streaming for Apache Kafka (MSK) cluster in the `us-east-2` region. It includes the necessary IAM role and policy attachments required for the MSK service to operate. The program ensures that all resources are properly defined and interconnected according to the provided IaC Intent Graph IR.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-2"
}

variable "cluster_name" {
  description = "The name of the MSK cluster"
  default     = "my-msk-cluster"
}

variable "instance_type" {
  description = "The instance type for the MSK brokers"
  default     = "kafka.t3.small"
}

variable "client_subnets" {
  description = "List of subnets for the MSK cluster"
  type        = list(string)
  default     = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]
}

variable "security_groups" {
  description = "List of security groups for the MSK cluster"
  type        = list(string)
  default     = ["sg-0123456789abcdef0"]
}

resource "aws_iam_role" "msk_service_role" {
  name = "msk-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "msk_service_policy" {
  name        = "msk-service-policy"
  path        = "/"
  description = "Policy for MSK service role"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:DescribeNetworkInterfaces",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeSubnets",
          "ec2:DescribeVpcs",
          "ec2:DescribeInternetGateways",
          "ec2:DescribeRouteTables",
          "ec2:DescribeAvailabilityZones",
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "cloudwatch:PutMetricData"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_msk_policy_to_role" {
  role       = aws_iam_role.msk_service_role.name
  policy_arn = aws_iam_policy.msk_service_policy.arn
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = var.cluster_name
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3
  broker_node_group_info {
    client_subnets = var.client_subnets
    instance_type  = var.instance_type
    security_groups = var.security_groups
    ebs_volume_size = 100
  }

  encryption_info {
    encryption_in_transit {
      client_broker = "TLS_PLAINTEXT"
    }
  }

  enhanced_monitoring = "PER_BROKER"

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = "/aws/msk/${var.cluster_name}"
      }
    }
  }

  tags = {
    Name = var.cluster_name
  }

  depends_on = [aws_iam_role.msk_service_role]
}
```

This Terraform configuration sets up a serverless MSK cluster with the specified parameters, including the necessary IAM role and policy attachments. Ensure that the subnet IDs and security group IDs provided in the `client_subnets` and `security_groups` variables are valid and exist in your AWS account.

