LLM Output #0:
### Description
The Terraform program below creates an Amazon Managed Streaming for Apache Kafka (MSK) cluster with three broker nodes. It also sets up an S3 bucket, a CloudWatch log group, and a Kinesis Firehose delivery stream to handle logging from the MSK brokers. The MSK cluster is configured with encryption at rest and open monitoring. An IAM role and policy are created to grant the necessary permissions for the MSK service to operate.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# S3 Bucket to store logs from MSK brokers
resource "aws_s3_bucket" "msk_logs_bucket" {
  bucket = "msk-logs-bucket-${var.environment}"
  acl    = "private"

  versioning {
    enabled = true
  }
}

# CloudWatch Log Group to collect logs from MSK brokers
resource "aws_cloudwatch_log_group" "msk_log_group" {
  name              = "/aws/msk/cluster/${var.cluster_name}"
  retention_in_days = 30
}

# Kinesis Firehose Delivery Stream to deliver logs to S3 and CloudWatch
resource "aws_kinesis_firehose_delivery_stream" "msk_firehose_delivery_stream" {
  name        = "msk-firehose-delivery-stream-${var.environment}"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn           = aws_iam_role.msk_service_role.arn
    bucket_arn         = aws_s3_bucket.msk_logs_bucket.arn
    prefix             = "msk-logs/"
    buffering_interval = 60
    buffering_size     = 5

    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.msk_log_group.name
      log_stream_name = "msk-firehose-log-stream"
    }
  }
}

# IAM Role for MSK service
resource "aws_iam_role" "msk_service_role" {
  name = "msk-service-role-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for MSK service
resource "aws_iam_policy" "msk_service_policy" {
  name        = "msk-service-policy-${var.environment}"
  description = "Policy for MSK service to access S3, CloudWatch, and MSK operations"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:PutObject",
          "s3:AbortMultipartUpload",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = [aws_s3_bucket.msk_logs_bucket.arn, "${aws_s3_bucket.msk_logs_bucket.arn}/*"]
      },
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "kafka:DescribeCluster",
          "kafka:DescribeConfiguration",
          "kafka:DescribeTopic",
          "kafka:GetBootstrapBrokers",
          "kafka:ListClusters",
          "kafka:ListConfigurations",
          "kafka:ListTopics"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the MSK service role
resource "aws_iam_role_policy_attachment" "attach_msk_policy_to_role" {
  role       = aws_iam_role.msk_service_role.name
  policy_arn = aws_iam_policy.msk_service_policy.arn
}

# MSK Cluster with logging and encryption
resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = var.cluster_name
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type = "kafka.m5.large"
    client_subnets  = var.subnet_ids
    security_groups = [var.security_group_id]

    storage_info {
      ebs_storage_info {
        volume_size = 1000
      }
    }
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = var.kms_key_arn
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = aws_cloudwatch_log_group.msk_log_group.name
      }
      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.msk_firehose_delivery_stream.name
      }
      s3 {
        enabled = false
      }
    }
  }

  tags = {
    Name = var.cluster_name
  }
}

# Variables
variable "environment" {
  description = "Environment name (e.g., dev, prod)"
  type        = string
  default     = "dev"
}

variable "cluster_name" {
  description = "Name of the MSK cluster"
  type        = string
  default     = "my-msk-cluster"
}

variable "subnet_ids" {
  description = "List of subnet IDs for the MSK cluster"
  type        = list(string)
  default     = []
}

variable "security_group_id" {
  description = "Security group ID for the MSK cluster"
  type        = string
  default     = ""
}

variable "kms_key_arn" {
  description = "ARN of the KMS key for encryption at rest"
  type        = string
  default     = ""
}
```

This Terraform configuration ensures that all dependencies are correctly handled, and the MSK cluster is properly set up with logging and encryption. Adjust the variables and defaults as needed for your specific environment.

