LLM Output #0:
### Description
The Terraform program below creates a managed Amazon Managed Streaming for Apache Kafka (MSK) cluster with 3 broker nodes in the `us-east-1` region. It also sets up an MSK Connect custom plugin using a `debezium.zip` file stored in S3 and creates an MSK Connect connector that uses this custom plugin to connect to the MSK cluster. The necessary IAM roles and policies are created and attached to ensure proper permissions.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"
}

# MSK Cluster
resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "msk-cluster"
  kafka_version          = "2.8.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets  = ["subnet-12345678", "subnet-87654321"] # Replace with your subnet IDs
    instance_type   = "m5.large"
    security_groups = ["sg-12345678"] # Replace with your security group ID
  }

  encryption_info {
    encryption_in_transit {
      client_broker = "TLS_PLAINTEXT"
    }
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
    }
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = "/aws/msk/cluster-logs"
      }
    }
  }

  tags = {
    Name = "msk-cluster"
  }
}

# IAM Role for MSK Connect Custom Plugin
resource "aws_iam_role" "msk_connect_plugin_role" {
  name = "msk-connect-plugin-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "connect.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for MSK Connect Custom Plugin
resource "aws_iam_policy" "msk_connect_plugin_policy" {
  name        = "msk-connect-plugin-policy"
  description = "Policy for MSK Connect custom plugin"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = [
          "arn:aws:s3:::your-bucket-name/debezium.zip", # Replace with your S3 bucket and object path
          "arn:aws:s3:::your-bucket-name"
        ]
      }
    ]
  })
}

# Attach Policy to IAM Role for MSK Connect Custom Plugin
resource "aws_iam_role_policy_attachment" "attach_msk_connect_plugin_policy" {
  role       = aws_iam_role.msk_connect_plugin_role.name
  policy_arn = aws_iam_policy.msk_connect_plugin_policy.arn
}

# MSK Connect Custom Plugin
resource "aws_mskconnect_custom_plugin" "msk_connect_custom_plugin" {
  name         = "debezium-custom-plugin"
  location_uri = "s3://your-bucket-name/debezium.zip" # Replace with your S3 bucket and object path

  depends_on = [aws_iam_role.msk_connect_plugin_role]
}

# IAM Role for MSK Connect Connector
resource "aws_iam_role" "msk_connect_connector_role" {
  name = "msk-connect-connector-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "connect.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for MSK Connect Connector
resource "aws_iam_policy" "msk_connect_connector_policy" {
  name        = "msk-connect-connector-policy"
  description = "Policy for MSK Connect connector"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kafka:DescribeCluster",
          "kafka:GetBootstrapBrokers",
          "kafka:ListClusters"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach Policy to IAM Role for MSK Connect Connector
resource "aws_iam_role_policy_attachment" "attach_msk_connect_connector_policy" {
  role       = aws_iam_role.msk_connect_connector_role.name
  policy_arn = aws_iam_policy.msk_connect_connector_policy.arn
}

# MSK Connect Connector
resource "aws_mskconnect_connector" "msk_connect_connector" {
  name             = "msk-connect-connector"
  connector_type   = "custom"
  kafka_cluster_arn = aws_msk_cluster.msk_cluster.arn
  service_execution_role_arn = aws_iam_role.msk_connect_connector_role.arn

  connector_configuration = jsonencode({
    "connector.class" = "io.debezium.connector.kafka.KafkaConnector",
    "tasks.max"       = "1",
    "topics"          = "your-topic-name", # Replace with your topic name
    "key.converter"   = "org.apache.kafka.connect.storage.StringConverter",
    "value.converter" = "org.apache.kafka.connect.json.JsonConverter",
    "plugin.name"     = "debezium-custom-plugin"
  })

  depends_on = [
    aws_msk_cluster.msk_cluster,
    aws_mskconnect_custom_plugin.msk_connect_custom_plugin
  ]
}
```

### Notes
- Ensure that the `debezium.zip` file is uploaded to the specified S3 bucket and that the bucket and object path are correctly referenced in the `location_uri` attribute of the `aws_mskconnect_custom_plugin` resource.
- Replace placeholder values such as subnet IDs, security group IDs, S3 bucket names, and topic names with actual values relevant to your environment.
- Adjust IAM policies and roles according to specific security requirements.

