provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# S3 bucket to store MSK logs
resource "aws_s3_bucket" "msk_logs_bucket" {
  bucket = "msk-logs-bucket-${random_string.suffix.result}"
  acl    = "private"

  versioning {
    enabled = true
  }
}

# CloudWatch log group for MSK
resource "aws_cloudwatch_log_group" "msk_log_group" {
  name              = "/aws/msk/cluster"
  retention_in_days = 30
}

# Kinesis Firehose delivery stream
resource "aws_kinesis_firehose_delivery_stream" "msk_firehose_delivery_stream" {
  name        = "msk-firehose-delivery-stream"
  destination = "s3"

  s3_configuration {
    role_arn           = aws_iam_role.firehose_role.arn
    bucket_arn         = aws_s3_bucket.msk_logs_bucket.arn
    prefix             = "logs/"
    buffering_hints {
      size_in_mBs = 5
      interval_in_seconds = 300
    }
    compression_format = "UNCOMPRESSED"
  }

  extended_s3_configuration {
    role_arn           = aws_iam_role.firehose_role.arn
    bucket_arn         = aws_s3_bucket.msk_logs_bucket.arn
    prefix             = "logs/"
    buffering_hints {
      size_in_mBs = 5
      interval_in_seconds = 300
    }
    compression_format = "UNCOMPRESSED"
    cloudwatch_logging_options {
      enabled         = true
      log_group_name  = aws_cloudwatch_log_group.msk_log_group.name
      log_stream_name = "firehose-log-stream"
    }
  }
}

# IAM role for Firehose
resource "aws_iam_role" "firehose_role" {
  name = "msk-firehose-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
