### Description
The Terraform program below creates an Amazon RDS MySQL cluster with 10 instances, each allocated 100 GB of storage. The cluster and its instances are configured to ensure high availability and reliability. The program includes necessary IAM roles and policies to manage the RDS resources securely.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "db_cluster_identifier" {
  description = "Identifier for the RDS cluster"
  default     = "my-mysql-cluster"
}

variable "db_instance_class" {
  description = "Instance class for the RDS instances"
  default     = "db.r5.large"
}

variable "allocated_storage" {
  description = "Allocated storage for each instance in GB"
  default     = 100
}

variable "engine" {
  description = "Database engine"
  default     = "aurora-mysql"
}

variable "engine_version" {
  description = "Engine version"
  default     = "8.0.mysql_aurora.3.02.0"
}

variable "master_username" {
  description = "Master username for the database"
  default     = "admin"
}

variable "master_password" {
  description = "Master password for the database"
  type        = string
  sensitive   = true
}

resource "aws_iam_role" "rds_iam_role" {
  name = "${var.db_cluster_identifier}_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "rds_iam_role_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSAugmentedDBPermissions"
  role       = aws_iam_role.rds_iam_role.name
}

resource "aws_rds_cluster" "mysql_cluster" {
  cluster_identifier      = var.db_cluster_identifier
  engine                  = var.engine
  engine_version          = var.engine_version
  master_username         = var.master_username
  master_password         = var.master_password
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
  iam_database_authentication_enabled = true
  db_subnet_group_name    = aws_db_subnet_group.default.name
  vpc_security_group_ids  = [aws_security_group.default.id]
  db_cluster_parameter_group_name = aws_db_cluster_parameter_group.default.name
  iam_roles               = [aws_iam_role.rds_iam_role.arn]
}

resource "aws_db_subnet_group" "default" {
  name       = "${var.db_cluster_identifier}_subnet_group"
  subnet_ids = data.aws_subnet_ids.default.ids

  tags = {
    Name = "${var.db_cluster_identifier}_subnet_group"
  }
}

data "aws_subnet_ids" "default" {
  vpc_id = var.vpc_id
}

resource "aws_security_group" "default" {
  name        = "${var.db_cluster_identifier}_security_group"
  description = "Security group for RDS cluster"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_cluster_parameter_group" "default" {
  name        = "${var.db_cluster_identifier}_parameter_group"
  family      = "aurora-mysql8.0"
  description = "Parameter group for RDS cluster"

  parameter {
    name         = "character_set_server"
    value        = "utf8mb4"
    apply_method = "pending-reboot"
  }

  parameter {
    name         = "collation_server"
    value        = "utf8mb4_unicode_ci"
    apply_method = "pending-reboot"
  }
}

resource "aws_rds_cluster_instance" "mysql_cluster_instance_1" {
  identifier              = "${var.db_cluster_identifier}-instance-1"
  cluster_identifier      = aws_rds_cluster.mysql_cluster.id
  instance_class          = var.db_instance_class
