### Description
This Terraform program creates an AWS Virtual Private Cloud (VPC) with a single subnet. It also sets up two Network Access Control Lists (NACLs): one for controlling ingress traffic and another for egress traffic. The ingress NACL allows SSH traffic, while the egress NACL allows all outbound traffic.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "MainVPC"
  }
}

resource "aws_subnet" "main_subnet" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"

  tags = {
    Name = "MainSubnet"
  }
}

resource "aws_network_acl" "subnet_ingress_acl" {
  vpc_id = aws_vpc.main_vpc.id

  tags = {
    Name = "IngressNACL"
  }
}

resource "aws_network_acl" "subnet_egress_acl" {
  vpc_id = aws_vpc.main_vpc.id

  tags = {
    Name = "EgressNACL"
  }
}

resource "aws_network_acl_rule" "ingress_allow_ssh" {
  network_acl_id = aws_network_acl.subnet_ingress_acl.id
  rule_number    = 100
  egress         = false
  protocol       = "tcp"
  rule_action    = "allow"
  from_port      = 22
  to_port        = 22
  cidr_block     = "0.0.0.0/0"

  tags = {
    Name = "AllowSSHIngress"
  }
}

resource "aws_network_acl_rule" "egress_allow_all" {
  network_acl_id = aws_network_acl.subnet_egress_acl.id
  rule_number    = 100
  egress         = true
  protocol       = "-1"
  rule_action    = "allow"
  cidr_block     = "0.0.0.0/0"

  tags = {
    Name = "AllowAllEgress"
  }
}

# Associate the NACLs with the subnet
resource "aws_network_acl_association" "subnet_ingress_acl_assoc" {
  network_acl_id = aws_network_acl.subnet_ingress_acl.id
  subnet_id      = aws_subnet.main_subnet.id
}

resource "aws_network_acl_association" "subnet_egress_acl_assoc" {
  network_acl_id = aws_network_acl.subnet_egress_acl.id
  subnet_id      = aws_subnet.main_subnet.id
}
```

This Terraform configuration sets up the required VPC, subnet, and NACLs with the specified rules. The `aws_network_acl_association` resources ensure that the NACLs are correctly associated with the subnet.

