The Terraform program below sets up a basic AWS Neptune cluster with a custom parameter group and restricts connections to two specified subnets. The configuration includes:

1. **AWS Provider Configuration**: Sets the region to `us-west-2`.
2. **IAM Role**: Creates an IAM role with the necessary permissions for Neptune operations.
3. **Neptune Cluster Parameter Group**: Defines a custom parameter group for the Neptune cluster.
4. **Neptune Subnet Group**: Specifies a subnet group that includes two example subnets.
5. **Neptune Cluster**: Creates a Neptune cluster using the custom parameter group and subnet group.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "neptune_role" {
  name = "neptune-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "neptune.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "neptune_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonNeptuneFullAccess"
  role       = aws_iam_role.neptune_role.name
}

resource "aws_neptune_cluster_parameter_group" "neptune_cluster_parameter_group" {
  family        = "neptune1"
  name          = "custom-neptune-parameter-group"
  description   = "Custom parameter group for Neptune cluster"

  parameter {
    name  = "neptune_query_timeout"
    value = "60000"
  }

  parameter {
    name  = "neptune_enable_audit_log"
    value = "1"
  }
}

resource "aws_neptune_subnet_group" "neptune_subnet_group" {
  name       = "neptune-subnet-group"
  subnet_ids = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]

  tags = {
    Name = "neptune-subnet-group"
  }
}

resource "aws_neptune_cluster" "neptune_cluster" {
  cluster_identifier              = "my-neptune-cluster"
  engine                          = "neptune"
  engine_version                  = "1.2.0.1"
  backup_retention_period         = 5
  preferred_backup_window         = "07:00-09:00"
  skip_final_snapshot             = true
  iam_database_authentication_enabled = true
  neptune_subnet_group_name       = aws_neptune_subnet_group.neptune_subnet_group.name
  neptune_cluster_parameter_group_name = aws_neptune_cluster_parameter_group.neptune_cluster_parameter_group.name
  iam_roles                       = [aws_iam_role.neptune_role.arn]

  tags = {
    Name = "my-neptune-cluster"
  }
}
```

