### Description

This Terraform program creates an AWS Chime Voice Connector with encryption and log media metrics. It includes the necessary resources such as `aws_chime_voice_connector`, `aws_chime_voice_connector_termination`, `aws_chime_voice_connector_logging`, `aws_kms_key`, and `aws_chime_voice_connector_origination`. The dependencies between these resources are preserved to ensure proper creation order. The AWS provider is configured with a default region, and default values are provided for variables where applicable.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  default     = "us-east-1"
}

variable "voice_connector_name" {
  description = "The name of the Chime Voice Connector"
  default     = "MyChimeVoiceConnector"
}

variable "termination_cps_limit" {
  description = "The maximum number of concurrent calls per second for the termination settings"
  default     = 10
}

variable "termination_calling_regions" {
  description = "The calling regions for the termination settings"
  type        = list(string)
  default     = ["US", "CA"]
}

variable "logging_enabled" {
  description = "Whether logging is enabled for the voice connector"
  type        = bool
  default     = true
}

variable "origination_routes" {
  description = "The origination routes for the voice connector"
  type        = list(object({
    host             = string
    port             = number
    protocol         = string
    priority         = number
    weight           = number
    caller_id_number = string
  }))
  default     = []
}

resource "aws_chime_voice_connector" "voice_connector" {
  name               = var.voice_connector_name
  require_encryption = true
}

resource "aws_kms_key" "encryption_key" {
  description             = "KMS key for Chime Voice Connector encryption"
  deletion_window_in_days = 10
}

resource "aws_chime_voice_connector_termination" "voice_connector_termination" {
  voice_connector_id = aws_chime_voice_connector.voice_connector.id
  cps_limit          = var.termination_cps_limit
  calling_regions    = var.termination_calling_regions
}

resource "aws_chime_voice_connector_logging" "voice_connector_logging" {
  voice_connector_id = aws_chime_voice_connector.voice_connector.id
  enable_media_metric = var.logging_enabled
}

resource "aws_chime_voice_connector_origination" "voice_connector_origination" {
  voice_connector_id = aws_chime_voice_connector.voice_connector.id

  route {
    host             = var.origination_routes[0].host
    port             = var.origination_routes[0].port
    protocol         = var.origination_routes[0].protocol
    priority         = var.origination_routes[0].priority
