### Description
The Terraform program below creates an AWS Redshift cluster with endpoint access from two subnets. It includes the necessary resources such as a VPC, two subnets, a security group, and the Redshift cluster itself. The subnets are placed in different Availability Zones to ensure high availability. The security group is configured to allow necessary inbound and outbound traffic for Redshift.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "redshift_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "redshift-vpc"
  }
}

resource "aws_subnet" "subnet_1" {
  vpc_id            = aws_vpc.redshift_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"

  tags = {
    Name = "redshift-subnet-1"
  }
}

resource "aws_subnet" "subnet_2" {
  vpc_id            = aws_vpc.redshift_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"

  tags = {
    Name = "redshift-subnet-2"
  }
}

resource "aws_security_group" "redshift_sg" {
  name        = "redshift-sg"
  description = "Security group for Redshift cluster"
  vpc_id      = aws_vpc.redshift_vpc.id

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "redshift-sg"
  }
}

resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier      = "my-redshift-cluster"
  node_type               = "dc2.large"
  master_username         = "admin"
  master_password         = "SecurePassword123!"
  iam_roles               = []
  cluster_type            = "single-node"
  publicly_accessible     = false
  enhanced_vpc_routing    = true
  vpc_security_group_ids  = [aws_security_group.redshift_sg.id]
  availability_zone       = aws_subnet.subnet_1.availability_zone
  preferred_maintenance_window = "sun:07:00-sun:07:30"

  tags = {
    Name = "my-redshift-cluster"
  }

  depends_on = [
    aws_subnet.subnet_1,
    aws_subnet.subnet_2,
    aws_security_group.redshift_sg
  ]
}
```

### Notes
- Ensure that the `master_password` is securely managed and rotated regularly.
- The `iam_roles` list is currently empty. You may need to add IAM roles if your Redshift cluster requires them.
- The `availability_zone` for the Redshift cluster is set to the availability zone of `subnet_1`. If you need to specify multiple subnets for high availability, you may need to adjust the configuration accordingly.

