### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# SNS topic to receive Redshift events
resource "aws_sns_topic" "redshift_event_topic" {
  name = "redshift-event-topic"
}

# IAM role for Redshift event subscription
resource "aws_iam_role" "redshift_event_subscription_role" {
  name = "redshift-event-subscription-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

# IAM policy allowing Redshift event subscription to publish to SNS
resource "aws_iam_policy" "redshift_event_subscription_policy" {
  name        = "redshift-event-subscription-policy"
  description = "Policy allowing Redshift event subscription to publish to SNS"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "sns:Publish"
        ]
        Effect   = "Allow"
        Resource = aws_sns_topic.redshift_event_topic.arn
      }
    ]
  })
}

# Attach policy to IAM role
resource "aws_iam_role_policy_attachment" "attach_redshift_event_policy_to_role" {
  role       = aws_iam_role.redshift_event_subscription_role.name
  policy_arn = aws_iam_policy.redshift_event_subscription_policy.arn
}

# Redshift cluster to generate events
resource "aws_redshift_cluster" "example_redshift_cluster" {
  cluster_identifier = "example-redshift-cluster"
  node_type          = "dc2.large"
  master_username    = "admin"
  master_password    = "SecurePassword123!"
  iam_roles          = [aws_iam_role.redshift_event_subscription_role.arn]
  cluster_subnet_group_name = "default"  # Ensure this subnet group exists
}

# Event subscription for Redshift cluster
resource "aws_redshift_event_subscription" "redshift_event_subscription" {
  name                = "redshift-event-subscription"
  sns_topic_arn       = aws_sns_topic.redshift_event_topic.arn
  source_ids          = [aws_redshift_cluster.example_redshift_cluster.cluster_identifier]
  source_type         = "cluster"
  event_categories    = ["configuration", "management", "monitoring", "security"]
  severity            = "ERROR"
  enabled             = true
  tags = {
    Name = "RedshiftEventSubscription"
  }
}
