### Description
The Terraform program below creates an AWS S3 bucket to store images for a website. It also sets up an IAM role and policy to manage access to the S3 bucket. The S3 bucket is configured to be publicly readable, allowing images to be displayed on a website without authentication.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"  # Default region, can be changed as needed
}

resource "aws_s3_bucket" "image_storage_bucket" {
  bucket = "my-image-storage-bucket-${random_string.bucket_suffix.result}"
  acl    = "public-read"

  tags = {
    Name        = "ImageStorageBucket"
    Environment = "production"
  }
}

resource "aws_iam_role" "s3_access_role" {
  name = "S3AccessRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name        = "S3AccessRole"
    Environment = "production"
  }
}

resource "aws_iam_policy" "s3_read_policy" {
  name        = "S3ReadPolicy"
  description = "Policy to allow read access to the S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = [
          aws_s3_bucket.image_storage_bucket.arn,
          "${aws_s3_bucket.image_storage_bucket.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_s3_read_policy" {
  role       = aws_iam_role.s3_access_role.name
  policy_arn = aws_iam_policy.s3_read_policy.arn
}

resource "aws_s3_bucket_policy" "bucket_public_read_policy" {
  bucket = aws_s3_bucket.image_storage_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "s3:GetObject"
        Effect = "Allow"
        Principal = "*"
        Resource = "${aws_s3_bucket.image_storage_bucket.arn}/*"
      }
    ]
  })
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}
```

### Explanation
- **AWS Provider**: Configured to use the `us-west-2` region.
- **S3 Bucket**: Created with a unique name using a random string suffix to ensure uniqueness. The bucket is set to `public-read` ACL.
- **IAM Role**: Created with a trust policy allowing EC2 instances to assume the role.
- **IAM Policy**: Defines a policy allowing read access to the S3 bucket.
- **IAM Role Policy Attachment**: Attaches the read policy to the IAM role.
- **S3 Bucket Policy**: Sets the bucket policy to allow public read access to all objects in the bucket.
- **Random String**: Generates a random suffix for the S3 bucket name to avoid naming conflicts.

