### Description
This Terraform program creates two S3 buckets: one for storing objects (`source_bucket`) and another for storing CSV inventory reports (`inventory_bucket`). It also sets up an IAM role and policy necessary for generating and storing the inventory reports. The inventory report is configured to be generated weekly.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "source_bucket" {
  bucket = "source-bucket-${var.environment}"
  acl    = "private"

  versioning {
    enabled = true
  }
}

resource "aws_s3_bucket" "inventory_bucket" {
  bucket = "inventory-bucket-${var.environment}"
  acl    = "private"
}

resource "aws_iam_role" "s3_inventory_role" {
  name = "s3-inventory-role-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "s3_inventory_policy" {
  name        = "s3-inventory-policy-${var.environment}"
  description = "Policy for S3 inventory operations."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:PutObject",
          "s3:GetBucketLocation"
        ]
        Effect   = "Allow"
        Resource = [
          aws_s3_bucket.inventory_bucket.arn,
          "${aws_s3_bucket.inventory_bucket.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_s3_inventory_policy" {
  role       = aws_iam_role.s3_inventory_role.name
  policy_arn = aws_iam_policy.s3_inventory_policy.arn
}

resource "aws_s3_bucket_inventory" "bucket_inventory" {
  bucket = aws_s3_bucket.source_bucket.id

  included_object_versions = "All"
  schedule                 = "Weekly"
  destination {
    bucket {
      format = "CSV"
      bucket = aws_s3_bucket.inventory_bucket.arn
      prefix = "inventory_reports/"
    }
    encryption {
      sse_kms {
        key_id = "aws/s3"
      }
    }
  }

  role_arn = aws_iam_role.s3_inventory_role.arn
}

variable "environment" {
  description = "Environment name to append to resource names for uniqueness."
  default     = "dev"
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **S3 Buckets**: Two S3 buckets are created: `source_bucket` for storing objects and `inventory_bucket` for storing the inventory reports.
- **IAM Role and Policy**: An IAM role (`s3_inventory_role`) and policy (`s3_inventory_policy`) are created to allow the S3 service to write inventory reports to the `inventory_bucket`.
- **IAM Role Policy Attachment**: The policy is attached to the IAM role.
- **S3 Bucket Inventory**: The inventory configuration is set up on the `source_bucket` to generate weekly CSV reports and store them in the `inventory_bucket`.
- **Variable**: A `environment` variable is used to ensure resource names are unique across different environments. The default value is set to `"dev"`.

