The Terraform program below creates an AWS S3 bucket and applies server-side encryption using a KMS key. The KMS key is created first, and then the S3 bucket is created with a dependency on the KMS key. The KMS key policy is configured to allow the S3 service to use it for encryption.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

resource "aws_kms_key" "s3_bucket_encryption_key" {
  description             = "KMS key for S3 bucket encryption"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = {
          Service = "s3.amazonaws.com"
        },
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ],
        Resource = "*"
      }
    ]
  })
}

resource "aws_s3_bucket" "my_s3_bucket" {
