  region = "us-west-2"  # Specify your desired AWS region
}

resource "aws_s3_bucket" "my_website_bucket" {
  bucket = "my-website-bucket"
  acl    = "private"

  tags = {
    Name        = "MyWebsiteBucket"
    Environment = "production"
  }
}

resource "aws_s3_bucket_cors_configuration" "my_website_bucket_cors" {
  bucket = aws_s3_bucket.my_website_bucket.id

  cors_rule {
    allowed_headers = ["*"]
    allowed_methods = ["POST", "GET"]
    allowed_origins = ["https://domain.com"]
    max_age_seconds = 3000
  }
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured with the region `us-west-2`. You can change this to any other region as needed.
- **S3 Bucket**: An S3 bucket named `my-website-bucket` is created with private access.
- **CORS Configuration**: The CORS configuration allows POST and GET requests from `https://domain.com`. The `allowed_headers` are set to `["*"]`, which means any header is allowed. The `max_age_seconds` is set to 3000 seconds.

This Terraform program is deployable with Terraform version ~> 1.9.8 and the AWS provider version ~> 5.75.

