### Description
This Terraform program creates an S3 bucket to host a static website. It uploads an `index.html` file to the bucket, sets a bucket policy to allow public read access, and configures the bucket to serve the website using `index.html` as the index page. The program ensures that all dependencies are correctly handled, and it uses default values for variables where applicable.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  default     = "us-west-2"
}

variable "bucket_name" {
  description = "The name of the S3 bucket"
  default     = "my-static-website-bucket"
}

variable "index_html_content" {
  description = "The content of the index.html file"
  type        = string
  default     = "<html><body><h1>Welcome to My Static Website</h1></body></html>"
}

resource "aws_s3_bucket" "static_website_bucket" {
  bucket = var.bucket_name
  acl    = "public-read"

  tags = {
    Name        = "StaticWebsiteBucket"
    Environment = "production"
  }
}

resource "aws_s3_bucket_object" "index_html" {
  bucket = aws_s3_bucket.static_website_bucket.bucket
  key    = "index.html"
  acl    = "public-read"
  content = var.index_html_content

  depends_on = [aws_s3_bucket.static_website_bucket]
}

resource "aws_s3_bucket_policy" "bucket_policy" {
  bucket = aws_s3_bucket.static_website_bucket.bucket
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Principal = "*"
        Action   = "s3:GetObject"
        Resource = "${aws_s3_bucket.static_website_bucket.arn}/*"
      }
    ]
  })

  depends_on = [aws_s3_bucket.static_website_bucket]
}

resource "aws_s3_bucket_website_configuration" "website_config" {
  bucket = aws_s3_bucket.static_website_bucket.bucket

  index_document = "index.html"

  depends_on = [aws_s3_bucket.static_website_bucket, aws_s3_bucket_object.index_html]
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured with a default region (`us-west-2`), which can be overridden by setting the `region` variable.
- **Variables**: 
  - `bucket_name`: The name of the S3 bucket, with a default value.
  - `index_html_content`: The content of the `index.html` file, with a default value.
- **Resources**:
  - `aws_s3_bucket.static_website_bucket`: Creates an S3 bucket with public read access.
  - `aws_s3_bucket_object.index_html`: Uploads the `index.html` file to the bucket.
  - `aws_s3_bucket_policy.bucket_policy`: Sets a bucket policy to allow public read access.
  - `aws_s3_bucket_website_configuration.website_config`: Configures the bucket to host a static website using `index.html` as the index page.
- **Dependencies**: The `depends_on` attribute ensures that resources are created in the correct order.

