```hcl
provider "aws" {
  region = "us-west-2"
}

variable "github_owner" {
  description = "GitHub owner of the repository"
  type        = string
  default     = "example_user"
}

variable "github_repo" {
  description = "GitHub repository name"
  type        = string
  default     = "cs_class_autograder"
}

variable "s3_bucket_name" {
  description = "S3 bucket name to store results"
  type        = string
  default     = "cs-class-autograder-results"
}

resource "aws_iam_role" "codebuild_autograder_role" {
  name = "codebuild-autograder-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "codebuild_autograder_policy" {
  name        = "codebuild-autograder-policy"
  description = "Policy for CodeBuild to access GitHub and S3"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::${var.s3_bucket_name}/*"
      },
      {
        Action = [
          "codebuild:StartBuild",
          "codebuild:BatchGetBuilds"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_codebuild_policy_to_role" {
  role       = aws_iam_role.codebuild_autograder_role.name
  policy_arn = aws_iam_policy.codebuild_autograder_policy.arn
}

