        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = [
          aws_s3_bucket.student_code_bucket.arn,
          "${aws_s3_bucket.student_code_bucket.arn}/*"
        ]
      }
    ]
  })
}

# Resource: Attach S3 access policy to CodeBuild role
resource "aws_iam_role_policy_attachment" "attach_s3_policy_to_role" {
  role       = aws_iam_role.codebuild_role.name
  policy_arn = aws_iam_policy.s3_access_policy.arn
}

# Resource: AWS CodeBuild Project to run students' code
