### Description

The Terraform program below sets up an isolated environment for an autograder using AWS CodeBuild and AWS VPC. The environment is designed to prevent students' code from reaching the internet, ensuring a secure execution environment. The program includes:

- An AWS VPC to isolate the autograder environment.
- A subnet within the VPC.
- An Internet Gateway to allow outbound traffic.
- A route table and route to enable internet access.
- A security group to control inbound and outbound traffic.
- An AWS CodeBuild project configured to run the autograder.
- An IAM role and policy for CodeBuild to access necessary AWS services.
- Credentials to access GitHub.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "github_token" {
  type        = string
  description = "GitHub personal access token for accessing private repositories"
  sensitive   = true
}

resource "aws_vpc" "autograder_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "autograder_subnet" {
  vpc_id            = aws_vpc.autograder_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_internet_gateway" "autograder_igw" {
  vpc_id = aws_vpc.autograder_vpc.id
}

resource "aws_route_table" "autograder_public_rt" {
  vpc_id = aws_vpc.autograder_vpc.id
}

resource "aws_route" "autograder_internet_route" {
  route_table_id         = aws_route_table.autograder_public_rt.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.autograder_igw.id
}

resource "aws_route_table_association" "autograder_subnet_assoc" {
  subnet_id      = aws_subnet.autograder_subnet.id
  route_table_id = aws_route_table.autograder_public_rt.id
}

resource "aws_security_group" "autograder_sg" {
  vpc_id = aws_vpc.autograder_vpc.id
  name   = "autograder_sg"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "autograder_role" {
  name = "autograder_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "autograder_policy" {
  name        = "autograder_policy"
  description = "Policy for CodeBuild to access necessary AWS services"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeDhcpOptions",
          "ec2:DescribeVpcs"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "autograder_role_policy_attach" {
  role       = aws_iam_role.autograder_role.name
  policy_arn = aws_iam_policy.autograder_policy.arn
}

resource "aws_codebuild_project" "autograder_project" {
  name         = "autograder_project"
  description  = "Autograder project for CS class"
  build_timeout = 60

  source {
    type            = "GITHUB"
    location        = "https://github.com/example/repo.git"
    git_clone_depth = 1
  }

  artifacts {
    type = "NO_ARTIFACTS"
  }

  environment {
    compute_type                = "BUILD_GENERAL1_SMALL"
    image                       = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    type                        = "LINUX_CONTAINER"
    image_pull_credentials_type = "SERVICE_ROLE"
    privileged_mode             = false
    environment_variable {
      name  = "GITHUB_TOKEN"
      value = var.github_token
    }
  }

  service_role = aws_iam_role.autograder_role.arn

  vpc_config {
    vpc_id             = aws_vpc.autograder_vpc.id
    subnets            = [aws_subnet.autograder_subnet.id]
    security_group_ids = [aws_security_group.autograder_sg.id]
  }
}

resource "aws_codebuild_source_credential" "autograder_github_creds" {
  auth_type = "PERSONAL_ACCESS_TOKEN"
  server_type = "GITHUB"
  token = var.github_token
}
```

