Below is the complete Terraform HCL program based on the provided IaC Intent Graph IR. This program sets up an AWS service that allows uploading cat pictures to an S3 bucket and retrieving random cat pictures via an API Gateway and Lambda functions.

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "bucket_name" {
  description = "The name of the S3 bucket to store cat pictures"
  default     = "cat-pictures-bucket"
}

variable "lambda_upload_function_name" {
  description = "The name of the Lambda function for uploading cat pictures"
  default     = "upload_cat_picture_lambda"
}

variable "lambda_get_function_name" {
  description = "The name of the Lambda function for getting random cat pictures"
  default     = "get_random_cat_picture_lambda"
}

variable "api_name" {
  description = "The name of the API Gateway"
  default     = "cat_pictures_api"
}

resource "aws_s3_bucket" "cat_pictures_bucket" {
  bucket = var.bucket_name
  acl    = "private"

  versioning {
    enabled = true
  }

  tags = {
    Name = "Cat Pictures Bucket"
  }
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "Lambda Execution Role"
  }
}

resource "aws_iam_role_policy_attachment" "lambda_s3_access_policy" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3FullAccess"
}

resource "aws_lambda_function" "upload_cat_picture_lambda" {
  function_name = var.lambda_upload_function_name
  handler       = "index.handler"
  runtime       = "python3.8"
  role          = aws_iam_role.lambda_execution_role.arn

  s3_bucket = aws_s3_bucket.cat_pictures_bucket.bucket
  s3_key    = "upload_cat_picture_lambda.zip"

  environment {
    variables = {
      BUCKET_NAME = aws_s3_bucket.cat_pictures_bucket.bucket
    }
  }

  tags = {
    Name = "Upload Cat Picture Lambda"
  }
}

resource "aws_lambda_function" "get_random_cat_picture_lambda" {
  function_name = var.lambda_get_function_name
  handler       = "index.handler"
  runtime       = "python3.8"
  role          = aws_iam_role.lambda_execution_role.arn

  s3_bucket = aws_s3_bucket.cat_pictures_bucket.bucket
  s3_key    = "get_random_cat_picture_lambda.zip"

  environment {
    variables = {
      BUCKET_NAME = aws_s3_bucket.cat_pictures_bucket.bucket
    }
  }

  tags = {
    Name = "Get Random Cat Picture Lambda"
  }
}

resource "aws_api_gateway_rest_api" "cat_pictures_api" {
  name        = var.api_name
  description = "API for uploading and retrieving cat pictures"

  tags = {
    Name = "Cat Pictures API"
  }
}

resource "aws_api_gateway_resource" "upload_resource" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  parent_id   = aws_api_gateway_rest_api.cat_pictures_api.root_resource_id
  path_part   = "upload"

  tags = {
    Name = "Upload Resource"
  }
}

resource "aws_api_gateway_resource" "random_resource" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  parent_id   = aws_api_gateway_rest_api.cat_pictures_api.root_resource_id
  path_part   = "random"

  tags = {
    Name = "Random Resource"
  }
}

resource "aws_api_gateway_method" "upload_method" {
  rest_api_id   = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id   = aws_api_gateway_resource.upload_resource.id
  http_method   = "POST"
  authorization = "NONE"

  tags = {
    Name = "Upload Method"
  }
}

resource "aws_api_gateway_method" "random_method" {
  rest_api_id   = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id   = aws_api_gateway_resource.random_resource.id
  http_method   = "GET"
  authorization = "NONE"

  tags = {
    Name = "Random Method"
  }
}

resource "aws_api_gateway_integration" "upload_integration" {
  rest_api_id             = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id             = aws_api_gateway_resource.upload_resource.id
  http_method             = aws_api_gateway_method.upload_method.http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.upload_cat_picture_lambda.invoke_arn

  tags = {
    Name = "Upload Integration"
  }
}

resource "aws_api_gateway_integration" "random_integration" {
  rest_api_id             = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id             = aws_api_gateway_resource.random_resource.id
  http_method             = aws_api_gateway_method.random_method.http_method
  integration_http_method = "GET"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.get_random_cat_picture_lambda.invoke_arn

  tags = {
    Name = "Random Integration"
  }
}

resource "aws_api_gateway_deployment" "cat_pictures_deployment" {
  depends_on = [
    aws_api_gateway_integration.upload_integration,
    aws_api_gateway_integration.random_integration
  ]

  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  stage_name  = "prod"

  tags = {
    Name = "Cat Pictures Deployment"
  }
}
```

This Terraform configuration sets up the required AWS resources to achieve the desired functionality. It includes an S3 bucket for storing cat pictures, an IAM role with S3 access, two Lambda functions for handling uploads and retrievals, an API Gateway with resources and methods for each operation, and integrations between the API Gateway and Lambda functions. The deployment of the API Gateway is also included.

