LLM Output #0:
### Description

This Terraform program sets up an infrastructure to host a web service that allows users to upload cat pictures and retrieve random cat pictures. The architecture includes:

- **AWS DynamoDB Table**: To store metadata about uploaded cat pictures.
- **AWS S3 Bucket**: To store the actual cat pictures.
- **AWS IAM Role and Policy**: To grant necessary permissions to the Lambda function.
- **AWS Lambda Function**: To handle the upload of cat pictures.
- **AWS Lambda Permission**: To allow API Gateway to invoke the Lambda function.
- **AWS API Gateway REST API, Resource, and Method**: To expose the API endpoints for uploading cat pictures.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_dynamodb_table" "cat_pictures_table" {
  name           = "cat-pictures-metadata"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }
}

resource "aws_s3_bucket" "cat_pictures_bucket" {
  bucket = "cat-pictures-bucket-${random_string.bucket_suffix.result}"
  acl    = "private"

  versioning {
    enabled = true
  }
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "lambda_policy" {
  name        = "lambda-policy"
  description = "Policy for Lambda function to interact with DynamoDB, S3, and API Gateway"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "dynamodb:PutItem",
          "dynamodb:GetItem",
          "dynamodb:Scan"
        ]
        Effect   = "Allow"
        Resource = aws_dynamodb_table.cat_pictures_table.arn
      },
      {
        Action = [
          "s3:PutObject",
          "s3:GetObject"
        ]
        Effect   = "Allow"
        Resource = "${aws_s3_bucket.cat_pictures_bucket.arn}/*"
      },
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_lambda_policy_to_role" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = aws_iam_policy.lambda_policy.arn
}

resource "aws_lambda_function" "upload_cat_picture_lambda" {
  filename         = "path/to/your/upload_cat_picture_lambda.zip"
  function_name    = "upload-cat-picture-lambda"
  role             = aws_iam_role.lambda_execution_role.arn
  handler          = "index.handler"
  runtime          = "python3.8"
  source_code_hash = filebase64sha256("path/to/your/upload_cat_picture_lambda.zip")

  environment {
    variables = {
      DYNAMODB_TABLE_NAME = aws_dynamodb_table.cat_pictures_table.name
      S3_BUCKET_NAME      = aws_s3_bucket.cat_pictures_bucket.bucket
    }
  }
}

resource "aws_lambda_permission" "allow_api_gateway_to_invoke_upload_lambda" {
  statement_id  = "AllowAPIGatewayInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.upload_cat_picture_lambda.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "*"
}

resource "aws_api_gateway_rest_api" "cat_pictures_api" {
  name        = "cat-pictures-api"
  description = "API for uploading and retrieving cat pictures"
}

resource "aws_api_gateway_resource" "upload_resource" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  parent_id   = aws_api_gateway_rest_api.cat_pictures_api.root_resource_id
  path_part   = "upload"
}

resource "aws_api_gateway_method" "upload_method" {
  rest_api_id   = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id   = aws_api_gateway_resource.upload_resource.id
  http_method   = "POST"
  authorization = "NONE"

  integration {
    type            = "AWS_PROXY"
    integration_http_method = "POST"
    uri             = aws_lambda_function.upload_cat_picture_lambda.invoke_arn
  }
}
```

### Notes

- Ensure that the `filename` and `handler` in the `aws_lambda_function` resource are correctly set to point to your Lambda function code and entry point.
- Replace `"path/to/your/upload_cat_picture_lambda.zip"` with the actual path to your Lambda function deployment package.
- The `source_code_hash` is used to trigger updates to the Lambda function when the code changes.
- The IAM policy attached to the Lambda execution role grants necessary permissions for DynamoDB, S3, and API Gateway operations. Adjust the policy as needed based on your specific requirements.

