### Description
This Terraform program provisions an EC2 instance and sets up daily backups using AWS Backup. The program includes the necessary resources such as an EC2 instance, a backup vault, a backup plan, and a backup selection. The backup plan is configured to perform backups every day at midnight. IAM roles and policies are created to ensure the EC2 instance and AWS Backup have the required permissions.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for EC2 Instance
resource "aws_iam_role" "ec2_instance_role" {
  name = "ec2-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for EC2 Instance
resource "aws_iam_policy" "ec2_instance_policy" {
  name        = "ec2-instance-policy"
  description = "Policy for EC2 instance to allow backups"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "backup:StartBackupJob",
          "backup:DescribeBackupVaults",
          "backup:DescribeRecoveryPoints"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach IAM Policy to IAM Role
resource "aws_iam_role_policy_attachment" "ec2_instance_policy_attachment" {
  role       = aws_iam_role.ec2_instance_role.name
  policy_arn = aws_iam_policy.ec2_instance_policy.arn
}

# EC2 Instance
resource "aws_instance" "ec2_instance" {
  ami           = "ami-0c55b159cbfafe1f0" # Example AMI ID
  instance_type = "t2.micro"
  iam_instance_profile = aws_iam_instance_profile.ec2_instance_profile.name

  tags = {
    Name = "TerraformManagedEC2Instance"
  }
}

# IAM Instance Profile for EC2 Instance
resource "aws_iam_instance_profile" "ec2_instance_profile" {
  name = "ec2-instance-profile"
  roles = [aws_iam_role.ec2_instance_role.name]
}

# AWS Backup Vault
resource "aws_backup_vault" "backup_vault" {
  name        = "terraform-backup-vault"
  kms_key_arn = "arn:aws:kms:us-west-2:123456789012:key/abcd1234-abcd-1234-abcd-1234abcd1234" # Replace with your KMS key ARN
}

# AWS Backup Plan
resource "aws_backup_plan" "backup_plan" {
  name = "daily-backup-plan"

  rule {
    rule_name         = "DailyBackupRule"
    target_vault_name = aws_backup_vault.backup_vault.name
    schedule          = "cron(0 0 * * ? *)" # Daily at midnight

    start_window = 60
    completion_window = 120

    lifecycle {
      move_to_cold_storage_after_days = 30
      delete_after_days              = 90
    }
  }
}

# AWS Backup Selection
resource "aws_backup_selection" "backup_selection" {
  iam_role_arn = aws_iam_role.backup_role.arn
  plan_id      = aws_backup_plan.backup_plan.id

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Name"
    value = "TerraformManagedEC2Instance"
  }
}

# IAM Role for AWS Backup
resource "aws_iam_role" "backup_role" {
  name = "backup-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for AWS Backup
resource "aws_iam_policy" "backup_policy" {
  name        = "backup-policy"
  description = "Policy for AWS Backup to access resources"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeVolumes",
          "ec2:DescribeSnapshots",
          "ec2:CreateSnapshot",
          "ec2:CopySnapshot",
          "ec2:DeleteSnapshot",
          "ec2:ModifySnapshotAttribute",
          "ec2:RestoreSnapshotFromRecycleBin",
          "ec2:RestoreSnapshotToVolume",
          "ec2:CreateTags",
          "ec2:DeleteTags",
          "ec2:DescribeTags",
          "ec2:DescribeInstanceAttribute",
          "ec2:DescribeInstanceStatus",
          "ec2:DescribeInstances",
          "ec2:DescribeVolumes",
          "ec2:DescribeSnapshots",
          "ec2:CreateSnapshot",
          "ec2:CopySnapshot",
          "ec2:DeleteSnapshot",
          "ec2:ModifySnapshotAttribute",
          "ec2:RestoreSnapshotFromRecycleBin",
          "ec2:RestoreSnapshotToVolume",
          "ec2:CreateTags",
          "ec2:DeleteTags",
          "ec2:DescribeTags",
          "ec2:DescribeInstanceAttribute",
          "ec2:DescribeInstanceStatus",
          "ec2:DescribeInstances",
          "ec2:DescribeVolumes",
          "ec2:DescribeSnapshots",
          "ec2:CreateSnapshot",
          "ec2:CopySnapshot",
          "ec2:DeleteSnapshot",
          "ec2:ModifySnapshotAttribute",
          "ec2:RestoreSnapshotFromRecycleBin",
          "ec2:RestoreSnapshotToVolume",
          "ec2:CreateTags",
          "ec2:DeleteTags",
          "ec2:DescribeTags",
          "ec2:DescribeInstanceAttribute",
          "ec2:DescribeInstanceStatus"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach IAM Policy to IAM Role for AWS Backup
resource "aws_iam_role_policy_attachment" "backup_policy_attachment" {
  role       = aws_iam_role.backup_role.name
  policy_arn = aws_iam_policy.backup_policy.arn
}
```

