### Description
This Terraform program sets up an AWS infrastructure to run a code every day at 7 UTC using AWS EventBridge. The program includes creating an IAM role and policy for the Lambda function, defining the Lambda function itself, setting up an EventBridge rule to trigger the Lambda function daily, and ensuring that EventBridge has the necessary permissions to invoke the Lambda function.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-east-1"  # Specify your desired AWS region
}

# IAM Role for Lambda Execution
resource "aws_iam_role" "eventbridge_lambda_execution_role" {
  name = "eventbridge_lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Basic Lambda Execution
resource "aws_iam_policy" "lambda_basic_execution_policy" {
  name        = "lambda_basic_execution_policy"
  path        = "/"
  description = "Basic Lambda execution policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

# Attach the Basic Execution Policy to the Lambda Execution Role
resource "aws_iam_role_policy_attachment" "attach_lambda_policy_to_role" {
  role       = aws_iam_role.eventbridge_lambda_execution_role.name
  policy_arn = aws_iam_policy.lambda_basic_execution_policy.arn
}

# Lambda Function to Run Code Daily
resource "aws_lambda_function" "daily_code_runner" {
  function_name = "daily_code_runner"
  handler       = "index.handler"
  runtime       = "python3.8"
  role          = aws_iam_role.eventbridge_lambda_execution_role.arn

  filename         = "path/to/your/deployment/package.zip"  # Update with your Lambda deployment package
  source_code_hash = filebase64sha256("path/to/your/deployment/package.zip")  # Update with your Lambda deployment package
}

# EventBridge Rule to Trigger the Lambda Function Daily at 7 UTC
resource "aws_eventbridge_rule" "daily_schedule_rule" {
  name                = "daily_schedule_rule"
  schedule_expression = "cron(0 7 * * ? *)"  # Daily at 7 UTC
}

# Permission to Allow EventBridge to Invoke the Lambda Function
resource "aws_lambda_permission" "allow_eventbridge_to_invoke_lambda" {
  statement_id  = "AllowExecutionFromEventBridge"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.daily_code_runner.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_eventbridge_rule.daily_schedule_rule.arn
}

# Target the Lambda Function from the EventBridge Rule
resource "aws_eventbridge_target" "target_lambda_function" {
  rule      = aws_eventbridge_rule.daily_schedule_rule.name
  target_id = "TargetFunctionV1"

  arn = aws_lambda_function.daily_code_runner.arn

  input = jsonencode({
    key = "value"  # Customize the input payload as needed
  })
}
```

### Notes
- Ensure the Lambda function code is uploaded and configured correctly by updating the `filename` and `source_code_hash` fields with the path to your deployment package.
- The EventBridge rule schedule expression is set to `cron(0 7 * * ? *)` to trigger the Lambda function daily at 7 UTC. Adjust the schedule expression if needed.
- Replace `"path/to/your/deployment/package.zip"` with the actual path to your Lambda deployment package.
- Customize the input payload in the `aws_eventbridge_target` resource as needed for your specific use case.

