### Description

This Terraform program sets up an AWS infrastructure to run a code every day at 7 UTC. It uses AWS EventBridge to schedule the event and triggers an AWS Lambda function at the specified time. The program includes the necessary IAM roles and policies to ensure proper execution.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"  # Specify your desired AWS region
}

# IAM Role for Lambda Execution
resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Basic Lambda Execution
resource "aws_iam_policy" "lambda_basic_execution_policy" {
  name        = "lambda_basic_execution_policy"
  description = "Basic execution policy for Lambda functions"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

# Attach the Lambda Basic Execution Policy to the Lambda Execution Role
resource "aws_iam_role_policy_attachment" "attach_lambda_policy_to_role" {
  role       = aws_iam_role.lambda_execution_role.name
  policy_arn = aws_iam_policy.lambda_basic_execution_policy.arn
}

# AWS Lambda Function
resource "aws_lambda_function" "daily_code_runner" {
  function_name = "daily_code_runner"
  handler       = "index.handler"  # Update with your handler
  runtime       = "python3.8"      # Update with your runtime
  role          = aws_iam_role.lambda_execution_role.arn

  filename         = "path/to/your/deployment/package.zip"  # Update with your deployment package path
  source_code_hash = filebase64sha256("path/to/your/deployment/package.zip")  # Update with your deployment package path
}

# Permission to Allow EventBridge to Invoke Lambda
resource "aws_lambda_permission" "allow_eventbridge_invocation" {
  statement_id  = "AllowExecutionFromEventBridge"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.daily_code_runner.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.daily_schedule_rule.arn
}

# AWS EventBridge Rule to Trigger Daily at 7 UTC
resource "aws_cloudwatch_event_rule" "daily_schedule_rule" {
  name                = "daily_schedule_rule"
  schedule_expression = "cron(0 7 * * ? *)"  # Trigger daily at 7 UTC
}

# AWS EventBridge Target to Trigger Lambda Function
resource "aws_cloudwatch_event_target" "trigger_daily_lambda" {
  rule      = aws_cloudwatch_event_rule.daily_schedule_rule.name
  target_id = "TriggerDailyLambda"

  arn = aws_lambda_function.daily_code_runner.arn
}
```

### Notes
- Ensure the `filename` and `source_code_hash` in the `aws_lambda_function` resource are updated to point to your actual Lambda deployment package.
- The `handler` and `runtime` in the `aws_lambda_function` resource should be updated according to your Lambda function's requirements.
- The `region` in the `provider` block can be changed to your preferred AWS region.

