### Description
This Terraform program sets up the infrastructure for a video streaming site using AWS CloudFront and AWS S3. It includes creating an S3 bucket to store video content, an IAM role and policy for CloudFront to access the S3 bucket, an origin access identity for CloudFront, and a CloudFront distribution to serve the video content globally.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-east-1"  # Specify your desired AWS region
}

variable "s3_bucket_name" {
  description = "Name of the S3 bucket to store video content"
  type        = string
  default     = "unique-video-content-bucket-name"  # Ensure this name is globally unique
}

resource "aws_s3_bucket" "video_content_bucket" {
  bucket = var.s3_bucket_name
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

resource "aws_iam_role" "cloudfront_origin_access_identity_role" {
  name = "cloudfront-origin-access-identity-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "s3_read_policy" {
  name        = "s3-read-policy"
  description = "Policy allowing read access to S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject"
        ]
        Effect = "Allow"
        Resource = [
          "${aws_s3_bucket.video_content_bucket.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_s3_read_policy_to_role" {
  role       = aws_iam_role.cloudfront_origin_access_identity_role.name
  policy_arn = aws_iam_policy.s3_read_policy.arn
}

resource "aws_cloudfront_origin_access_identity" "video_content_origin_access_identity" {
  comment = "Origin access identity for CloudFront to access S3 bucket"
}

resource "aws_s3_bucket_policy" "bucket_policy_for_cloudfront" {
  bucket = aws_s3_bucket.video_content_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject"
        ]
        Effect = "Allow"
        Principal = {
          AWS = aws_cloudfront_origin_access_identity.video_content_origin_access_identity.iam_arn
        }
        Resource = [
          "${aws_s3_bucket.video_content_bucket.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_cloudfront_distribution" "video_content_distribution" {
  origin {
    domain_name = aws_s3_bucket.video_content_bucket.bucket_regional_domain_name
    origin_id   = aws_s3_bucket.video_content_bucket.id

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.video_content_origin_access_identity.cloudfront_access_identity_path
    }
  }

  enabled             = true
  is_ipv6_enabled     = true
  comment             = "CloudFront distribution to serve video content globally"
  default_root_object = "index.html"

  viewer_certificate {
    cloudfront_default_certificate = true
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  logging_config {
    include_cookies = false
    bucket          = aws_s3_bucket.video_content_bucket.bucket
    prefix          = "cloudfront-logs/"
  }
}
```

This Terraform configuration ensures that the S3 bucket is private and secured with versioning and server-side encryption. The IAM role and policy allow CloudFront to access the S3 bucket, and the CloudFront distribution is configured to serve the video content globally. Adjust the `s3_bucket_name` variable to ensure it is globally unique.

Reference output:
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.75"
    }
  }

  required_version = "~> 1.9.8"
}

provider "aws" {
  region = "us-east-1"
  profile = "admin-1"

  assume_role {
    role_arn = "arn:aws:iam::590184057477:role/yicun-iac"
  }
}

resource "aws_s3_bucket" "video_content" {
  bucket_prefix = "video-content-"
}

resource "aws_s3_object" "put_website" {
  bucket = aws_s3_bucket.video_content.bucket
  key = "index.html"
  source = "./supplement/index.html"
  content_type = "text/html"
}

resource "aws_s3_object" "put_website_css" {
  bucket = aws_s3_bucket.video_content.bucket
  key = "css/style.css"
  source = "./supplement/css/style.css"
  content_type = "text/css"
}

resource "aws_s3_bucket_policy" "bucket_policy" {
  bucket = aws_s3_bucket.video_content.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action = "s3:GetObject"
        Resource = "${aws_s3_bucket.video_content.arn}/*"
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.my_distribution.arn
          }
        }
      }
    ]
  })
}


locals {
  s3_origin_id = "s3_video_content_origin"
}

resource "aws_cloudfront_origin_access_control" "s3_oac" {
  name                              = "s3-oac"
  description                       = "aws access control policy"
  origin_access_control_origin_type = "s3"
  signing_behavior                  = "always"
  signing_protocol                  = "sigv4"
}

resource "aws_cloudfront_distribution" "my_distribution" {
  origin {
    domain_name              = aws_s3_bucket.video_content.bucket_regional_domain_name
    origin_access_control_id = aws_cloudfront_origin_access_control.s3_oac.id
    origin_id                = local.s3_origin_id
  }

  enabled             = true
  default_root_object = "index.html"

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = local.s3_origin_id

    forwarded_values {
      query_string = false

      cookies {
        forward = "none"
      }
    }

    viewer_protocol_policy = "allow-all"
  }

  price_class = "PriceClass_200"

  restrictions {
    geo_restriction {
      restriction_type = "whitelist"
      locations        = ["US", "CA", "GB", "DE"]
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

# Route53
resource "aws_route53_zone" "my_zone" {
  name = "my-test-cloudfront.com"
}

resource "aws_route53_record" "cdn_ipv4" {
  type    = "A"
  name    = "cdn"
  zone_id = aws_route53_zone.my_zone.zone_id

  alias {
    name                   = aws_cloudfront_distribution.my_distribution.domain_name
    zone_id                = aws_cloudfront_distribution.my_distribution.hosted_zone_id
    evaluate_target_health = true
  }
}

