### Description
This Terraform configuration sets up the infrastructure for a video streaming site using AWS CloudFront, AWS Route53, and AWS S3. The setup includes creating an S3 bucket to store video content, configuring an IAM role and policy for CloudFront to access the S3 bucket securely, setting up a CloudFront distribution to serve the content globally, and configuring a Route53 hosted zone and record to map a domain to the CloudFront distribution.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-east-1"  # Specify your desired AWS region
}

variable "domain_name" {
  description = "The domain name for the video streaming site"
  type        = string
  default     = "example.com"  # Replace with your actual domain name
}

resource "aws_s3_bucket" "video_streaming_bucket" {
  bucket = "video-streaming-bucket-${var.domain_name}"
  acl    = "private"

  tags = {
    Name        = "VideoStreamingBucket"
    Environment = "production"
  }
}

resource "aws_iam_role" "cloudfront_origin_access_identity_role" {
  name = "CloudFrontOriginAccessIdentityRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name        = "CloudFrontOriginAccessIdentityRole"
    Environment = "production"
  }
}

resource "aws_iam_policy" "s3_read_policy" {
  name        = "S3ReadPolicy"
  description = "Policy to allow read access to S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::${aws_s3_bucket.video_streaming_bucket.bucket}/*"
      }
    ]
  })

  tags = {
    Name        = "S3ReadPolicy"
    Environment = "production"
  }
}

resource "aws_iam_role_policy_attachment" "attach_s3_read_policy_to_role" {
  role       = aws_iam_role.cloudfront_origin_access_identity_role.name
  policy_arn = aws_iam_policy.s3_read_policy.arn
}

resource "aws_cloudfront_origin_access_identity" "video_streaming_origin_access_identity" {
  comment = "Origin access identity for CloudFront to access S3 bucket"
}

resource "aws_s3_bucket_policy" "video_streaming_bucket_policy" {
  bucket = aws_s3_bucket.video_streaming_bucket.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "s3:GetObject"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::cloudfront:user/CloudFront Origin Access Identity ${aws_cloudfront_origin_access_identity.video_streaming_origin_access_identity.cloudfront_origin_access_identity_path}"
        }
        Resource = "arn:aws:s3:::${aws_s3_bucket.video_streaming_bucket.bucket}/*"
      }
    ]
  })
}

resource "aws_cloudfront_distribution" "video_streaming_distribution" {
  origin {
    domain_name = "${aws_s3_bucket.video_streaming_bucket.bucket}.s3.amazonaws.com"
    origin_id   = "myS3Origin"

    s3_origin_config {
      origin_access_identity = aws_cloudfront_origin_access_identity.video_streaming_origin_access_identity.cloudfront_origin_access_identity_path
    }
  }

  enabled             = true
  is_ipv6_enabled     = true
  comment             = "CloudFront distribution for video streaming"
  default_root_object = "index.html"

  default_cache_behavior {
    target_origin_id = "myS3Origin"

    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD", "OPTIONS"]

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    min_ttl                = 0
    default_ttl            = 3600
    max_ttl                = 86400
    compress               = true
    trusted_signers        = ["self"]
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

resource "aws_route53_zone" "video_streaming_domain_zone" {
  name = var.domain_name
}

resource "aws_route53_record" "video_streaming_domain_record" {
  zone_id = aws_route53_zone.video_streaming_domain_zone.zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.video_streaming_distribution.domain_name
    zone_id                = aws_cloudfront_distribution.video_streaming_distribution.hosted_zone_id
    evaluate_target_health = false
  }
}
```

