### Description
The Terraform program below sets up the infrastructure for a video streaming site using AWS Load Balancing. It includes an Application Load Balancer (ALB), a target group, two EC2 instances to host the video streaming application, and a listener to handle incoming HTTP traffic. The configuration ensures that the resources are created in the correct order and that the dependencies are properly managed.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_lb" "video_streaming_load_balancer" {
  name               = "video-streaming-lb"
  internal           = false
  load_balancer_type = "application"
  subnets            = [aws_subnet.public_subnet_1.id, aws_subnet.public_subnet_2.id]
  security_groups    = [aws_security_group.lb_sg.id]
}

resource "aws_lb_target_group" "video_streaming_target_group" {
  name     = "video-streaming-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main_vpc.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

resource "aws_instance" "video_streaming_server_1" {
  ami           = var.ami_id
  instance_type = var.instance_type
  subnet_id     = aws_subnet.public_subnet_1.id
  security_groups = [aws_security_group.server_sg.id]

  tags = {
    Name = "video-streaming-server-1"
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_instance" "video_streaming_server_2" {
  ami           = var.ami_id
  instance_type = var.instance_type
  subnet_id     = aws_subnet.public_subnet_2.id
  security_groups = [aws_security_group.server_sg.id]

  tags = {
    Name = "video-streaming-server-2"
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_lb_listener" "video_streaming_listener" {
  load_balancer_arn = aws_lb.video_streaming_load_balancer.arn
  port              = "80"
  protocol          = "HTTP"
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.video_streaming_target_group.arn
  }
}

resource "aws_vpc" "main_vpc" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public_subnet_1" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-1"
  }
}

resource "aws_subnet" "public_subnet_2" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.2.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-2"
  }
}

resource "aws_security_group" "lb_sg" {
  name        = "lb-sg"
  description = "Security group for the load balancer"
  vpc_id      = aws_vpc.main_vpc.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_security_group" "server_sg" {
  name        = "server-sg"
  description = "Security group for the video streaming servers"
  vpc_id      = aws_vpc.main_vpc.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

variable "ami_id" {
  description = "The AMI ID for the EC2 instances"
  default     = "ami-0c55b159cbfafe1f0" # Example AMI ID for Amazon Linux 2
}

variable "instance_type" {
  description = "The instance type for the EC2 instances"
  default     = "t2.micro"
}
```

This Terraform configuration sets up a basic infrastructure for a video streaming site using AWS Load Balancing. It includes a VPC, public subnets, security groups, an Application Load Balancer, a target group, and two EC2 instances. The load balancer listens for incoming HTTP traffic and forwards it to the target group, which manages the two EC2 instances.

