  enable_dns_hostnames = true

  tags = {
    Name = "video_streaming_vpc"
  }
}

resource "aws_subnet" "video_streaming_subnet" {
  vpc_id            = aws_vpc.video_streaming_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"

  tags = {
    Name = "video_streaming_subnet"
  }
}

resource "aws_security_group" "video_streaming_sg" {
  vpc_id = aws_vpc.video_streaming_vpc.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "video_streaming_sg"
  }
}

resource "aws_instance" "video_streaming_server" {
  ami           = var.ami_id
  instance_type = var.instance_type
  key_name      = var.key_name
  subnet_id     = aws_subnet.video_streaming_subnet.id
  vpc_security_group_ids = [aws_security_group.video_streaming_sg.id]

  tags = {
    Name = "video_streaming_server"
  }
}

resource "aws_lb" "video_streaming_lb" {
  name               = "video-streaming-lb"
  internal           = false
  load_balancer_type = "application"
  subnets            = [aws_subnet.video_streaming_subnet.id]

  tags = {
    Name = "video_streaming_lb"
  }
}

resource "aws_lb_target_group" "video_streaming_tg" {
  name     = "video-streaming-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.video_streaming_vpc.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Name = "video_streaming_tg"
  }
}

resource "aws_lb_listener" "video_streaming_listener" {
  load_balancer_arn = aws_lb.video_streaming_lb.arn
  port              = "80"
  protocol          = "HTTP"
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.video_streaming_tg.arn
  }

  tags = {
    Name = "video_streaming_listener"
  }
}

resource "aws_route53_zone" "video_streaming_zone" {
  name = var.domain_name

  tags = {
    Name = "video_streaming_zone"
  }
}

