  cidr_block        = var.public_subnet_cidr_block
  map_public_ip_on_launch = true
}

resource "aws_subnet" "database_subnet_private_1" {
  vpc_id            = aws_vpc.database_vpc.id
  cidr_block        = var.private_subnet_cidr_block
  map_public_ip_on_launch = false
}

resource "aws_security_group" "database_security_group" {
  name        = "database-sg"
  description = "Security group for the database instance"
  vpc_id      = aws_vpc.database_vpc.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Adjust this to restrict access
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_parameter_group" "database_parameter_group" {
  name   = "postgres-parameter-group"
  family = "postgres13"

  parameter {
    name         = "log_connections"
    value        = "1"
    apply_method = "immediate"
  }

  parameter {
    name         = "log_disconnections"
    value        = "1"
    apply_method = "immediate"
  }
}

resource "aws_kms_key" "database_kms_key" {
  description             = "KMS key for database encryption"
  deletion_window_in_days = 10
  enable_key_rotation     = true
}

resource "aws_db_instance" "database_instance" {
  identifier              = var.db_instance_identifier
  instance_class          = var.db_instance_class
  allocated_storage       = var.allocated_storage
  engine                  = "postgres"
  engine_version          = var.engine_version
  multi_az                = var.multi_az
  db_subnet_group_name    = aws_db_subnet_group.database_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.database_security_group.id]
  parameter_group_name    = aws_db_parameter_group.database_parameter_group.name
  kms_key_id              = aws_kms_key.database_kms_key.arn
  final_snapshot_identifier = "pgsnapshot"

  skip_final_snapshot = false
}

resource "aws_db_subnet_group" "database_subnet_group" {
  name       = "database-subnet-group"
  subnet_ids = [aws_subnet.database_subnet_private_1.id]

  tags = {
    Name = "Database Subnet Group"
  }
}
```

