The Terraform program below sets up a PostgreSQL 15 instance on AWS RDS within specific public subnets. The RDS instance is configured with a managed setup for low maintenance, using an instance type of "db.t3.micro" and allocated storage of 5 GB. The program also creates a VPC and two public subnets in different availability zones to ensure high availability. Security groups and DB parameter groups are included for additional configuration.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "vpc_cidr_block" {
  description = "CIDR block for the main VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "CIDR blocks for the public subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "availability_zones" {
  description = "Availability zones for the subnets"
  type        = list(string)
  default     = ["us-west-2a", "us-west-2b"]
}

resource "aws_vpc" "main_vpc" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_subnet" "public_subnet_1" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = var.subnet_cidr_blocks[0]
  availability_zone = var.availability_zones[0]
  map_public_ip_on_launch = true
}

resource "aws_subnet" "public_subnet_2" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = var.subnet_cidr_blocks[1]
  availability_zone = var.availability_zones[1]
  map_public_ip_on_launch = true
}

resource "aws_security_group" "postgres_sg" {
  name        = "postgres_sg"
  description = "Security group for PostgreSQL"
  vpc_id      = aws_vpc.main_vpc.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Adjust this for security
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_db_parameter_group" "postgres_param_group" {
  name   = "postgres-param-group"
  family = "postgres15"

  parameter {
    name         = "log_connections"
    value        = "1"
    apply_method = "immediate"
  }
}

resource "aws_db_instance" "airbyte_postgresql" {
  identifier              = "airbyte-postgresql"
  engine                  = "postgres"
  engine_version          = "15"
  instance_class          = "db.t3.micro"
  allocated_storage       = 5
  username                = "airbyte_user"
  password                = "secure_password"  # Change this to a secure password
  db_subnet_group_name    = aws_db_subnet_group.postgres_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.postgres_sg.id]
  parameter_group_name    = aws_db_parameter_group.postgres_param_group.name
  publicly_accessible     = true
  skip_final_snapshot     = true

  depends_on = [
    aws_subnet.public_subnet_1,
    aws_subnet.public_subnet_2,
  ]
}

resource "aws_db_subnet_group" "postgres_subnet_group" {
  name       = "postgres-subnet-group"
  subnet_ids = [aws_subnet.public_subnet_1.id, aws_subnet.public_subnet_2.id]
}
