### Description
This Terraform program sets up a PostgreSQL 15 instance on AWS RDS within specific public subnets for running Airbyte connector test cases. It includes the creation of public subnets, a security group, an IAM role, and an IAM policy. The PostgreSQL instance is configured to use these resources and is set up with managed settings for low maintenance.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "vpc_id" {
  description = "The ID of the VPC where the subnets will be created"
  type        = string
}

variable "availability_zone_1" {
  description = "The first availability zone for the public subnet"
  type        = string
  default     = "us-west-2a"
}

variable "availability_zone_2" {
  description = "The second availability zone for the public subnet"
  type        = string
  default     = "us-west-2b"
}

variable "cidr_block_1" {
  description = "The CIDR block for the first public subnet"
  type        = string
  default     = "10.0.1.0/24"
}

variable "cidr_block_2" {
  description = "The CIDR block for the second public subnet"
  type        = string
  default     = "10.0.2.0/24"
}

resource "aws_subnet" "public_subnet_1" {
  vpc_id            = var.vpc_id
  cidr_block        = var.cidr_block_1
  availability_zone = var.availability_zone_1
  map_public_ip_on_launch = true
}

resource "aws_subnet" "public_subnet_2" {
  vpc_id            = var.vpc_id
  cidr_block        = var.cidr_block_2
  availability_zone = var.availability_zone_2
  map_public_ip_on_launch = true
}

resource "aws_security_group" "postgresql_sg" {
  name        = "postgresql_sg"
  description = "Security group for PostgreSQL instance"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Adjust as needed for security
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "rds_iam_role" {
  name = "rds_iam_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "rds_iam_policy" {
  name        = "rds_iam_policy"
  description = "Policy for RDS operations"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "rds:*",
          "logs:*",
          "cloudwatch:*"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_rds_policy_to_role" {
  role       = aws_iam_role.rds_iam_role.name
  policy_arn = aws_iam_policy.rds_iam_policy.arn
}

resource "aws_db_instance" "airbyte_postgresql" {
  identifier              = "airbyte-postgresql"
  engine                  = "postgres"
  engine_version          = "15"
  instance_class          = "db.t3.medium"
  allocated_storage       = 500
  username                = "airbyte_user"
  password                = "secure_password"  # Replace with a secure method for managing passwords
  db_subnet_group_name    = aws_db_subnet_group.airbyte_db_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.postgresql_sg.id]
  iam_database_authentication_enabled = true
  skip_final_snapshot     = true
  backup_retention_period = 7
  multi_az                = false
  publicly_accessible     = true
  parameter_group_name    = "default.postgres15"
}

resource "aws_db_subnet_group" "airbyte_db_subnet_group" {
  name       = "airbyte-db-subnet-group"
  subnet_ids = [aws_subnet.public_subnet_1.id, aws_subnet.public_subnet_2.id]
}
```

### Notes
