  subnet_ids              = [aws_subnet.subnet_public_1.id, aws_subnet.subnet_public_2.id]

  tags = {
    Name = "MySQLRDSInstance"
  }
}

output "db_endpoint" {
  value = aws_db_instance.mysql_rds_instance.endpoint
}
```

