This Terraform program sets up a PostgreSQL database instance in AWS within a custom VPC and subnet. The database instance is configured to allow major version upgrades and automatically perform minor version upgrades. It is not publicly accessible, ensuring secure access through a security group.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_block" {
  description = "CIDR block for the subnet"
  default     = "10.0.1.0/24"
}

variable "db_instance_class" {
  description = "Instance class for the RDS database"
  default     = "db.t3.micro"
}

variable "db_allocated_storage" {
  description = "Allocated storage for the RDS database in GB"
  default     = 20
}

variable "db_engine_version" {
  description = "Engine version for the RDS database"
  default     = "13.7"
}

variable "db_name" {
  description = "Name of the database"
  default     = "mydatabase"
}

variable "db_username" {
  description = "Username for the database"
  default     = "admin"
}

variable "db_password" {
  description = "Password for the database"
  default     = "securepassword123"
}

resource "aws_vpc" "database_vpc" {
  cidr_block = var.vpc_cidr_block

  tags = {
    Name = "DatabaseVPC"
  }
}

resource "aws_subnet" "database_subnet" {
  vpc_id            = aws_vpc.database_vpc.id
  cidr_block        = var.subnet_cidr_block
  availability_zone = "us-west-2a"

  tags = {
    Name = "DatabaseSubnet"
  }
}

resource "aws_security_group" "database_sg" {
  name        = "DatabaseSecurityGroup"
  description = "Security group for the database"
  vpc_id      = aws_vpc.database_vpc.id

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]  # Allow access from within the VPC
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "DatabaseSecurityGroup"
  }
}

resource "aws_db_instance" "database_instance" {
  identifier              = "my-postgresql-db"
  engine                  = "postgres"
  engine_version          = var.db_engine_version
  instance_class          = var.db_instance_class
  allocated_storage       = var.db_allocated_storage
  username                = var.db_username
  password                = var.db_password
  db_name                 = var.db_name
  skip_final_snapshot     = true
  publicly_accessible     = false
  auto_minor_version_upgrade = true
  backup_retention_period = 7
  multi_az                = false
  vpc_security_group_ids  = [aws_security_group.database_sg.id]
  subnet_id               = aws_subnet.database_subnet.id

  tags = {
    Name = "MyPostgreSQLDB"
  }
}
```

This Terraform configuration creates a VPC, a subnet within that VPC, a security group to control access, and a PostgreSQL database instance within the subnet and security group. The database is configured to allow major version upgrades and automatically perform minor version upgrades, and it is not publicly accessible.

