Below is the complete Terraform HCL program that sets up an AWS RDS Aurora MySQL cluster with a proxy for enhanced connection management, including VPC, subnets, security groups, IAM roles, and Secrets Manager for secure credential storage. The idle client timeout for the proxy is set to 1800, and debug logging is disabled.

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "The CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "The CIDR blocks for the subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "security_group_name" {
  description = "The name of the security group"
  default     = "aurora_sg"
}

variable "security_group_description" {
  description = "The description of the security group"
  default     = "Security group for Aurora cluster and proxy"
}

variable "security_group_ingress_rules" {
  description = "Ingress rules for the security group"
  type        = list(map(string))
  default     = [
    {
      from_port   = 3306
      to_port     = 3306
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    }
  ]
}

variable "aurora_cluster_identifier" {
  description = "The identifier for the Aurora cluster"
  default     = "aurora-cluster"
}

variable "aurora_instance_class" {
  description = "The instance class for the Aurora instances"
  default     = "db.serverless"
}

variable "aurora_engine" {
  description = "The engine for the Aurora cluster"
  default     = "aurora-mysql"
}

variable "aurora_engine_version" {
  description = "The engine version for the Aurora cluster"
  default     = "8.0.mysql_aurora.3.02.0"
}

variable "aurora_username" {
  description = "The username for the Aurora database"
  default     = "admin"
}

variable "aurora_password" {
  description = "The password for the Aurora database"
  default     = "password123"
}

variable "proxy_name" {
  description = "The name of the Aurora proxy"
  default     = "aurora-proxy"
}

resource "aws_vpc" "aurora_vpc" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_subnet" "aurora_subnet_1" {
  vpc_id            = aws_vpc.aurora_vpc.id
  cidr_block        = var.subnet_cidr_blocks[0]
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "aurora_subnet_2" {
  vpc_id            = aws_vpc.aurora_vpc.id
  cidr_block        = var.subnet_cidr_blocks[1]
  availability_zone = "us-west-2b"
}

resource "aws_security_group" "aurora_sg" {
  name        = var.security_group_name
  description = var.security_group_description
  vpc_id      = aws_vpc.aurora_vpc.id

  ingress {
    from_port   = var.security_group_ingress_rules[0].from_port
    to_port     = var.security_group_ingress_rules[0].to_port
    protocol    = var.security_group_ingress_rules[0].protocol
    cidr_blocks = var.security_group_ingress_rules[0].cidr_blocks
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "aurora_proxy_role" {
  name = "aurora-proxy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "aurora_proxy_policy" {
  name        = "aurora-proxy-policy"
  description = "Policy to allow access to Secrets Manager for Aurora proxy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_aurora_proxy_policy" {
  role       = aws_iam_role.aurora_proxy_role.name
  policy_arn = aws_iam_policy.aurora_proxy_policy.arn
}

resource "aws_secretsmanager_secret" "aurora_credentials" {
  name = "aurora-credentials"

  tags = {
    Name = "AuroraCredentials"
  }
}

resource "aws_secretsmanager_secret_version" "aurora_credentials_version" {
  secret_id     = aws_secretsmanager_secret.aurora_credentials.id
  secret_string = jsonencode({
    username = var.aurora_username
    password = var.aurora_password
  })
}

resource "aws_rds_cluster" "aurora_cluster" {
  cluster_identifier      = var.aurora_cluster_identifier
  engine                  = var.aurora_engine
  engine_version          = var.aurora_engine_version
  master_username         = var.aurora_username
  master_password         = var.aurora_password
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
  db_subnet_group_name    = aws_db_subnet_group.aurora_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.aurora_sg.id]

  lifecycle {
    ignore_changes = [master_password]
  }
}

resource "aws_db_subnet_group" "aurora_subnet_group" {
  name       = "aurora-subnet-group"
  subnet_ids = [aws_subnet.aurora_subnet_1.id, aws_subnet.aurora_subnet_2.id]
}

resource "aws_db_proxy" "aurora_proxy" {
  name                   = var.proxy_name
  engine_family          = "MYSQL"
  db_cluster_identifier  = aws_rds_cluster.aurora_cluster.id
  iam_role_arn           = aws_iam_role.aurora_proxy_role.arn
  debug_logging          = false
  idle_client_timeout    = 1800

  auth {
    auth_scheme = "SECRETS"
    secret_arn  = aws_secretsmanager_secret.aurora_credentials.arn
    username    = var.aurora_username
  }
}
