Below is a complete Terraform HCL program that sets up an AWS RDS Aurora MySQL cluster with a proxy for enhanced connection management, including VPC, subnets, security groups, IAM roles, and Secrets Manager for secure credential storage. The backup retention period for the RDS cluster is set to 5 days, and the preferred backup window is from 7 AM to 9 AM.

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_cidr_block" {
  description = "CIDR block for the VPC"
  default     = "10.0.0.0/16"
}

variable "subnet_cidr_blocks" {
  description = "CIDR blocks for the subnets"
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]
}

variable "instance_class" {
  description = "Instance class for the Aurora MySQL instances"
  default     = "db.serverless"
}

variable "engine_version" {
  description = "Engine version for the Aurora MySQL cluster"
  default     = "8.0.mysql_aurora.3.02.0"
}

resource "aws_vpc" "aurora_vpc" {
  cidr_block = var.vpc_cidr_block
}

resource "aws_subnet" "aurora_subnet_1" {
  vpc_id            = aws_vpc.aurora_vpc.id
  cidr_block        = var.subnet_cidr_blocks[0]
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "aurora_subnet_2" {
  vpc_id            = aws_vpc.aurora_vpc.id
  cidr_block        = var.subnet_cidr_blocks[1]
  availability_zone = "us-west-2b"
}

resource "aws_security_group" "aurora_sg" {
  vpc_id = aws_vpc.aurora_vpc.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_iam_role" "aurora_rds_proxy_role" {
  name = "aurora-rds-proxy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "aurora_rds_proxy_policy" {
  name        = "aurora-rds-proxy-policy"
  description = "Policy for RDS Proxy to access Aurora cluster"

  policy = jsonencode({
    Version = "2012-10-17"
