}

resource "aws_rds_cluster_instance" "aurora_mysql_instance_2" {
  identifier         = "aurora-mysql-instance-2"
  cluster_identifier = aws_rds_cluster.aurora_mysql_cluster.id
  instance_class     = var.instance_class
  engine             = aws_rds_cluster.aurora_mysql_cluster.engine
  engine_version     = aws_rds_cluster.aurora_mysql_cluster.engine_version
}

resource "aws_db_proxy" "aurora_rds_proxy" {
  name                   = "aurora-rds-proxy"
  debug_logging          = false
  engine_family          = "MYSQL"
  idle_client_timeout    = 1800
  require_tls            = true
  vpc_security_group_ids = [aws_security_group.aurora_sg.id]
  vpc_subnet_ids         = [aws_subnet.aurora_subnet_1.id, aws_subnet.aurora_subnet_2.id]
  auth {
