  name                = "aurora-rds-proxy-target-group"
  db_proxy_name       = aws_db_proxy.aurora_rds_proxy.name
  target_group_arn    = aws_rds_cluster.aurora_mysql_cluster.reader_endpoint
  connection_pool_config {
    max_connections_per_user = 10
  }
}
