The Terraform program below sets up a basic Amazon Lightsail instance with user data. It includes the creation of an IAM role and policy necessary for the Lightsail instance, ensuring proper permissions and dependencies are met.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "lightsail_instance_name" {
  description = "The name of the Lightsail instance"
  default     = "basic-lightsail-instance"
}

variable "lightsail_instance_plan" {
  description = "The plan for the Lightsail instance"
  default     = "small_1_0"
}

variable "lightsail_instance_blueprint" {
  description = "The blueprint for the Lightsail instance"
  default     = "ubuntu_20_04"
}

variable "user_data" {
  description = "User data script to run on instance launch"
  default     = <<-EOF
                #!/bin/bash
                echo "Hello, World!" > /var/www/html/index.html
                EOF
}

resource "aws_iam_role" "lightsail_instance_role" {
  name = "lightsail-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "lightsail_instance_policy" {
  name        = "lightsail-instance-policy"
  path        = "/"
  description = "Policy for Lightsail instance"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:*",
          "s3:*",
          "logs:*"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_lightsail_policy_to_role" {
  role       = aws_iam_role.lightsail_instance_role.name
  policy_arn = aws_iam_policy.lightsail_instance_policy.arn
}

resource "aws_lightsail_instance" "basic_lightsail_instance" {
  name              = var.lightsail_instance_name
  availability_zone = "us-west-2a"  # Specify your desired availability zone
  blueprint_id      = var.lightsail_instance_blueprint
  bundle_id         = var.lightsail_instance_plan
  key_pair_name     = "my-key-pair"  # Ensure this key pair exists in your AWS account
  user_data         = var.user_data

  tags = {
    Name = "BasicLightsailInstance"
  }

  depends_on = [aws_iam_role_policy_attachment.attach_lightsail_policy_to_role]
}
```

### Notes
- Ensure that the `key_pair_name` specified in the `aws_lightsail_instance` resource exists in your AWS account.
- The IAM policy provided in the example grants broad permissions (`ec2:*`, `s3:*`, `logs:*`). Adjust the policy according to your specific requirements for security and least privilege principles.
- The `user_data` script is a simple example that writes "Hello, World!" to an HTML file. Modify it as needed for your use case.

