### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-east-1"  # Default region, can be changed as needed
}

# IAM Role for Lightsail Instance
resource "aws_iam_role" "lightsail_instance_role" {
  name = "lightsail-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Lightsail Instance
resource "aws_iam_policy" "lightsail_instance_policy" {
  name        = "lightsail-instance-policy"
  description = "Policy for Lightsail instance"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:*",
          "s3:*",
          "logs:*",
          "cloudwatch:*"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach IAM Policy to IAM Role
resource "aws_iam_role_policy_attachment" "attach_lightsail_policy_to_role" {
  role       = aws_iam_role.lightsail_instance_role.name
  policy_arn = aws_iam_policy.lightsail_instance_policy.arn
}

# Create Lightsail Instance with WordPress Blueprint
resource "aws_lightsail_instance" "wordpress_lightsail_instance" {
  name              = "wordpress-lightsail-instance"
  availability_zone = "us-east-1a"  # Ensure this matches your region
  blueprint_id      = "wordpress_6.1"  # WordPress blueprint ID
  bundle_id         = "medium_2_0"  # Example bundle ID, choose appropriate size
  key_pair_name     = var.key_pair_name  # Variable for SSH key pair name

  tags = {
    Name = "WordPress-Lightsail-Instance"
  }
}

# Variable for SSH key pair name
variable "key_pair_name" {
  description = "Name of the SSH key pair to use for the Lightsail instance"
  type        = string
  default     = "my-key-pair"  # Default key pair name, can be changed
}
```

### Notes
- Ensure that the `key_pair_name` variable is set to an existing SSH key pair in your AWS account.
- The `blueprint_id` and `bundle_id` can be adjusted based on the specific WordPress version and instance size you require.
- The IAM policy attached to the Lightsail instance role provides broad permissions. Adjust the policy as needed to meet your security requirements.

