### Description

The Terraform program below defines an AWS Lightsail instance with an attached IAM role and policy. The Lightsail instance is configured to run a MySQL database. The IAM role and policy ensure that the Lightsail instance has the necessary permissions to interact with other AWS services, specifically to manage the MySQL database.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for Lightsail Instance
resource "aws_iam_role" "lightsail_instance_role" {
  name = "lightsail-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Lightsail Instance
resource "aws_iam_policy" "lightsail_instance_policy" {
  name        = "lightsail-instance-policy"
  description = "Policy for Lightsail instance to manage MySQL database"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "rds:*",
          "ec2:*",
          "lightsail:*"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach IAM Policy to IAM Role
resource "aws_iam_role_policy_attachment" "attach_lightsail_policy_to_role" {
  role       = aws_iam_role.lightsail_instance_role.name
  policy_arn = aws_iam_policy.lightsail_instance_policy.arn
}

# AWS Lightsail Instance
resource "aws_lightsail_instance" "my_lightsail_instance" {
  name              = "my-lightsail-instance"
  availability_zone = "us-west-2a"
  blueprint_id      = "amazon_linux_2"
  bundle_id         = "nano_1_0"
  key_pair_name     = var.key_pair_name

  iam_instance_profile = aws_iam_role.lightsail_instance_role.name

  tags = {
    Name = "MyLightsailInstance"
  }
}

# MySQL Database on Lightsail Instance
resource "aws_db_instance" "my_mysql_database" {
  identifier           = "my-mysql-database"
  engine               = "mysql"
  engine_version       = "8.0"
  instance_class       = "db.t3.micro"
  allocated_storage    = 20
  username             = var.db_username
  password             = var.db_password
  parameter_group_name = "default.mysql8.0"

  skip_final_snapshot = true

  depends_on = [aws_lightsail_instance.my_lightsail_instance]
}

# Variables
variable "key_pair_name" {
  description = "Name of the SSH key pair for the Lightsail instance"
  type        = string
  default     = "my-key-pair"
}

variable "db_username" {
  description = "Username for the MySQL database"
  type        = string
  default     = "admin"
}

variable "db_password" {
  description = "Password for the MySQL database"
  type        = string
  sensitive   = true
  default     = "password123"
}
```

### Notes
- Ensure that the `key_pair_name` variable is set to an existing SSH key pair in your AWS account.
- The `db_username` and `db_password` variables are provided with default values, but it is recommended to override them with secure credentials.
- The IAM policy grants broad permissions (`rds:*`, `ec2:*`, `lightsail:*`) for simplicity. In a production environment, you should restrict these permissions to only what is necessary.

### Description
The Terraform program below sets up an AWS Lightsail instance to host a MySQL database. It configures daily backups to occur between 16:00 and 16:30 each day and schedules maintenance tasks on Tuesdays between 17:00 and 17:30. The program includes the necessary IAM roles and policies to ensure the Lightsail instance can write to the backup bucket.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "instance_name" {
  description = "The name of the Lightsail instance"
  default     = "mysql-instance"
}

variable "bucket_name" {
  description = "The name of the Lightsail bucket for backups"
  default     = "mysql-backup-bucket"
}

resource "aws_iam_role" "lightsail_role" {
  name = "LightsailMySQLRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "lightsail_policy" {
  name        = "LightsailMySQLPolicy"
  description = "Policy for Lightsail instance to access S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:PutObject",
          "s3:GetObject",
          "s3:DeleteObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::${var.bucket_name}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lightsail_policy_attachment" {
  role       = aws_iam_role.lightsail_role.name
  policy_arn = aws_iam_policy.lightsail_policy.arn
}

resource "aws_lightsail_instance" "lightsail_mysql_instance" {
  name              = var.instance_name
  availability_zone = "us-west-2a"
  blueprint_id      = "amazon_linux_2"
  bundle_id         = "small_1_0"
  key_pair_name     = "my-key-pair"
  iam_role_name     = aws_iam_role.lightsail_role.name
}

resource "aws_lightsail_bucket" "lightsail_backup_bucket" {
  name = var.bucket_name
}

resource "aws_lightsail_bucket_object" "backup_schedule" {
  bucket_name = aws_lightsail_bucket.lightsail_backup_bucket.name
  key         = "backup_schedule.json"
  content     = jsonencode({
    backup_window_start_hour = 16
    backup_window_end_hour   = 16
  })
  content_type = "application/json"
}

resource "aws_lightsail_bucket_object" "maintenance_window" {
  bucket_name = aws_lightsail_bucket.lightsail_backup_bucket.name
  key         = "maintenance_window.json"
  content     = jsonencode({
    maintenance_window_start_day   = "tuesday"
    maintenance_window_start_hour  = 17
    maintenance_window_end_hour    = 17
  })
  content_type = "application/json"
}
```

### Explanation
1. **Provider Configuration**: Sets the AWS region to `us-west-2`.
2. **Variables**: Defines variables for the instance name and bucket name with default values.
3. **IAM Role and Policy**: Creates an IAM role and policy allowing the Lightsail instance to access the S3 bucket.
4. **Lightsail Instance**: Creates a Lightsail instance with the specified blueprint and bundle.
5. **Lightsail Bucket**: Creates an S3 bucket to store backups.
6. **Backup Schedule and Maintenance Window**: Configures the backup schedule and maintenance window using JSON files stored in the S3 bucket.

This configuration ensures that the Lightsail instance has the necessary permissions and settings to perform daily backups and scheduled maintenance tasks.

### Description
The Terraform program below creates an AWS Lightsail instance and a PostgreSQL database hosted on that instance. The database is configured to allow immediate application of changes, bypassing the need for maintenance windows. The program includes necessary IAM roles and configurations to ensure proper deployment.

### Terraform HCL Program

```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the Lightsail instance and database"
  default     = "us-east-1"
}

variable "instance_name" {
  description = "The name of the Lightsail instance"
  default     = "lightsail-postgres-instance"
}

variable "database_name" {
  description = "The name of the Lightsail PostgreSQL database"
  default     = "postgres-db"
}

variable "instance_plan" {
  description = "The plan for the Lightsail instance"
  default     = "small_2_0"
}

variable "database_engine" {
  description = "The engine type for the Lightsail database"
  default     = "postgresql"
}

variable "database_engine_version" {
  description = "The engine version for the Lightsail database"
  default     = "13.4"
}

resource "aws_lightsail_instance" "lightsail_postgres_instance" {
  name              = var.instance_name
  availability_zone = data.aws_availability_zones.available.names[0]
  blueprint_id      = "amazon_linux_2"
  bundle_id         = var.instance_plan
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_lightsail_database" "lightsail_postgres_database" {
  name                   = var.database_name
  relational_database_bundle_id = "micro_1_0"
  master_database_name     = "masterdb"
  master_username          = "admin"
  master_user_password     = "securepassword123"
  backup_retention_enabled = true
  preferred_backup_window  = "07:00-09:00"
  preferred_maintenance_window = "sun:05:00-sun:09:00"
  engine                 = var.database_engine
  engine_version         = var.database_engine_version
  master_endpoint_port   = 5432

  depends_on = [aws_lightsail_instance.lightsail_postgres_instance]
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured with a default region (`us-east-1`), which can be overridden using the `region` variable.
- **Variables**: Several variables are defined to allow customization of the instance and database names, plans, and other settings.
- **Lightsail Instance**: An AWS Lightsail instance is created with a specified blueprint and bundle ID. The availability zone is dynamically selected from available zones.
- **Lightsail Database**: A PostgreSQL database is created on the Lightsail instance. The database is configured with a master username, password, and other settings. The `depends_on` attribute ensures that the database is created only after the instance is ready.
- **Data Source**: A data source is used to fetch available availability zones, ensuring the instance is deployed in a valid zone.

This configuration ensures that the PostgreSQL database on AWS Lightsail is set up with the ability to apply changes immediately, as required.

