### Description
This Terraform program sets up an AWS Lightsail bucket and configures an IAM role with the necessary permissions to access the bucket. The program includes:

1. **IAM Role (`aws_iam_role.lightsail_access_role`)**: An IAM role specifically for Lightsail to access S3.
2. **IAM Policy (`aws_iam_policy.s3_access_policy`)**: A policy that grants the required S3 access permissions.
3. **IAM Role Policy Attachment (`aws_iam_role_policy_attachment.attach_s3_policy_to_role`)**: Attaches the S3 policy to the Lightsail IAM role.
4. **Lightsail Bucket (`aws_lightsail_bucket.lightsail_bucket`)**: The Lightsail bucket that will be accessed.
5. **S3 Bucket Policy (`aws_s3_bucket_policy.bucket_policy`)**: A bucket policy that allows the Lightsail IAM role to access the bucket.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

# IAM Role for Lightsail to access S3
resource "aws_iam_role" "lightsail_access_role" {
  name = "lightsail-s3-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy granting S3 access permissions
resource "aws_iam_policy" "s3_access_policy" {
  name        = "s3-access-policy"
  description = "Policy granting S3 access permissions for Lightsail"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:s3:::my-lightsail-bucket/*"
      }
    ]
  })
}

# Attach the S3 policy to the Lightsail IAM role
resource "aws_iam_role_policy_attachment" "attach_s3_policy_to_role" {
  role       = aws_iam_role.lightsail_access_role.name
  policy_arn = aws_iam_policy.s3_access_policy.arn
}

# Lightsail Bucket
resource "aws_lightsail_bucket" "lightsail_bucket" {
  name = "my-lightsail-bucket"
}

# S3 Bucket Policy to allow Lightsail IAM role access
resource "aws_s3_bucket_policy" "bucket_policy" {
  bucket = aws_lightsail_bucket.lightsail_bucket.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Effect   = "Allow"
        Principal = {
          AWS = aws_iam_role.lightsail_access_role.arn
        }
