### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

resource "aws_s3_bucket" "long_term_data_storage" {
  bucket = "long-term-data-storage-${var.environment}"
  acl    = "private"

  tags = {
