  }
}

resource "aws_iam_role" "s3_backup_role" {
  name = "S3BackupRole-${var.environment}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name        = "S3BackupRole"
    Environment = var.environment
  }
}

resource "aws_iam_policy" "s3_backup_policy" {
  name        = "S3BackupPolicy-${var.environment}"
  description = "Policy for S3 backup operations"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = [
          "${aws_s3_bucket.long_term_data_storage.arn}",
          "${aws_s3_bucket.long_term_data_storage.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_s3_backup_policy_to_role" {
  role       = aws_iam_role.s3_backup_role.name
  policy_arn = aws_iam_policy.s3_backup_policy.arn
}

variable "environment" {
  description = "Environment tag for resources"
  default     = "production"
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured with a default region (`us-west-2`), which can be changed as needed.
- **S3 Bucket**: An S3 bucket named `long-term-data-storage-${var.environment}` is created with private access.
- **Versioning**: Versioning is enabled on the S3 bucket to support backups.
- **IAM Role**: An IAM role named `S3BackupRole-${var.environment}` is created, allowing EC2 instances to assume this role.
- **IAM Policy**: An IAM policy named `S3BackupPolicy-${var.environment}` is defined, granting permissions for S3 backup operations.
- **Policy Attachment**: The IAM policy is attached to the IAM role.
- **Variable**: A variable `environment` is used to tag resources, with a default value of `"production"`. This allows for easy customization of resource names and tags based on the environment.

