### Description
This Terraform program creates an internal-facing load balancer within an AWS environment. The load balancer is configured with a listener, a target group, and a listener rule to route traffic to the target group. The load balancer uses private IP addresses, ensuring it is only accessible within the specified VPC and subnets.

### Terraform HCL Program
```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  default     = "us-west-2"
}

variable "vpc_id" {
  description = "The ID of the VPC where the load balancer will be deployed"
  type        = string
}

variable "subnet_ids" {
  description = "A list of subnet IDs where the load balancer will be deployed"
  type        = list(string)
}

resource "aws_lb" "internal_load_balancer" {
  name            = "internal-load-balancer"
  internal        = true
  load_balancer_type = "application"
  subnets         = var.subnet_ids
  security_groups = [aws_security_group.internal_lb_sg.id]
  vpc_id          = var.vpc_id
}

resource "aws_security_group" "internal_lb_sg" {
  name        = "internal-lb-sg"
  description = "Security group for the internal load balancer"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/8"]  # Adjust this CIDR block as needed
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb_listener" "internal_load_balancer_listener" {
  load_balancer_arn = aws_lb.internal_load_balancer.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "fixed-response"
    fixed_response {
      content_type = "text/plain"
      message_body = "Hello, World!"
      status_code  = "200"
    }
  }
}

resource "aws_lb_target_group" "internal_load_balancer_target_group" {
  name     = "internal-load-balancer-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = var.vpc_id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

resource "aws_lb_listener_rule" "internal_load_balancer_listener_rule" {
  listener_arn = aws_lb_listener.internal_load_balancer_listener.arn
  priority     = 1

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.internal_load_balancer_target_group.arn
  }

  condition {
    field  = "path-pattern"
    values = ["/"]
  }
}
```

### Notes
- Ensure that the `vpc_id` and `subnet_ids` variables are set to the correct values for your AWS environment.
- Adjust the security group ingress rules as needed to match your specific requirements.
- This configuration assumes that the target instances are already running and registered with the target group. You may need to add additional resources to register instances with the target group.

