### Description
The Terraform program below creates an Application Load Balancer (ALB) that forwards incoming HTTP traffic on port 80 to one or more EC2 instances registered in a target group. The ALB and target group are configured in the `us-west-2` region. The necessary IAM roles and policies are also defined to ensure proper permissions for the load balancer.

### Terraform HCL Program

```hcl
provider "aws" {
  region = "us-west-2"
}

# IAM Role for the Load Balancer
resource "aws_iam_role" "lb_role" {
  name = "alb_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticloadbalancing.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for the Load Balancer
resource "aws_iam_policy" "lb_policy" {
  name        = "alb_policy"
  description = "Policy for ALB to access target groups"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:Describe*",
          "ec2:Get*",
          "ec2:CreateTags",
          "ec2:DeleteTags"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "lb_policy_attach" {
  policy_arn = aws_iam_policy.lb_policy.arn
  role       = aws_iam_role.lb_role.name
}

# Application Load Balancer
resource "aws_lb" "application_load_balancer" {
  name               = "my-application-load-balancer"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.lb_sg.id]
  subnets            = [aws_subnet.public_subnet_1.id, aws_subnet.public_subnet_2.id]

  enable_deletion_protection = false
}

# Security Group for the Load Balancer
resource "aws_security_group" "lb_sg" {
  name        = "alb_sg"
  description = "Security group for ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Target Group
resource "aws_lb_target_group" "target_group" {
  name     = "my-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

# Listener on port 80
resource "aws_lb_listener" "listener_80" {
  load_balancer_arn = aws_lb.application_load_balancer.arn
  port              = 80
  protocol          = "HTTP"
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.target_group.arn
  }
}

# VPC and Subnets (placeholders, replace with actual VPC and subnet IDs)
resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_subnet" "public_subnet_1" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = "us-west-2a"
}

resource "aws_subnet" "public_subnet_2" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
}
```

### Notes
- Ensure that EC2 instances are registered with the target group after they are created.
- Replace the placeholder VPC and subnet configurations with your actual VPC and subnet IDs.
- The IAM role and policy are set up to allow the load balancer to manage its resources. Adjust the policy as needed based on your specific requirements.

