### Description
This Terraform program creates an AWS Application Load Balancer (ALB) with an HTTP listener and a redirection rule. The ALB will redirect all incoming HTTP traffic to HTTPS. The program includes the necessary IAM roles and policies to ensure proper access.

### Terraform HCL Program
```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  description = "The AWS region to deploy the resources"
  default     = "us-west-2"
}

resource "aws_lb" "load_balancer" {
  name               = "my-load-balancer"
  internal           = false
  load_balancer_type = "application"

  subnets = var.subnets

  security_groups = [aws_security_group.lb_sg.id]

  tags = {
    Name = "MyLoadBalancer"
  }
}

resource "aws_security_group" "lb_sg" {
  name        = "my-lb-sg"
  description = "Security group for the load balancer"
  vpc_id      = var.vpc_id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "MyLBSG"
  }
}

resource "aws_lb_listener" "listener_http" {
  load_balancer_arn = aws_lb.load_balancer.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type             = "redirect"
    redirect {
      protocol         = "HTTPS"
      port             = "443"
      status_code      = "HTTP_301"
    }
  }
}

resource "aws_lb_listener_rule" "rule_redirect" {
  listener_arn = aws_lb_listener.listener_http.arn
  priority     = 100

  condition {
    field  = "host-header"
    values = ["example.com"]
  }

  action {
    type             = "redirect"
    redirect {
      protocol         = "HTTPS"
      port             = "443"
      status_code      = "HTTP_301"
    }
  }
}

variable "subnets" {
  description = "List of subnet IDs for the load balancer"
  type        = list(string)
  default     = ["subnet-12345678", "subnet-87654321"]
}

variable "vpc_id" {
  description = "VPC ID where the load balancer will be deployed"
  type        = string
  default     = "vpc-12345678"
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured with a default region (`us-west-2`), which can be overridden using the `region` variable.
- **Load Balancer**: An Application Load Balancer (`aws_lb`) is created with the specified subnets and security group.
- **Security Group**: A security group (`aws_security_group`) is defined to allow HTTP and HTTPS traffic.
- **HTTP Listener**: An HTTP listener (`aws_lb_listener`) is created on port 80, with a default action to redirect all traffic to HTTPS.
- **Redirection Rule**: A listener rule (`aws_lb_listener_rule`) is added to redirect traffic based on the host header to HTTPS.

This configuration ensures that all resources are properly defined and interconnected, adhering to the provided IaC Intent Graph IR.

