### Description
The Terraform program below creates a basic AWS SQL database using Amazon RDS. The configuration includes a provider setup for AWS, specifying a region. It also defines an IAM role with the necessary permissions for the RDS instance. The `aws_db_instance` resource is created with default settings, including a username and password for database access.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

resource "aws_iam_role" "rds_role" {
  name = "rds-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "rds_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSFullAccess"
  role       = aws_iam_role.rds_role.name
}

resource "aws_db_instance" "basic_sql_database" {
  identifier              = "basic-sql-database"
  engine                  = "mysql"
  engine_version          = "8.0"
  instance_class          = "db.t3.micro"
  allocated_storage       = 20
  username                = "admin"
  password                = "securepassword123"
  skip_final_snapshot     = true
  vpc_security_group_ids  = [aws_security_group.default.id]
  db_subnet_group_name    = aws_db_subnet_group.default.name
  iam_database_authentication_enabled = true
  iam_roles               = [aws_iam_role.rds_role.arn]

  depends_on = [
    aws_iam_role_policy_attachment.rds_policy,
  ]
}

resource "aws_security_group" "default" {
  name        = "basic-sql-database-sg"
  description = "Security group for basic SQL database"
  vpc_id      = aws_vpc.default.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_vpc" "default" {
  cidr_block = "10.0.0.0/16"
}

resource "aws_db_subnet_group" "default" {
  name       = "basic-sql-database-subnet-group"
  subnet_ids = aws_subnet.default[*].id
}

resource "aws_subnet" "default" {
