### Description
The Terraform program below creates a memory-optimized PostgreSQL instance using the AWS RDS service. The instance class `db.r6g.large` is chosen for its memory-optimized capabilities. The program includes a provider configuration for AWS, sets up an IAM role for the database instance, and ensures all necessary attributes are specified.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired AWS region
}

variable "db_name" {
  description = "The name of the database"
  default     = "mydatabase"
}

variable "db_username" {
  description = "The username for the database"
  default     = "admin"
}

variable "db_password" {
  description = "The password for the database user"
  default     = "securepassword"
  sensitive   = true
}

variable "allocated_storage" {
  description = "The allocated storage size in gigabytes"
  default     = 20
}

variable "engine_version" {
  description = "The version of the PostgreSQL engine"
  default     = "13.7"
}

resource "aws_iam_role" "rds_iam_role" {
  name = "rds-memory-optimized-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "rds_iam_role_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSFullAccess"
  role       = aws_iam_role.rds_iam_role.name
}

resource "aws_db_instance" "memory_optimized_postgresql" {
  identifier              = "memory-optimized-postgresql"
  instance_class          = "db.r6g.large"
  engine                  = "postgres"
  engine_version          = var.engine_version
  allocated_storage       = var.allocated_storage
  username                = var.db_username
  password                = var.db_password
  db_name                 = var.db_name
  iam_database_authentication_enabled = true
  vpc_security_group_ids  = [aws_security_group.database_sg.id]
  skip_final_snapshot     = true

  tags = {
    Name = "MemoryOptimizedPostgreSQL"
  }
}

resource "aws_security_group" "database_sg" {
  name        = "database-sg"
  description = "Security group for the PostgreSQL database"
  vpc_id      = "vpc-12345678"  # Replace with your VPC ID

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]  # Adjust as needed for security
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}
```

This Terraform configuration sets up a memory-optimized PostgreSQL instance with the specified instance class and other necessary configurations. It also includes an IAM role and security group to ensure proper access and security. Adjust the `vpc_id` and security group rules as needed for your specific environment.

