### Description
The Terraform program below creates a basic AWS RDS instance with `gp3` storage type. The configuration includes the necessary provider setup, IAM role creation for the RDS instance, and the RDS instance itself. The program ensures that all required resources and dependencies are correctly defined and referenced.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"  # Default region, can be changed as needed
}

# IAM Role for RDS
resource "aws_iam_role" "rds_instance_role" {
  name = "rds-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for RDS
resource "aws_iam_policy" "rds_instance_policy" {
  name        = "rds-instance-policy"
  description = "Policy for RDS instance"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:*"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach IAM Policy to IAM Role
resource "aws_iam_role_policy_attachment" "rds_instance_policy_attachment" {
  policy_arn = aws_iam_policy.rds_instance_policy.arn
  role       = aws_iam_role.rds_instance_role.name
}

# Basic RDS Instance
resource "aws_db_instance" "basic_rds_instance" {
  identifier              = "basic-rds-instance"
  engine                  = "mysql"
  engine_version          = "8.0"
  instance_class          = "db.t3.micro"
  allocated_storage       = 20
  storage_type            = "gp3"
  username                = "admin"
  password                = "password123"
  parameter_group_name    = "default.mysql8.0"
  db_subnet_group_name    = "default"
  vpc_security_group_ids  = ["sg-0123456789abcdef0"]  # Replace with your security group ID
  skip_final_snapshot     = true
  iam_database_authentication_enabled = true
  iam_roles               = [aws_iam_role.rds_instance_role.name]
}
```

### Notes
- Ensure that the `vpc_security_group_ids` and other sensitive information like `username` and `password` are replaced with appropriate values.
- The `region` in the provider configuration can be changed to suit your needs.
- The IAM role and policy are created to demonstrate best practices, but they may need to be adjusted based on specific requirements.

