### Description
This Terraform program creates an AWS Virtual Private Cloud (VPC) with two public subnets. It also sets up an Internet Gateway and associates it with the VPC. A route table is created for the public subnets, and a route is added to allow internet access via the Internet Gateway. The subnets are then associated with this route table.

### Terraform HCL Program
```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_internet_gateway" "main_igw" {
  vpc_id = aws_vpc.main_vpc.id
}

resource "aws_route_table" "public_route_table" {
  vpc_id = aws_vpc.main_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main_igw.id
  }
}

resource "aws_subnet" "public_subnet_1" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone       = "us-west-2a"
}

resource "aws_subnet" "public_subnet_2" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = true
  availability_zone       = "us-west-2b"
}

resource "aws_route_table_association" "subnet_1_route_table_assoc" {
  subnet_id      = aws_subnet.public_subnet_1.id
  route_table_id = aws_route_table.public_route_table.id
}

resource "aws_route_table_association" "subnet_2_route_table_assoc" {
  subnet_id      = aws_subnet.public_subnet_2.id
  route_table_id = aws_route_table.public_route_table.id
}
```

### Explanation
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **VPC**: A VPC is created with a CIDR block of `10.0.0.0/16`.
- **Internet Gateway**: An Internet Gateway is created and attached to the VPC.
- **Route Table**: A route table is created for the VPC and a route is added to allow traffic to `0.0.0.0/0` via the Internet Gateway.
- **Public Subnets**: Two public subnets are created within the VPC, each in different availability zones (`us-west-2a` and `us-west-2b`), with CIDR blocks `10.0.1.0/24` and `10.0.2.0/24`, respectively. Public IP mapping is enabled for instances launched in these subnets.
- **Route Table Associations**: Each public subnet is associated with the public route table.

