  vpc_id = var.vpc_id
}

resource "aws_egress_only_internet_gateway_attachment" "egress_only_internet_gateway_attachment_pike" {
  egress_only_internet_gateway_id = aws_egress_only_internet_gateway.egress_only_internet_gateway_pike.id
  vpc_id                          = var.vpc_id
}

resource "aws_tags" "tags_for_egress_only_internet_gateway_pike" {
  resource_id = aws_egress_only_internet_gateway.egress_only_internet_gateway_pike.id
  tags = {
    permissions = "true"
  }
}
```

### Notes
- Ensure the `vpc_id` variable is provided when deploying this configuration.
- The provider configuration specifies the AWS region. You can change it to your desired region.
- The program uses Terraform's built-in `aws_tags` resource to apply tags to the egress-only internet gateway.

